/* HIDDEN UNTIL ASKED FOR — so Status is on screen without scrolling
   (docs/unified-view/2-layouts.md §5). All are in the column menu. */
export const DEFAULT_HIDDEN: RequestColumnKey[] = ["po", "repeats", "updated"];

/* THE ORDERS LIST'S COLUMNS — no delivery-flags column. */
export const REQUEST_LIST_COLUMNS = REQUEST_COLUMNS.filter((c) => c.key !== "flags");

export const REQUEST_SEARCH_FIELDS = REQUEST_COLUMNS.filter((c) => c.label).map((c) => ({
  key: c.key,
  label: c.label,
}));

/** What each column PRINTS, as text a header box or a search can match. */
export function requestColumnText(r: OrderRequest, key: RequestColumnKey): string {
  switch (key) {
    case "requestNo": {
      const s = sentOn(r);
      return `${r.requestNo} ${s ? DATE_FMT.format(new Date(s)) : ""}`;
    }
    case "shipTo":
      return r.shipTo;
    case "assets":
      return assetNames(r).join(", ");
    case "products":
      return productNames(r).join(", ");
    case "quantity":
      return quantityText(r.lines);
    case "date":
      return r.date ? `${printKey(r.date)} ${windowText(r)}` : "";
    case "repeats":
      return r.recurring ? r.frequency : "";
    case "po":
      return r.po;
    case "flags":
      return r.flags.map((f) => f.kind).join(", ");
    case "documents":
      return r.documents.map((d) => d.name).join(", ");
    case "status":
      return r.status;
    case "updated":
      return DATE_FMT.format(new Date(r.updatedAt));
    default:
      return "";
  }
}

export function matchesRequest(r: OrderRequest, q: string): boolean {
  return REQUEST_SEARCH_FIELDS.map((f) => requestColumnText(r, f.key))
    .join(" ")
    .toLowerCase()
    .includes(q);
}

export interface RequestSort {
  key: RequestColumnKey;
  dir: "asc" | "desc";
}

function sortValue(r: OrderRequest, key: RequestColumnKey): string | number {
  switch (key) {
    case "quantity":
      return quantityOf(r.lines).gal;
    case "date":
      return `${r.date}-${String(r.windowStart).padStart(4, "0")}`;
    case "status":
      return statusRank(r.status);
    case "flags":
      return r.flags.length;
    case "documents":
      return r.documents.length;
    case "updated":
      return r.updatedAt;
    default:
      return requestColumnText(r, key).toLowerCase();
  }
}

export function sortRequests(rows: OrderRequest[], sort: RequestSort | null): OrderRequest[] {
  /* Unsorted, the newest change is on top. */
  if (!sort) return [...rows].sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  const dir = sort.dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const x = sortValue(a, sort.key);
    const y = sortValue(b, sort.key);
    return (x < y ? -1 : x > y ? 1 : 0) * dir;
  });
}

/* -------------------------------------------------------------- store ---- */

/*
  ONE OWNER FOR THE REQUESTS — outlives the screen, so a request made here
  is still here after visiting another page. The setter writes the activity
  log, as `quoteStore` does.
*/
/*
  THE SEED'S FILLS, TUNED (Pavan, 2026-10-22): every order fills (or, once
  delivered, filled) its monitored tanks to somewhere between 45% and 94% —
  but for ONE overload (a big tank sent 120%) and ONE that stays low (a near-
  empty tank sent too little, ~18%). Quantities only; the tanks are as seeded.
  Plain arithmetic here — the tank helpers further down are not defined yet
  when this runs.
*/
/** `examples` off: the ideal fills only — for orders made later (a rule's). */
function tuneFulfilment(rows: OrderRequest[], examples = true): OrderRequest[] {
  const today = startOfDay(new Date()).getTime();
  let k = 0;
  let overload = !examples;
  let low = !examples;
  return rows.map((r) => {
    if (!r.date) return r;
    /* DELIVERED — refilled to 45–94%: the gallons that sum to it, and the
       monitor's reading after, from the level when ordered (as the seed). */
    if (DELIVERED.includes(r.status)) {
      const made = r.audit?.[0]?.at ? startOfDay(new Date(r.audit[0].at)).getTime() : today;
      const span = Math.max(0, Math.round((new Date(`${r.date}T00:00`).getTime() - made) / 86_400_000));
      return {
        ...r,
        lines: r.lines.map((l) => {
          const a = assetById(l.assetId);
          if (!a?.monitor || !a.capacity || l.topOff || l.levelAtOrder === undefined) return l;
          const atGal = Math.round((l.levelAtOrder / 100) * a.capacity);
          const left = atGal - Math.min(atGal, a.dailyUse * span);
          const target = 45 + ((k++ * 17) % 50);
          const gal = Math.max(10, Math.round(((target / 100) * a.capacity - left) / 10) * 10);
          return { ...l, gal, levelAfter: Math.min(100, Math.round(((left + gal) / a.capacity) * 100)) };
        }),
      };
    }
    const days = Math.max(0, Math.round((new Date(`${r.date}T00:00`).getTime() - today) / 86_400_000));
    return {
      ...r,
      lines: r.lines.map((l) => {
        const a = assetById(l.assetId);
        if (!a?.monitor || !a.capacity || l.topOff) return l;
        const left = Math.max(0, Math.round((a.level / 100) * a.capacity) - a.dailyUse * days);
        let target = 45 + ((k++ * 17) % 50);
        if (!overload && a.capacity >= 1000 && left / a.capacity < 0.8) {
          overload = true;
          target = 120;
        } else if (!low && left / a.capacity < 0.1) {
          low = true;
          target = 18;
        }
        return { ...l, gal: Math.max(10, Math.round(((target / 100) * a.capacity - left) / 10) * 10) };
      }),
    };
  });
}

let requests: OrderRequest[] = tuneFulfilment(SEED_REQUESTS);
const listeners = new Set<() => void>();
const emit = () => listeners.forEach((l) => l());
const subscribe = (l: () => void) => {
  listeners.add(l);
  return () => listeners.delete(l);
};

export function useRequests(): OrderRequest[] {
  return React.useSyncExternalStore(subscribe, () => requests);
}

export function updateRequest(id: string, patch: Partial<OrderRequest>, change?: string) {
  const at = new Date().toISOString();
  requests = requests.map((r) =>
    r.id !== id
      ? r
      : {
          ...r,
          ...patch,
          updatedAt: at,
          /* MEANINGFUL EVENTS ONLY — a draft's typing is not logged. */
          audit: change ? [...(r.audit ?? []), { at, by: PORTAL_ACTOR, changes: [change] }] : r.audit,
        }
  );
  emit();
}

/** A blank Draft, made the moment Create Order is pressed. */
export function createRequest(recurring = false): OrderRequest {
  const n = nextRequestNo();
  const at = new Date().toISOString();
  const r: OrderRequest = {
    id: `ord-new-${n}`,
    requestNo: `ORD-${n}`,
    /* One ship-to on the account is simply that ship-to. */
    shipTo: SHIP_TOS.length === 1 ? SHIP_TOS[0].name : "",
    lines: [blankLine()],
    date: "",
    windowStart: 8 * 60,
    windowEnd: 12 * 60,
    preferred: [],
    po: "",
    instructions: "",
    recurring,
    frequency: recurring ? FREQUENCIES[2] : "",
    endDate: "",
    status: "Draft",
    flags: [],
    documents: [],
    updatedAt: at,
    audit: [{ at, by: PORTAL_ACTOR, changes: ["Order created"] }],
  };
  requests = [r, ...requests];
  emit();
  return r;
}

/** Requests a rule made — added once each (their id is rule + date). */
export function insertRequests(made: OrderRequest[]) {
  const have = new Set(requests.map((r) => r.id));
  const fresh = tuneFulfilment(made.filter((r) => !have.has(r.id)), false);
  if (fresh.length === 0) return;
  requests = [...fresh, ...requests];
  emit();
}

/** The next order number — for a new order and a rule's orders. */
export function nextRequestNo() {
  return Math.max(FIRST_REQUEST_NO - 1, ...requests.map((r) => Number(r.requestNo.slice(4)) || 0)) + 1;
}

/** Every request, as it is now — for reads outside React. */
export const allRequests = () => requests;

/*
  DUPLICATE (Pavan, 2026-10-13 — "Duplicate", not "Reorder"): a new Draft
  with the same ship-to, tanks, products, quantities, window, recurrence and
  instructions. The date is left blank — the old one has usually passed.
*/
export function duplicateRequest(id: string): OrderRequest | null {
  const src = requests.find((r) => r.id === id);
  if (!src) return null;
  const r = createRequest();
  updateRequest(r.id, {
    shipTo: src.shipTo,
    lines: src.lines.map((l) => ({ ...l })),
    windowStart: src.windowStart,
    windowEnd: src.windowEnd,
    preferred: src.preferred.map((p) => ({ ...p })),
    instructions: src.instructions,
    recurring: src.recurring,
    frequency: src.frequency,
  });
  const at = new Date().toISOString();
  requests = requests.map((x) =>
    x.id === r.id
      ? { ...x, audit: [{ at, by: PORTAL_ACTOR, changes: [`Duplicated from ${src.requestNo}`] }] }
      : x
  );
  emit();
  return requests.find((x) => x.id === r.id)!;
}

/** A ship-to renamed — its requests follow it, so none loses its site. */
export function renameShipToInRequests(from: string, to: string) {
  if (from === to) return;
  requests = requests.map((r) => (r.shipTo === from ? { ...r, shipTo: to } : r));
  emit();
}

/** Drop an untouched new draft, closed unfilled. */
export function discardRequest(id: string) {
  requests = requests.filter((r) => r.id !== id);
  emit();
}

/*
  ORDER THE REST (Pavan, 2026-10-15 — PRD FR-28): a new request for the
  gallons a partial delivery left, to the same ship-to and tanks, split over
  its lines in proportion; the date is left to choose.
*/
export function orderTheRest(id: string): OrderRequest | null {
  const src = requests.find((r) => r.id === id);
  if (!src || !src.undeliveredGal) return null;
  const r = duplicateRequest(id);
  if (!r) return null;
  const asked = src.lines.reduce((t, l) => t + (l.topOff ? 0 : l.gal), 0) || 1;
  updateRequest(r.id, {
    recurring: false,
    frequency: "",
    lines: src.lines.map((l) => ({ ...l, topOff: false, gal: Math.round((src.undeliveredGal! * (l.gal || asked)) / asked) })),
    instructions: `The rest of ${src.requestNo} (${src.undeliveredGal.toLocaleString()} gal not delivered).`,
  });
  const at = new Date().toISOString();
  requests = requests.map((x) =>
    x.id === r.id ? { ...x, audit: [{ at, by: PORTAL_ACTOR, changes: [`The rest of ${src.requestNo}`] }] } : x
  );
  emit();
  return requests.find((x) => x.id === r.id)!;
}

/* -------------------------------------------------------- level bands --- */

/*
  TANK LEVEL BANDS (Pavan, 2026-10-17) — set on the monitor, read here:
  10% or lower Urgent (red, blinking), under 50 Low (red), under 80 Moderate
  (yellow), 80 and above Sufficient (green). Batteries under 20% are low.
*/
export type LevelBand = "Urgent" | "Low" | "Moderate" | "Sufficient";
export const levelBand = (pct: number): LevelBand =>
  pct <= 10 ? "Urgent" : pct < 50 ? "Low" : pct < 80 ? "Moderate" : "Sufficient";
export const LOW_BATTERY = 20;

/** Preferred windows kept inside the delivery window — trimmed, empties dropped. */
export const clampPreferred = (p: TimeSpan[], start: number, end: number): TimeSpan[] =>
  p
    .map((x) => ({ start: Math.max(start, Math.min(x.start, end)), end: Math.min(end, Math.max(x.end, start)) }))
    .filter((x) => x.end > x.start);

/* -------------------------------------------------- tank arithmetic ---- */

/*
  WHAT THE MONITOR TELLS AN ORDER (Pavan, 2026-10-17). From the level, the
  size and the day-to-day usage:

    in the tank now      = level% × capacity
    days to empty        = in the tank now ÷ daily use
    left at delivery     = in the tank now − daily use × days until delivery
    SUGGESTED            = capacity − left at delivery   (full on the day)
    after delivery       = (left at delivery + ordered) ÷ capacity

  e.g. 10,000 gal tank at 20% (2,000), 400 gal/day, delivery in 2 days:
  1,200 left → suggested 8,800; ordering 6,000 makes it 72%.
*/
export const galNow = (a: Asset) => Math.round((a.level / 100) * a.capacity);
export const daysToEmpty = (a: Asset): number | null =>
  a.monitor && a.dailyUse > 0 ? Math.floor(galNow(a) / a.dailyUse) : null;
/** Whole days from today to a `YYYY-MM-DD` — 0 for today, unset or past. */
export const daysUntil = (key: string) => {
  if (!key) return 0;
  const d = new Date(`${key}T00:00`);
  const t = new Date();
  t.setHours(0, 0, 0, 0);
  return Math.max(0, Math.round((d.getTime() - t.getTime()) / 86_400_000));
};
export const galAtDelivery = (a: Asset, days: number) => Math.max(0, galNow(a) - a.dailyUse * days);
/** Fill to full on the delivery day, to the nearest 10 gal. */
export const suggestedGal = (a: Asset, days: number) =>
  Math.max(0, Math.round((a.capacity - galAtDelivery(a, days)) / 10) * 10);
/* NOT CAPPED (Pavan, 2026-10-22): 1,200 gal into a 1,000 gal tank reads
   120% — the overload is the figure, not hidden behind "full". */
export const pctAfterDelivery = (a: Asset, days: number, gal: number, topOff: boolean) =>
  topOff ? 100 : Math.round(((galAtDelivery(a, days) + gal) / a.capacity) * 100);

/**
 * WHEN THE ORDER WAS SENT TO THE TENANT (Pavan, 2026-10-19) — shown under its
 * number; null while it is a draft. The PLANNED DATE (`date`) is a different
 * thing: when the customer wants it delivered.
 */
export function sentOn(r: OrderRequest): string | null {
  if (r.status === "Draft") return null;
  const sent = r.audit?.find((e) => e.changes.some((c) => c === "Order submitted" || c === "Request submitted"));
  return sent?.at ?? r.audit?.[0]?.at ?? null;
}

/** THE CUSTOMER ASKS FOR A CHANGE to a sent order (Pavan, 2026-10-19). */
export const CHANGE_KINDS = ["Planned date", "Delivery window", "Quantity", "Tanks or products", "Cancel the order", "Something else"];
export function requestChange(id: string, what: string, note: string) {
  const o = requests.find((x) => x.id === id);
  if (!o) return;
  updateRequest(
    id,
    {
      changeRequest: { kind: what === "Cancel the order" ? "cancel" : "change", what, note, at: new Date().toISOString() },
    },
    `Change requested · ${what}${note ? ` — ${note}` : ""}`
  );
}

/** The list's rows: every order, and the record a press opens is its own. */
export function orderListRows(all: OrderRequest[]): OrderRequest[] {
  return all;
}

/* ---------------------------------------------- dashboard attention ---- */

/** STILL TO ARRIVE — sent, not yet delivered. */
export const NOT_DELIVERED: RequestStatus[] = ["Unassigned", "Scheduled", "Out for delivery"];
/** RUNNING LATE (Anirudh, 2026-10-17): its planned date has passed and it is
    not delivered. There is no ETA to judge it by yet. */
export const isRunningLate = (r: OrderRequest) => NOT_DELIVERED.includes(r.status) && !!r.date && r.date < todayKey();
/** NO PROOF OF DELIVERY: delivered, but no delivery ticket on it. */
export const lacksPod = (r: OrderRequest) =>
  DELIVERED.includes(r.status) && !r.documents.some((d) => d.kind === "Delivery ticket");
/** ON HOLD FOR CREDIT — a yes/no from the tenant; no balance. */
export const onCreditHold = (r: OrderRequest) => r.flags.some((f) => f.kind === "Credit hold");

export { scheduleSummary } from "../unified-view/threepl/RuleFrequency";

import { TriangleAlert } from "lucide-react";
import * as React from "react";
import { Pill } from "@/components/ui/pill";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { cn } from "@/lib/utils";

/**
 * Breakdown content — what a "+N" chip or a total opens.
 *
 * The anatomy is the DS's own, copied from `InvoiceCard` (Figma "Invoice"
 * 27599:62303) — the only hover-card content pattern in the DS, and the one the
 * DS DataTable puts in its Amount column:
 *
 *   flex w-full flex-col gap-4
 *     h4  text-base font-semibold          ← title, foreground (not a muted label)
 *     border-t border-dashed border-border  ← rule under the title
 *     flex flex-col gap-1                   ← detail rows
 *       flex items-center justify-between text-sm text-muted-foreground
 *       …value spans carry tabular-nums
 *     border-t border-dashed border-border  ← rule before the total
 *     flex items-center justify-between text-base font-semibold  ← total
 *
 * The container keeps `HoverCardContent`'s default `p-4`; width is the only
 * override, which is the one the DS itself makes (`w-[380px]` for the Invoice
 * card). Rows with no `value` render as a plain list (the products case).
 */
export interface BreakdownRow {
  label: string;
  /** Omit for a label-only list. */
  value?: string;
  /**
   * A second line under the label — what the row carries (Pavan, 2026-10-14:
   * an asset's products under its name, its capacity as the value).
   */
  sub?: string;
}

/**
 * A GROUPED TABLE instead of rows (Pavan, 2026-10-14 — a ship-to's products,
 * each with its assets, their type and capacity). Same card: title, dashed
 * rule, the card's own type sizes; a header row, then a band per group.
 */
export interface BreakdownTable {
  columns: { label: string; align?: "left" | "right" }[];
  groups: { label: string; rows: string[][] }[];
}

export interface BreakdownCardProps {
  title: string;
  rows: BreakdownRow[];
  table?: BreakdownTable;
  /** Renders the dashed rule + bold total row. Omit to end after the rows. */
  total?: { label: string; value: string };
  /** WARNINGS, after the total (Pavan, 2026-10-20) — red, an alert mark each:
      what the figure means will go wrong. */
  warnings?: string[];
}

export function BreakdownCard({ title, rows, table, total, warnings }: BreakdownCardProps) {
  return (
    <div className="flex w-full flex-col gap-4">
      <h4 className="text-base font-semibold">{title}</h4>
      <div className="border-t border-dashed border-border" />

      {table && (
        <table className="w-full table-fixed text-sm">
          <thead>
            <tr className="text-xs text-muted-foreground">
              {table.columns.map((c) => (
                <th key={c.label} className={cn("pb-1.5 font-medium", c.align === "right" ? "" : "text-left")}>
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          {table.groups.map((g) => (
            <tbody key={g.label}>
              {/* THE GROUP — its name on a quiet band across the table; an
                  unnamed group (a plain table) has no band. */}
              {g.label && <tr>
                <td colSpan={table.columns.length} className="pt-2">
                  <span className="block rounded-sm bg-fp-table-header px-2 py-1 text-xs font-semibold text-foreground">
                    {g.label}
                  </span>
                </td>
              </tr>}
              {g.rows.map((r, i) => (
                <tr key={i} className="text-muted-foreground">
                  {r.map((cell, j) => (
                    <td
                      key={j}
                      /* THE NAME TRUNCATES; the rest wrap, so a list of
                         products is read whole. */
                      className={cn(
                        "py-1 pr-2 align-top",
                        j === 0 ? "truncate pl-2 text-foreground" : "break-words",
                        table.columns[j]?.align === "right" && "text-right tabular-nums"
                      )}
                      title={cell}
                    >
                      {cell}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          ))}
        </table>
      )}

      <div className="flex flex-col gap-1">
        {rows.map((row, i) => (
          <div
            key={`${row.label}-${i}`}
            className={cn(
              "flex justify-between gap-6 text-sm text-muted-foreground",
              row.sub ? "items-baseline py-0.5" : "items-center"
            )}
          >
            {row.sub ? (
              <span className="flex min-w-0 flex-col">
                <span className="truncate text-foreground">{row.label}</span>
                <span className="text-xs">{row.sub}</span>
              </span>
            ) : (
              <span className="min-w-0 truncate">{row.label}</span>
            )}
            {row.value && (
              <span className="shrink-0 tabular-nums">{row.value}</span>
            )}
          </div>
        ))}
      </div>

      {total && (
        <>
          <div className="border-t border-dashed border-border" />
          <div className="flex items-center justify-between gap-6 text-base font-semibold">
            <span>{total.label}</span>
            <span className="tabular-nums">{total.value}</span>
          </div>
        </>
      )}

      {warnings && warnings.length > 0 && (
        <ul className="flex flex-col gap-1.5">
          {warnings.map((w) => (
            <li key={w} className="flex items-start gap-2 text-sm text-status-failed">
              <TriangleAlert aria-hidden className="mt-0.5 size-4 shrink-0" />
              <span>{w}</span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/*
  ONE WAY TO OPEN A BREAKDOWN, EVERYWHERE (Pavan, 2026-10-14). A "+N" chip —
  or, where the whole cell IS the figure (a quantity), the figure — opens the
  card ON CLICK, above the cell. Not hover: touch cannot hover, and a card
  that appears under a passing pointer is one nobody asked for. The press
  stays in the cell: a row that opens its record on click must not open it
  as well.
*/
export function BreakdownPopover({
  trigger,
  label,
  card,
  width = 280,
  align = "start",
  className,
}: {
  /** The pressable face — a chip, or the figure. */
  trigger: React.ReactNode;
  /** What the press does, for a screen reader. */
  label: string;
  card: BreakdownCardProps;
  width?: number;
  align?: "start" | "end";
  className?: string;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          onClick={(e) => e.stopPropagation()}
          className={cn(
            "shrink-0 cursor-pointer rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
            className
          )}
        >
          {trigger}
        </button>
      </PopoverTrigger>
      <PopoverContent
        align={align}
        side="top"
        style={{ width }}
        className="max-h-96 overflow-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <BreakdownCard {...card} />
      </PopoverContent>
    </Popover>
  );
}

/** The "+N" chip that opens a breakdown. */
export function OverflowChip({
  count,
  label,
  card,
  width,
}: {
  count: number;
  label: string;
  card: BreakdownCardProps;
  width?: number;
}) {
  return (
    <BreakdownPopover
      label={label}
      card={card}
      width={width}
      trigger={<Pill className="cursor-pointer tabular-nums">+{count}</Pill>}
    />
  );
}

import { ChevronLeft, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { DateField } from "@/components/ui/date-picker";
import { formatFullDate, startOfDay } from "./data";

/**
 * Delivery-date filter — ‹ date › stepper with a calendar picker.
 *
 * Defaults to today and steps a day at a time in either direction, so past and
 * future dates are both reachable. The pill opens the shared date picker in
 * its one-date form — Today is its first preset.
 *
 * Sits in the toolbar rather than inside the Filters panel: it is the one filter
 * whose current value has to stay legible at a glance, since every row on screen
 * is scoped by it.
 */
export interface DateFilterProps {
  value: Date;
  onChange: (next: Date) => void;
}

export function DateFilter({ value, onChange }: DateFilterProps) {
  const step = (days: number) => {
    const next = new Date(value);
    next.setDate(next.getDate() + days);
    onChange(startOfDay(next));
  };

  return (
    <div className="flex items-center gap-1">
      <Button
        variant="outline"
        size="icon-sm"
        aria-label="Previous day"
        onClick={() => step(-1)}
      >
        <ChevronLeft />
      </Button>

      {/* THE SHARED PICKER, one date (DS ui §10p). */}
      <DateField value={value} onChange={(d) => d && onChange(startOfDay(d))} align="end">
        <Button
          variant="outline"
          size="sm"
          aria-label={`Delivery date: ${formatFullDate(value)}. Pick a date`}
        >
          {formatFullDate(value)}
        </Button>
      </DateField>

      <Button
        variant="outline"
        size="icon-sm"
        aria-label="Next day"
        onClick={() => step(1)}
      >
        <ChevronRight />
      </Button>
    </div>
  );
}

import * as React from "react";
import { TriangleAlert, X } from "lucide-react";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { SheetField } from "@/components/side-sheet/parts";
import { HangingAdd } from "./HangingAdd";
import { Slider } from "@/components/ui/slider";
import {
  formatSpan,
  formatWindow,
} from "@/components/form-layout/TimeWindowSlider";
import { cn } from "@/lib/utils";
/** A stretch of the day, minutes from midnight. */
export interface TimeSpan {
  start: number;
  end: number;
}

/*
  DELIVERY WINDOW & PREFERRED TIME (Pavan, 2026-10-20, after his reference;
  shared by every module's order sheet) —
  ONE day, drawn once, full width. The delivery window is the range on the
  track; each preferred time is a light-blue bar under it, on the same scale,
  with dashed lines up to the track and its two times under its ends. A bar
  is moved by dragging it, sized by dragging an end, and removed with its ✕;
  the + hanging off the box (as a table's add) puts a new one in the
  window's next free stretch.

  Keyboard: a bar takes focus — ← → move it half an hour, Shift + ← → move
  its end, Delete removes it.

  NEVER OVERLAPPING (Pavan, 2026-10-20) — a bar stops at its neighbours,
  whichever way it is dragged or typed; with no free half hour left in the
  window, + says to delete or adjust one first. PRESS A TIME under a bar to
  type its start and end to the minute — the slider and the box are the same
  value.
*/

const DAY = 24 * 60;
const STEP = 30;
/** Every third hour labelled, as the reference. */
const TICKS = [0, 3, 6, 9, 12, 15, 18, 21, 24];
const pct = (m: number) => `${(m / DAY) * 100}%`;
/** `4a`, `1:30p` — the reference's short times. */
const short = (m: number) => {
  const h24 = Math.floor((((m % DAY) + DAY) % DAY) / 60);
  const mm = m % 60;
  const h = h24 % 12 === 0 ? 12 : h24 % 12;
  return `${h}${mm ? `:${String(mm).padStart(2, "0")}` : ""}${h24 < 12 ? "a" : "p"}`;
};
const hhmm = (m: number) =>
  `${String(Math.floor(m / 60)).padStart(2, "0")}:${String(m % 60).padStart(2, "0")}`;
const fromHhmm = (v: string) => {
  const m = v.match(/^(\d{1,2}):(\d{2})$/);
  return m ? Number(m[1]) * 60 + Number(m[2]) : null;
};
const tick = (h: number) =>
  h === 0 || h === 24
    ? "12a"
    : h === 12
      ? "12p"
      : h < 12
        ? `${h}a`
        : `${h - 12}p`;

type Drag = {
  i: number;
  mode: "move" | "start" | "end";
  grab: number;
  from: TimeSpan;
};

export function DeliveryWindowTimeline({
  start,
  end,
  onWindowChange,
  preferred,
  onPreferredChange,
  disabled,
  required,
  label = "Delivery window & preferred time",
}: {
  /** The field's label, outside the box — every module says it its own way. */
  label?: string;
  /** The delivery window, minutes from midnight. */
  start: number;
  end: number;
  onWindowChange: (start: number, end: number) => void;
  preferred: TimeSpan[];
  onPreferredChange: (next: TimeSpan[]) => void;
  disabled?: boolean;
  required?: boolean;
}) {
  const scale = React.useRef<HTMLDivElement>(null);
  const [width, setWidth] = React.useState(0);
  React.useLayoutEffect(() => {
    if (!scale.current) return;
    const ro = new ResizeObserver(([e]) => setWidth(e.contentRect.width));
    ro.observe(scale.current);
    return () => ro.disconnect();
  }, []);
  const drag = React.useRef<Drag | null>(null);
  /* THE NEW BAR TAKES FOCUS (DS ui §10f) — so ← → move it at once. */
  const [focusNew, setFocusNew] = React.useState<number | null>(null);
  /** The bar whose times are being typed, and which box opened it. */
  const [edit, setEdit] = React.useState<{
    i: number;
    field: "start" | "end";
  } | null>(null);
  const [full, setFull] = React.useState(false);
  React.useEffect(() => setFull(false), [preferred, start, end]);

  /* THE ROOM A BAR HAS — from its neighbours (or the window) either side. */
  const room = (i: number, at: TimeSpan) => {
    const others = preferred.filter((_, j) => j !== i);
    return {
      lo: Math.max(
        start,
        ...others.filter((q) => q.end <= at.start).map((q) => q.end),
      ),
      hi: Math.min(
        end,
        ...others.filter((q) => q.start >= at.end).map((q) => q.start),
      ),
    };
  };

  const toMin = (clientX: number) => {
    const r = scale.current!.getBoundingClientRect();
    return Math.round((((clientX - r.left) / r.width) * DAY) / STEP) * STEP;
  };
  const clampSpan = (
    i: number,
    at: TimeSpan,
    s: number,
    e: number,
    mode: Drag["mode"],
  ): TimeSpan => {
    const { lo, hi } = room(i, at);
    if (mode === "move") {
      const len = e - s;
      const a = Math.min(Math.max(s, lo), hi - len);
      return { start: a, end: a + len };
    }
    if (mode === "start")
      return { start: Math.min(Math.max(s, lo), e - STEP), end: e };
    return { start: s, end: Math.max(Math.min(e, hi), s + STEP) };
  };
  const setAt = (i: number, p: TimeSpan) =>
    onPreferredChange(preferred.map((x, j) => (j === i ? p : x)));

  const onDown = (e: React.PointerEvent, i: number, mode: Drag["mode"]) => {
    if (disabled) return;
    e.preventDefault();
    e.stopPropagation();
    (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
    drag.current = { i, mode, grab: toMin(e.clientX), from: preferred[i] };
  };
  const onMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    const delta = toMin(e.clientX) - d.grab;
    const s = d.mode === "end" ? d.from.start : d.from.start + delta;
    const en = d.mode === "start" ? d.from.end : d.from.end + delta;
    setAt(d.i, clampSpan(d.i, d.from, s, en, d.mode));
  };
  const onUp = () => (drag.current = null);

  const add = () => {
    /* THE FIRST FREE STRETCH OF HALF AN HOUR OR MORE, up to two hours. */
    const taken = [...preferred].sort((a, b) => a.start - b.start);
    let at = start;
    for (const q of [...taken, { start: end, end }]) {
      if (q.start - at >= STEP) {
        setFocusNew(preferred.length);
        onPreferredChange([
          ...preferred,
          { start: at, end: Math.min(q.start, at + 120) },
        ]);
        return;
      }
      at = Math.max(at, q.end);
    }
    setFull(true);
  };
  /* A TYPED PAIR — what's wrong with it, or null when it fits. */
  const problem = (i: number, s: number | null, e: number | null) => {
    if (s === null || e === null) return "Enter both times";
    if (e <= s) return "End after the start";
    if (s < start || e > end)
      return `Inside the delivery window, ${formatWindow(start, end)}`;
    if (preferred.some((q, j) => j !== i && s < q.end && e > q.start))
      return "Overlaps another preferred time";
    return null;
  };
  const onKey = (e: React.KeyboardEvent, i: number) => {
    const p = preferred[i];
    const by =
      e.key === "ArrowRight" ? STEP : e.key === "ArrowLeft" ? -STEP : 0;
    if (by) {
      e.preventDefault();
      setAt(
        i,
        e.shiftKey
          ? clampSpan(i, p, p.start, p.end + by, "end")
          : clampSpan(i, p, p.start + by, p.end + by, "move"),
      );
    } else if (e.key === "Delete" || e.key === "Backspace") {
      e.preventDefault();
      onPreferredChange(preferred.filter((_, j) => j !== i));
    }
  };

  const has = preferred.length > 0;
  const canAdd = !disabled && end - start >= STEP;
  return (
    /* THE LABEL OUTSIDE, as every field's (Pavan, 2026-10-20); the unit in
       the input's own outline; the add hangs off its corner, as a table's. */
    <SheetField label={label} required={required}>
      <div className="flex flex-col">
        <div
          className={cn(
            "flex flex-col gap-2 rounded-md border border-input bg-fp-surface-1b px-4 pt-3 pb-3 transition-[color,box-shadow] focus-within:border-ring focus-within:ring-2 focus-within:ring-ring/50 dark:bg-fp-field-fill",
            canAdd && "rounded-bl-none",
          )}
        >
          <div className="flex min-w-0 items-baseline justify-between gap-3">
            <span className="text-sm whitespace-nowrap tabular-nums text-foreground">
              {formatWindow(start, end)}
            </span>
            <span className="min-w-0 truncate text-xs text-muted-foreground">
              {formatSpan(start, end)}
            </span>
          </div>

          {/* THE SCALE — track, hours, then the preferred bars on the same day. */}
          <div
            ref={scale}
            className={cn("relative", has ? "h-[78px]" : "h-10")}
            onPointerMove={onMove}
            onPointerUp={onUp}
          >
            <Slider
              className="absolute inset-x-0 top-0 h-5 [&_[data-slot=slider-thumb]]:size-5 [&_[data-slot=slider-track]]:h-2.5"
              aria-label="Delivery window"
              min={0}
              max={DAY}
              step={STEP}
              minStepsBetweenThumbs={60 / STEP}
              value={[start, end]}
              disabled={disabled}
              onValueChange={([a, b]) => onWindowChange(a, b)}
            />
            <div
              aria-hidden
              className="absolute inset-x-0 top-6 h-3.5 select-none"
            >
              {TICKS.map((h, i) => (
                <span
                  key={h}
                  className={cn(
                    "absolute top-0 text-xs leading-none tabular-nums text-muted-foreground",
                    i === 0 && "left-0",
                    i === TICKS.length - 1 && "right-0",
                    i > 0 && i < TICKS.length - 1 && "-translate-x-1/2",
                  )}
                  style={
                    i === 0 || i === TICKS.length - 1
                      ? undefined
                      : { left: `${(h / 24) * 100}%` }
                  }
                >
                  {tick(h)}
                </span>
              ))}
            </div>

            {preferred.map((p, i) => {
              /* A NARROW BAR PUTS ITS TIMES OUTSIDE ITS ENDS, so they never meet. */
              const narrow =
                width > 0 && ((p.end - p.start) / DAY) * width < 84;
              /* WHERE TWO BARS MEET, THE TIME IS PRINTED ONCE — by the later bar. */
              const shared = preferred.some(
                (q, j) => j !== i && q.start === p.end,
              );
              return (
                <React.Fragment key={i}>
                  {[p.start, p.end].map((m, k) => (
                    <span
                      key={k}
                      aria-hidden
                      className="absolute top-4 h-7 border-l border-dashed border-muted-foreground/60"
                      style={{ left: pct(m) }}
                    />
                  ))}
                  <div
                    role="group"
                    ref={(el) => {
                      if (el && i === focusNew) {
                        el.focus({ preventScroll: true });
                        setFocusNew(null);
                      }
                    }}
                    autoFocus={i === focusNew}
                    tabIndex={disabled ? -1 : 0}
                    aria-label={`Preferred time ${formatWindow(p.start, p.end)}`}
                    onKeyDown={(e) => !disabled && onKey(e, i)}
                    onPointerDown={(e) => onDown(e, i, "move")}
                    className={cn(
                      "group/bar absolute top-11 h-2.5 rounded-xs bg-fp-lane-blue/30 outline-none focus-visible:ring-2 focus-visible:ring-ring/50",
                      !disabled &&
                        "cursor-grab active:cursor-grabbing hover:bg-fp-lane-blue/45",
                    )}
                    /* 1px of air each side, so two bars that meet stay two. */
                    style={{
                      left: `calc(${pct(p.start)} + 1px)`,
                      width: `calc(${pct(p.end - p.start)} - 2px)`,
                    }}
                  >
                    {!disabled && (
                      <>
                        {/* THE ENDS SIZE IT — a grip wider than the line. */}
                        <span
                          onPointerDown={(e) => onDown(e, i, "start")}
                          className="absolute inset-y-[-4px] -left-1.5 w-3 cursor-ew-resize"
                        />
                        <span
                          onPointerDown={(e) => onDown(e, i, "end")}
                          className="absolute inset-y-[-4px] -right-1.5 w-3 cursor-ew-resize"
                        />
                        <button
                          type="button"
                          aria-label={`Remove preferred time ${formatWindow(p.start, p.end)}`}
                          onPointerDown={(e) => e.stopPropagation()}
                          onClick={() =>
                            onPreferredChange(
                              preferred.filter((_, j) => j !== i),
                            )
                          }
                          className="absolute top-1/2 -right-6 flex size-5 -translate-y-1/2 items-center justify-center rounded-sm text-muted-foreground opacity-0 outline-none transition-opacity group-hover/bar:opacity-100 group-focus-visible/bar:opacity-100 hover:text-foreground focus-visible:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <X className="size-3.5" />
                        </button>
                      </>
                    )}
                  </div>
                  {/* A SHORT BAR CARRIES ONE LABEL, BOTH TIMES — two would run
                      into each other or into the next bar's. */}
                  <TimeLabel
                    m={p.start}
                    text={
                      narrow && !shared
                        ? `${short(p.start)}–${short(p.end)}`
                        : undefined
                    }
                    open={edit?.i === i && edit.field === "start"}
                    onOpenChange={(o) =>
                      setEdit(o ? { i, field: "start" } : null)
                    }
                    disabled={disabled}
                  >
                    <TimesEditor
                      p={p}
                      focus="start"
                      check={(a, b) => problem(i, a, b)}
                      onCommit={(np) => setAt(i, np)}
                    />
                  </TimeLabel>
                  {!shared && !narrow && (
                    <TimeLabel
                      m={p.end}
                      className="-translate-x-full"
                      open={edit?.i === i && edit.field === "end"}
                      onOpenChange={(o) =>
                        setEdit(o ? { i, field: "end" } : null)
                      }
                      disabled={disabled}
                    >
                      <TimesEditor
                        p={p}
                        focus="end"
                        check={(a, b) => problem(i, a, b)}
                        onCommit={(np) => setAt(i, np)}
                      />
                    </TimeLabel>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        </div>
        <div className="flex items-start gap-3">
          {canAdd && <HangingAdd label="Add preferred time" onClick={add} />}
          {/* NO ROOM LEFT (Pavan, 2026-10-20) — said where the add was pressed. */}
          {full && (
            <p
              role="alert"
              className="flex items-center gap-1.5 pt-1.5 text-xs text-status-failed"
            >
              <TriangleAlert className="size-3.5 shrink-0" />
              Delete or adjust the current preferred time to add a new one.
            </p>
          )}
        </div>
      </div>
    </SheetField>
  );
}

/** A bar's time under its end — pressed, it opens the typed times. */
function TimeLabel({
  m,
  text,
  className,
  open,
  onOpenChange,
  disabled,
  children,
}: {
  m: number;
  /** In place of the one time — a short bar's "8a–9:20a". */
  text?: string;
  className?: string;
  open: boolean;
  onOpenChange: (o: boolean) => void;
  disabled?: boolean;
  children: React.ReactNode;
}) {
  const label = (
    <span
      className={cn(
        "absolute top-[59px] text-xs leading-none tabular-nums text-foreground",
        className,
      )}
      style={{ left: pct(m) }}
    >
      {text ?? short(m)}
    </span>
  );
  if (disabled) return label;
  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={`Type the preferred time, ${short(m)}`}
          className={cn(
            "absolute top-[57px] -ml-0.5 rounded-sm px-0.5 py-0.5 text-xs leading-none tabular-nums text-foreground underline decoration-current/40 decoration-dotted underline-offset-2 outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
            className,
          )}
          style={{ left: pct(m) }}
        >
          {text ?? short(m)}
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-auto p-3">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/** START AND END TO THE MINUTE — each change that fits is kept at once. */
function TimesEditor({
  p,
  focus,
  check,
  onCommit,
}: {
  p: TimeSpan;
  focus: "start" | "end";
  check: (s: number | null, e: number | null) => string | null;
  onCommit: (p: TimeSpan) => void;
}) {
  const [a, setA] = React.useState(hhmm(p.start));
  const [b, setB] = React.useState(hhmm(p.end));
  const err = check(fromHhmm(a), fromHhmm(b));
  const put = (na: string, nb: string) => {
    const s = fromHhmm(na);
    const e = fromHhmm(nb);
    if (!check(s, e)) onCommit({ start: s!, end: e! });
  };
  return (
    <div className="flex flex-col gap-2">
      <div className="flex items-end gap-2">
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          Start
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={a}
            autoFocus={focus === "start"}
            onChange={(e) => {
              setA(e.target.value);
              put(e.target.value, b);
            }}
          />
        </label>
        <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground">
          End
          <Input
            type="time"
            step={60}
            className="w-[130px]"
            value={b}
            autoFocus={focus === "end"}
            onChange={(e) => {
              setB(e.target.value);
              put(a, e.target.value);
            }}
          />
        </label>
      </div>
      {err && <p className="text-xs text-status-failed">{err}</p>}
    </div>
  );
}

