/**
 * Preset-view row.
 *
 * The interaction is the DS's finalized one, from the Data Action Control unit
 * (`data-action-control/DataActionControl.tsx`, rows 177–228) — NOT the
 * `PresetTabs` helper in `experiments/dac-rebuild`, which is archived
 * (`arc-rebuild-*` in App.tsx's ARCHIVE_KEYS) and only stubs view creation by
 * appending "View 1", "View 2" with no name and no state.
 *
 * What that means concretely:
 *   • "Default" is a reset control, not a tab — it restores the default state.
 *   • Creating a view opens a Dialog and the view is NAMED. A view captures the
 *     current search / sort / hidden columns / page size / delivery date, and
 *     selecting it restores them. A view that carries no state is just a label.
 *   • Each saved view has a `⋯` menu revealed on hover: Update view (only when
 *     the current state has drifted), Rename, Delete.
 *   • A brand dot next to the active tab marks unsaved drift.
 *   • Tabs are plain buttons with a `border-b-2` active underline — not the
 *     shadcn Tabs component, so the `⋯` control can sit inside the tab.
 */

/** The slice of screen state a saved view captures and restores. */
export interface ViewState {
  search: string;
  sortKey: string | null;
  sortDir: "asc" | "desc" | null;
  hidden: string[];
  /**
   * Column order as keys, outermost left. Part of the view because which two
   * columns sit side by side IS the view for anyone comparing them — a view
   * that restored the filters but not the arrangement would rebuild half the
   * thing. Empty means "as the table declares them".
   */
  columnOrder: string[];
  /** Reader-set column widths in px, by key. Empty means "as declared". */
  columnWidths: Record<string, number>;
  pageSize: number;
  /** Delivery date as `YYYY-MM-DD` — views are date-scoped like everything else. */
  dateKey: string;
  /** Which column the "Search by column" tool is pointed at. */
  colScope: string;
  /** Its query. Captured so a saved view restores the narrowing it was built with. */
  colQuery: string;
  /**
   * Active grouping dimensions, outermost first. ORDER IS SIGNIFICANT and is
   * compared as given — Status › Customer and Customer › Status are different
   * views, not the same one.
   */
  groupBy: string[];
}

export interface SavedView {
  id: string;
  name: string;
  state: ViewState;
}

/** Order-independent comparison, so drift detection can't be fooled by key order. */
export function viewStateKey(s: ViewState): string {
  return JSON.stringify({
    search: s.search,
    sortKey: s.sortKey,
    sortDir: s.sortDir,
    hidden: [...s.hidden].sort(),
    pageSize: s.pageSize,
    dateKey: s.dateKey,
    colScope: s.colScope,
    colQuery: s.colQuery,
    // Not sorted: the order of the dimensions is part of the state.
    groupBy: s.groupBy ?? [],
  });
}

export interface FuelOrdersViewBarProps {
  /**
   * Only the id and name are read here — the captured state is opaque to this
   * component, which is why Asset Orders and Customers can reuse the row with
   * their own state shapes.
   */
  views: { id: string; name: string }[];
  /**
   * BUILT-IN VIEWS, sitting FIRST, ruled off from Default and the saved ones.
   *
   * A saved view is something a reader MADE; a preset is something the business
   * already is. The businesses inside a line of service — fuel's transport and
   * tank wagon — are the second kind: a broker works one of them, all day, and
   * would otherwise rebuild the same filter every morning and save it under the
   * name it already has.
   *
   * They carry no `⋯` menu, because there is nothing to rename, update or
   * delete about a fact. Picking one is picking Default AND that narrowing, so
   * the two selections are one control and only one tab is ever underlined —
   * and picking one from inside a saved view drops that view.
   */
  presets?: { key: string; label: string }[];
  /** `null` = no preset; the Default tab owns the underline. */
  presetKey?: string | null;
  /** `null` clears the preset — the row sends it when a view takes over. */
  onPresetChange?: (key: string | null) => void;
  /** `null` = the Default view is active. */
  activeId: string | null;
  /** Current state differs from the active view (or from default). */
  dirty: boolean;
  onApply: (id: string) => void;
  onResetToDefault: () => void;
  onCreate: (name: string) => void;
  onRename: (id: string, name: string) => void;
  onUpdate: (id: string) => void;
  onDelete: (id: string) => void;
  /**
   * A segmented scope control, seated at the right of this row ahead of the
   * actions. For a list that holds two KINDS of record rather than two filters
   * of one — fuel orders and asset orders take different forms and answer
   * different questions, so which of them you are looking at is a decision made
   * before anything else on the row applies.
   */
  segments?: { key: string; label: string }[];
  segmentValue?: string;
  onSegmentChange?: (key: string) => void;
  /** Primary CTA — rendered at the right end of this row. */
  onCreateOrder?: () => void;
  /**
   * Turns the CTA into a menu. A list whose Create means several DIFFERENT
   * records — a delivery, an asset out, an asset back — cannot express that in
   * one button: the three take different forms, so the choice has to be made
   * before the form opens rather than by a Type field inside it.
   *
   * Each option carries a `detail` because the names alone do not separate
   * them: "Asset Delivery" and "Asset Pickup" are one word apart and opposite.
   */
  createMenu?: {
    key: string;
    label: string;
    /** Optional — Sales' menu carries names only (Pavan, 2026-10-07). */
    detail?: string;
    /**
     * Turns the entry into a GROUP: its label and detail stop being a button
     * and become the heading over a radio list. Use it where one kind of thing
     * comes in two named variants — the variant is a property of the thing, not
     * a third kind, and a flat menu of near-identical names is where a one-word
     * difference gets misread.
     *
     * Choosing an entry ACTS in one click: `onCreateSelect` gets the
     * chosen key. Each entry starts its order; nothing is held selected.
     */
    choices?: { key: string; label: string; detail?: string }[];
  }[];
  onCreateSelect?: (key: string) => void;
  /** CTA label. Defaults to Fuel Orders' own verb. */
  ctaLabel?: string;
  /** Export — sits immediately left of the CTA. */
  onExport?: () => void;
}

const tabCls = (isActive: boolean) =>
  cn(
    /* `self-end` IS THE WHOLE POINT OF THE ACTIVE RULE. The row is
       `items-center` and its height is set by the taller right cluster, so a
       centred tab floated a couple of pixels clear of the hairline and its 2px
       underline read as a second, parallel line. Bottom-aligned, the two meet:
       the tab's rule lands on the divider with nothing between them. */
    "self-end px-3 py-2 text-xs whitespace-nowrap outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
    isActive
      ? "font-medium text-foreground"
      : "text-muted-foreground hover:text-foreground"
  );

/** Brand dot marking unsaved drift on the active tab. */
function DirtyDot() {
  return (
    <span
      className="ml-1.5 inline-block size-1.5 rounded-full bg-brand align-middle"
      aria-label="unsaved changes"
    />
  );
}

export function FuelOrdersViewBar({
  views,
  activeId,
  dirty,
  onApply,
  onResetToDefault,
  presets,
  presetKey = null,
  onPresetChange,
  onCreate,
  onRename,
  onUpdate,
  onDelete,
  segments,
  segmentValue,
  onSegmentChange,
  onCreateOrder,
  createMenu,
  onCreateSelect,
  onExport,
  ctaLabel = "Create Order",
}: FuelOrdersViewBarProps) {
  const [dialog, setDialog] = React.useState<{
    mode: "new" | "rename";
    id?: string;
    name: string;
    /** A NEW VIEW'S SUGGESTED NAME, from the filters on (Pavan, 2026-10-21) —
        the placeholder; → or Tab takes it to type on from, and Save with
        the box empty saves it. */
    suggestion?: string;
  } | null>(null);


  const submit = () => {
    if (!dialog) return;
    const name = dialog.name.trim() || (dialog.mode === "new" ? dialog.suggestion ?? "" : "");
    if (!name) return;
    /* Creating activates the new view, so it clears the business for the same
       reason applying one does. */
    if (dialog.mode === "new") {
      onPresetChange?.(null);
      onCreate(name);
    }
    else if (dialog.id) onRename(dialog.id, name);
    setDialog(null);
  };

  return (
    <>
      {/* -mx-4 -mt-4 cancels the content layer's 16px inset so the hairline spans
          the full panel width, as it does on the DS screen. */}
      {/* NO BOTTOM PADDING. The active tab's 2px rule has to LAND ON the row's
          hairline — that is what makes it read as a tab and not as an underline
          floating above a line. The row used to keep 2px under the tabs, which
          left a hairline gap between the two rules and made the whole tab strip
          look one notch high. Everything on the right measures its own distance
          from the divider with `self-end` + a margin, so those margins carry
          the 2px that came out of here. */}
      <div className="-mx-4 -mt-4 flex shrink-0 items-center gap-1 border-b border-border px-3 pt-0.5">
        {/* THE BUSINESSES COME FIRST, then a rule, then the views.

            They are two different kinds of thing and the row was reading as one
            list of six. A preset is WHICH BUSINESS this is — a fact about the
            work, true before anyone opened the screen; a view is a narrowing
            somebody MADE and can rename or delete. Ordering the facts first and
            ruling them off says which half of the row you are in, and puts the
            thing a broker changes least often where it is easiest to find.

            DEFAULT IS STILL THE RESTING STATE — it holds the underline when no
            business and no view is on, and it is the first thing after the
            rule, which is where the reader's eye lands once they are past the
            facts. */}
        {presets?.map((p) => (
          <button
            key={p.key}
            type="button"
            /* A PRESET IS DEFAULT PLUS A NARROWING, so picking one from inside
               a saved view drops the view as well. The row used to hide the
               presets while a view was active rather than answer this; hidden
               controls are a worse answer than a stated rule. */
            onClick={() => {
              if (activeId !== null) onResetToDefault();
              onPresetChange?.(p.key);
            }}
            className={cn(
              tabCls(presetKey === p.key),
              "border-b-2",
              presetKey === p.key ? "border-foreground" : "border-transparent"
            )}
          >
            {p.label}
          </button>
        ))}

        {presets && presets.length > 0 && (
          <span aria-hidden className="mx-2 mb-2 h-5 w-px shrink-0 self-end bg-border" />
        )}

        <button
          type="button"
          onClick={onResetToDefault}
          className={cn(
            tabCls(activeId === null && presetKey === null),
            "border-b-2",
            activeId === null && presetKey === null
              ? "border-foreground"
              : "border-transparent"
          )}
        >
          All
          {activeId === null && presetKey === null && dirty && <DirtyDot />}
        </button>

        {views.map((v) => {
          const isActive = v.id === activeId;
          return (
            /* The wrapper is the flex child, so the alignment lives here —
               `tabCls`'s own `self-end` cannot reach past it. */
            <div key={v.id} className="group/tab flex items-end self-end pr-1">
              <button
                type="button"
                /* A VIEW AND A BUSINESS ARE MUTUALLY EXCLUSIVE, because only
                   one tab in this row can hold the underline and a narrowing
                   nobody can see is the thing Default exists to prevent. A
                   saved view does not capture the business — `ViewState` has no
                   field for it — so taking a view means leaving the business,
                   the same way picking a business leaves the view. */
                onClick={() => {
                  onPresetChange?.(null);
                  onApply(v.id);
                }}
                className={cn(
                  tabCls(isActive),
                  "border-b-2",
                  isActive ? "border-foreground" : "border-transparent"
                )}
              >
                {v.name}
              </button>
              {/* CHANGED SINCE SAVED — THE UPDATE IS ONE PRESS, beside the
                  name (Pavan, 2026-10-21), not a dot that sends you to ⋯.
                  The two-arrow refresh glyph, in grey (2026-10-22). */}
              {isActive && dirty && (
                <Tooltip>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      aria-label={`Update ${v.name} with the changes`}
                      onClick={() => onUpdate(v.id)}
                      className="mb-1.5 ml-0.5 inline-flex size-6 items-center justify-center rounded-md text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                    >
                      <RefreshCw className="size-3.5" />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>Update changes</TooltipContent>
                </Tooltip>
              )}
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <button
                    type="button"
                    aria-label={`${v.name} options`}
                    className="ml-0.5 rounded p-0.5 text-muted-foreground opacity-0 outline-none transition-opacity hover:text-foreground focus-visible:opacity-100 group-hover/tab:opacity-100 data-[state=open]:opacity-100"
                  >
                    <MoreHorizontal className="size-3.5" />
                  </button>
                </DropdownMenuTrigger>
                <DropdownMenuContent align="start">
                  {isActive && dirty && (
                    <DropdownMenuItem onClick={() => onUpdate(v.id)}>
                      <Check /> Update view
                    </DropdownMenuItem>
                  )}
                  <DropdownMenuItem
                    onClick={() =>
                      setDialog({ mode: "rename", id: v.id, name: v.name })
                    }
                  >
                    Rename
                  </DropdownMenuItem>
                  <DropdownMenuItem
                    variant="destructive"
                    onClick={() => onDelete(v.id)}
                  >
                    Delete
                  </DropdownMenuItem>
                </DropdownMenuContent>
              </DropdownMenu>
            </div>
          );
        })}

        <button
          type="button"
          onClick={() => setDialog({ mode: "new", name: "", suggestion: suggestViewName() })}
          /* Not a tab — it has no rule to land, so it keeps 4px off the
             hairline rather than sitting on it. */
          className="mb-1 ml-1 inline-flex items-center gap-1 self-end rounded-md px-2 py-1 text-xs text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <Plus className="size-4" /> View
        </button>

        {/*
          Primary CTA, moved up here from the toolbar's right cluster so it sits
          on the preset-view row.

          `size="xs"` — the DS step below `sm` (h-6/24px vs h-8/32px). This row
          carries text tabs, not controls, so the 32px button sat heavy on it.

          `rounded-[4px]` is OFF the DS radius scale, which runs
          xs 2px / sm 6px / md 8px / lg 10px — there is no 4px step. Asked for
          directly, so it stands as a literal, but it is the one raw value in
          this file. FOLLOW-UP: either add a 4px step to the radius scale in
          src/index.css and swap this for the token, or move the button to
          `rounded-sm` (6px). A decision to make here, not a Figma round-trip.

          `mr-1` is load-bearing: this row cancels the content layer's 16px inset
          with -mx-4 and re-pads at px-3 (12px) so its hairline spans the whole
          panel, which would leave the button 4px further right than the toolbar
          controls below it. The extra 4px puts both right edges on the same line.

          `self-end mb-3` sets the gap to the hairline. The row is
          `items-center`, so the button opts out of centring and measures from the
          bottom instead; 12px of margin puts exactly 12px between the button's
          lower edge and the divider. (It was 10 + the row's own 2px of bottom
          padding, until the tabs took that padding away so their rule could land
          on the hairline.)
        */}
        {/* THE SCOPE, THEN SPACE, THEN THE ACTIONS. The segments choose WHICH
            list this is; the buttons act on it. A 20px gap says they are not
            the same kind of control (a rule did, until 2026-10-05). It takes the `ml-auto` so the whole right cluster sits
            right; the CTA below no longer needs it. */}
        {segments && segments.length > 0 && (
          <>
            <ToggleGroup
              type="single"
              variant="outline"
              size="sm"
              value={segmentValue}
              /* Radix emits "" when the active item is pressed again. A scope is
                 never empty — ignore the deselect so one segment stays chosen. */
              onValueChange={(next) => next && onSegmentChange?.(next)}
              aria-label="Order kind"
              className="mb-2.5 ml-auto h-7 self-end"
            >
              {segments.map((seg) => (
                <ToggleGroupItem
                  key={seg.key}
                  value={seg.key}
                  className="h-7 px-2.5 text-xs font-normal data-[state=on]:font-medium"
                >
                  {seg.label}
                </ToggleGroupItem>
              ))}
            </ToggleGroup>
            {/* SPACE, NOT A RULE (Pavan, 2026-10-05): 12px here plus the
                row's 4px gap each side — 20px between the scope and the CTA. */}
            <span aria-hidden className="w-3 shrink-0" />
          </>
        )}

        {/* NO HANDLER, NO BUTTON. A list without a create flow — Vendors, where
            a carrier is onboarded through a contract rather than typed into a
            table — should not carry a CTA that does nothing when pressed. The
            `ml-auto` moves to the Export button below so the right cluster
            still sits right. */}
        {createMenu && createMenu.length > 0 ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                size="xs"
                className={cn(
                  "mb-3 self-end rounded-[4px]",
                  !segments?.length && "ml-auto"
                )}
              >
                <Plus />
                {ctaLabel}
                <ChevronDown />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-80">
              {createMenu.map((o, i) =>
                o.choices?.length ? (
                  <React.Fragment key={o.key}>
                    {i > 0 && <DropdownMenuSeparator />}
                    {/* The group's own name is a HEADING, not a button — the
                        entries below it are the choice. Plain entries, no
                        radios (Pavan, 2026-10-05): each one STARTS an order,
                        so there is no selection for a dot to hold. */}
                    <DropdownMenuLabel className="flex flex-col items-start gap-0.5 py-2 font-normal">
                      <span className="text-sm font-medium text-foreground">
                        {o.label}
                      </span>
                      {o.detail && (
                        <span className="text-xs text-muted-foreground">{o.detail}</span>
                      )}
                    </DropdownMenuLabel>
                    {o.choices.map((c) => (
                      <DropdownMenuItem
                        key={c.key}
                        className="flex-col items-start gap-0.5 py-2"
                        onSelect={() => onCreateSelect?.(c.key)}
                      >
                        <span className="text-sm text-foreground">{c.label}</span>
                        {c.detail && (
                          <span className="text-xs text-muted-foreground">
                            {c.detail}
                          </span>
                        )}
                      </DropdownMenuItem>
                    ))}
                  </React.Fragment>
                ) : (
                  <DropdownMenuItem
                    key={o.key}
                    className="flex-col items-start gap-0.5 py-2"
                    onSelect={() => onCreateSelect?.(o.key)}
                  >
                    <span className="text-sm font-medium text-foreground">{o.label}</span>
                    {o.detail && (
                      <span className="text-xs text-muted-foreground">{o.detail}</span>
                    )}
                  </DropdownMenuItem>
                )
              )}
            </DropdownMenuContent>
          </DropdownMenu>
        ) : (
          onCreateOrder && (
            <Button
              size="xs"
              className={cn(
                "mb-3 self-end rounded-[4px]",
                !segments?.length && "ml-auto"
              )}
              onClick={onCreateOrder}
            >
              <Plus />
              {ctaLabel}
            </Button>
          )
        )}

        {/*
          Export, moved down from the page header so both actions for this list
          sit together. `icon-xs` (24px) matches the CTA's height, and the same
          self-end/mb-3 puts them on one baseline.

          It is the rightmost item, so it carries the `mr-1` that keeps this row
          aligned with the toolbar below: the row cancels the content layer's
          16px inset with -mx-4 and re-pads at px-3, so without the extra 4px the
          trailing control would sit proud of every toolbar control under it.
        */}
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon-xs"
              aria-label="Export"
              onClick={onExport}
              className={cn(
                "mr-1 mb-3 self-end",
                // Takes over pushing the right cluster right when there is no CTA.
                onCreateOrder || createMenu || segments?.length ? "ml-1.5" : "ml-auto"
              )}
            >
              <Upload />
            </Button>
          </TooltipTrigger>
          <TooltipContent>Export</TooltipContent>
        </Tooltip>
      </div>

      <Dialog open={dialog !== null} onOpenChange={(o) => !o && setDialog(null)}>
        <DialogContent className="sm:max-w-sm">
          <DialogHeader>
            <DialogTitle>
              {dialog?.mode === "rename" ? "Rename view" : "Save current view"}
            </DialogTitle>
          </DialogHeader>
          <div className="grid gap-2">
            <Label htmlFor="fuel-view-name">View name</Label>
            <Input
              id="fuel-view-name"
              autoFocus
              value={dialog?.name ?? ""}
              onChange={(e) =>
                setDialog((d) => (d ? { ...d, name: e.target.value } : d))
              }
              onKeyDown={(e) => {
                if (e.key === "Enter") submit();
                /* TAKE THE SUGGESTION to add to it. */
                if ((e.key === "ArrowRight" || e.key === "Tab") && !dialog?.name && dialog?.suggestion) {
                  e.preventDefault();
                  setDialog((d) => (d ? { ...d, name: `${d.suggestion} ` } : d));
                }
              }}
              placeholder={(dialog?.mode === "new" && dialog.suggestion) || "e.g. Unassigned today"}
            />
          </div>
          <DialogFooter>
            <DialogClose asChild>
              <Button variant="outline">Cancel</Button>
            </DialogClose>
            <Button
              onClick={submit}
              disabled={!dialog?.name.trim() && !(dialog?.mode === "new" && dialog.suggestion)}
            >
              {dialog?.mode === "rename" ? "Rename" : "Save view"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import * as React from "react";
import { Plus } from "lucide-react";
import { cn } from "@/lib/utils";

/*
  THE ADD ON A TABLE — a tab hanging off the card's bottom-left corner.

  WHY NOT A BAND INSIDE THE CARD. A full-width strip draws a rule across the
  whole card to carry one small act, and what it reads as is an empty extra
  row of the table. (Pavan, 2026-09-22 — after both were built and put side by
  side.)

  WHY FILLED AND NOT OUTLINED. It takes the table's own header tint, so it
  continues the table rather than sitting near it as a separate control. An
  outline would be a second box under a card that already has one, which is
  the nesting `docs/ds/ui/2-rules.md` §10f exists to remove.

  A PLUS, AND THE WORDS ON HOVER. The row it adds is one of many and the sign
  says the act; a permanent label makes an ordinary add look like the
  section's main one. The label still arrives on keyboard focus, so it is not
  a thing only a mouse can find, and the button keeps its `aria-label` either
  way — the collapsed state is a visual economy, never a nameless control.
*/

/* IT CAN OPEN A MENU (Pavan, 2026-10-07). When one add offers a choice of
   row — the quote's Fee or Tax — it is a menu's trigger, so whatever the
   trigger hands it (ref, pointer and key handlers, aria) is passed through.
   Nothing about how it looks changes. */
export function HangingAdd({
  label,
  onClick,
  disabled,
  className,
  ...trigger
}: {
  /** "Add products", "Add vendor" — the table's own noun, always plural-safe. */
  label: string;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  disabled?: boolean;
  className?: string;
} & Omit<React.ComponentPropsWithRef<"button">, "onClick" | "className" | "disabled">) {
  const [open, setOpen] = React.useState(false);

  return (
    <button
      {...trigger}
      type="button"
      aria-label={label}
      disabled={disabled}
      onClick={onClick}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      onFocus={() => setOpen(true)}
      onBlur={() => setOpen(false)}
      className={cn(
        /* SQUARE ON TOP, ROUNDED BELOW — the top edge is the card's bottom
           edge, and a radius there would show a notch between them. */
        "flex h-8 items-center rounded-t-none rounded-b-md bg-fp-table-header px-2.5",
        "text-sm font-medium text-foreground outline-none transition-colors",
        "hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring/50",
        "disabled:pointer-events-none disabled:opacity-50",
        className
      )}
    >
      <Plus className="size-4 shrink-0" />
      <span
        className={cn(
          "overflow-hidden whitespace-nowrap transition-[max-width,opacity,padding] duration-200",
          open ? "max-w-[140px] pl-1.5 opacity-100" : "max-w-0 opacity-0"
        )}
      >
        {label}
      </span>
    </button>
  );
}

import * as React from "react";
import { History, ListFilter, Search } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  clearActiveFilters,
  groupIds,
  listKeyOf,
  readHistory,
  recordHistory,
  setActiveFilters,
  type HistoryEntry,
} from "./filterMemory";

/**
 * Faceted filter panel, generic over its facets.
 *
 * Structure is the DS panel's (Figma "Action Bar Unit · Filter interactions",
 * 27665:14074): facet side menu + options pane + Clear All / Apply footer, same
 * sizes and classes Fuel Orders proved.
 *
 * SEARCH IS PER-FACET, and that is the rule this carries forward: a facet gets a
 * search field when its list cannot be taken in at once, and does not when it is
 * short enough to scan. `searchable` is an explicit flag rather than a length
 * threshold, so a facet cannot silently gain or lose the control as its options
 * change.
 *
 * DS FOLLOW-UP: this is the parameterised `tables-layout/FilterPanel` that
 * `docs/handoff-ds-adoption-2.md` Task 5 asks for. When the DS version takes
 * facets as props, this file deletes itself.
 */
/**
 * An option is either a bare value, or a value with a second line under it —
 * a ship-to needs its address to be told apart from a similarly-named site, and
 * the checkbox label alone cannot carry that.
 */
export type ListOption = string | { value: string; description: string };

const optionValue = (o: ListOption) => (typeof o === "string" ? o : o.value);
const optionDescription = (o: ListOption) =>
  typeof o === "string" ? undefined : o.description;

export interface ListFacetSection {
  title: string;
  options: ListOption[];
}

export interface ListFacet {
  key: string;
  label: string;
  /** Flat option list. Omit when the facet uses `sections`. */
  options?: ListOption[];
  /**
   * A facet that asks the SAME question at several grains — ship-to name, ZIP,
   * state are all "which address" — puts them in one pane under sub-headings
   * rather than eating three rows of the facet menu. Selections across sections
   * are independent, and the facet's count is their total.
   */
  sections?: ListFacetSection[];
  /** Give the options pane a search field. Off for lists you can take in whole. */
  searchable?: boolean;
}

/** Every option a facet holds, flat — for counting and for search. */
const facetOptions = (f: ListFacet): string[] =>
  (f.options ?? f.sections?.flatMap((sec) => sec.options) ?? []).map(optionValue);

export function ListFilters({
  facets,
  value,
  onApply,
  fullWidth = false,
  countFor,
  historyKey,
}: {
  facets: ListFacet[];
  /** Which list's RECENT HISTORY this is — defaults to the facets it has. */
  historyKey?: string;
  /** Stretch the trigger to its container — for a row of its own, in a sheet. */
  fullWidth?: boolean;
  /**
   * What is actually applied, when the caller keeps it.
   *
   * The panel STAGES changes — nothing narrows until Apply — so it holds its
   * own working copy, and that copy has to be reset to the truth each time the
   * panel opens or it will re-apply a tick the reader took off somewhere else.
   * Somewhere else is the chip shelf: take a chip off, open the panel, and
   * without this the checkbox would still be on.
   */
  value?: ReadonlySet<string>;
  /**
   * Fires on Apply and on Clear All with the selected `facetKey:option` ids.
   *
   * Left out, the panel is a composition demo — it shows the interaction and
   * narrows nothing, which is what every screen got before Order Types moved
   * in here from a tab row. A facet that REPLACES working behaviour has to be
   * wired, so the caller passes this and applies what it can.
   */
  onApply?: (selected: ReadonlySet<string>) => void;
  /**
   * HOW MANY ROWS THE TICKS WOULD LEAVE (Pavan, 2026-10-05) — shown on the
   * footer's left as the reader ticks, before Apply. The screen answers it
   * with the same narrowing it applies, everything else on screen included
   * (search, column boxes, scope). Left out, the footer has no count.
   */
  countFor?: (selected: ReadonlySet<string>) => number;
}) {
  const [open, setOpen] = React.useState(false);
  const [checked, setChecked] = React.useState<Set<string>>(new Set());
  /* RECENT HISTORY (Pavan, 2026-10-21) — the toolbar's panel only; the
     export sheet's copy applies as it goes and keeps none. */
  const list = historyKey ?? listKeyOf(facets);
  const [history, setHistory] = React.useState<HistoryEntry[]>([]);
  /* THE VIEW ROW NAMES A VIEW FROM WHAT IS ON — see `filterMemory`. */
  React.useEffect(() => {
    if (fullWidth) return;
    setActiveFilters(facets, value ?? checked);
    return () => clearActiveFilters(facets);
  });

  const applied = value ? value.size : checked.size;

  const toggle = (key: string) =>
    setChecked((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });

  return (
    <Popover
      open={open}
      onOpenChange={(next) => {
        if (next && value) setChecked(new Set(value));
        if (next && !fullWidth) setHistory(readHistory(list));
        setOpen(next);
      }}
    >
      {/* `asChild` slots onto exactly ONE child, so this note sits outside the
          trigger — as raw text inside it, React counted it as a second child and
          Radix threw "failed to slot onto its children".
          `bg-transparent` makes the button outline-only, like the search field
          beside it: the DS `outline` variant fills with `bg-background` (#efefeb
          light), the APP background, which is right when the button sits on it
          and wrong here on the white content layer, where it read as a filled
          grey block next to a transparent input. The stroke moves to
          `--input` so it matches the field beside it: the `outline` variant uses
          `--border` in light but ALREADY uses `--input` in dark, so light was the
          odd one out and the button read a shade lighter than the input. */}
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          size="sm"
          className={cn(fullWidth && "h-8 w-full justify-start")}
        >
          <ListFilter />
          Filters
          {/* THE COUNT IS WHAT IS APPLIED, NOT WHAT IS TICKED. The panel's own
              ticks are a draft until Apply, and the button is read with the
              panel shut — a number that moved as you ticked would be counting
              a narrowing that has not happened. It also has to follow a chip
              being taken off outside the panel. Falls back to the ticks only
              where the caller does not keep the applied set. */}
          {applied > 0 && (
            <span className="ml-1 rounded-full bg-accent px-1.5 text-xs tabular-nums">
              {applied}
            </span>
          )}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-[600px] overflow-hidden p-0">
        <ListFilterPanel
          facets={facets}
          checked={checked}
          onToggle={toggle}
          menuWidth={200}
          height={264}
          history={fullWidth ? undefined : history}
          onPickHistory={(ids) => setChecked(new Set(ids))}
        />

        {/* THE COUNT ON THE LEFT, BOTH ACTS ON THE RIGHT (Pavan,
            2026-10-05). The number is what Apply would show — read before
            committing to it. Clear All sits beside Apply as its quieter
            sibling, not across the bar from it. */}
        <div className="flex h-16 items-center justify-between gap-3 border-t border-border px-4">
          <span className="text-sm tabular-nums text-muted-foreground" aria-live="polite">
            {countFor && (
              <>
                <span className="font-medium text-foreground">
                  {countFor(checked).toLocaleString()}
                </span>{" "}
                {countFor(checked) === 1 ? "result" : "results"}
              </>
            )}
          </span>
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                const empty = new Set<string>();
                setChecked(empty);
                onApply?.(empty);
              }}
            >
              Clear All
            </Button>
            <Button
              size="sm"
              onClick={() => {
                if (!fullWidth) recordHistory(list, checked);
                onApply?.(checked);
                setOpen(false);
              }}
            >
              Apply Filters
            </Button>
          </div>
        </div>
      </PopoverContent>
    </Popover>
  );
}

/**
 * The panel's BODY — facet menu, options pane — with no chrome of its own.
 *
 * Split out so the same two panes can be a popover on a toolbar and a plain
 * block inside a sheet. The export sheet takes the second form: a panel that
 * opens another floating panel on top of itself is two layers deep for one
 * question, and the reader loses sight of the count they are deciding about.
 *
 * IT DOES NOT OWN WHAT IS TICKED. The popover stages its ticks until Apply and
 * the sheet applies them as they happen, and that difference belongs to the
 * caller — this renders a set and reports toggles.
 */
export function ListFilterPanel({
  facets,
  checked,
  onToggle,
  menuWidth = 200,
  height,
  className,
  history,
  onPickHistory,
}: {
  facets: ListFacet[];
  /** RECENT HISTORY — filter sets applied in the last 24 hours. The menu
      leads with it only when there are some. */
  history?: HistoryEntry[];
  onPickHistory?: (ids: string[]) => void;
  /** Ticked ids, as `facetKey:option`. */
  checked: ReadonlySet<string>;
  onToggle: (id: string) => void;
  /** The facet column's width. Narrower inside a sheet than in the popover. */
  menuWidth?: number;
  /**
   * Fix the panes' height and let them scroll inside it.
   *
   * FOR A POPOVER, which cannot grow past the window it floats in. Left out —
   * the sheet — the panel is as tall as its longest pane and nothing scrolls:
   * a facet list in a column with room to spare does not need a viewport of its
   * own, and a scroller hides how much there is to read.
   */
  height?: number;
  className?: string;
}) {
  const [facetKey, setFacetKey] = React.useState(facets[0]?.key ?? "");
  const [query, setQuery] = React.useState("");

  const HISTORY = "__history";
  const showHistory = facetKey === HISTORY && Boolean(history?.length);
  const facet = facets.find((f) => f.key === facetKey) ?? facets[0];

  const q = query.toLowerCase();
  /* Search matches the description as well as the value: on a ship-to facet the
     address IS what people search by — a city or a state, not the site name. */
  const match = (o: ListOption) =>
    optionValue(o).toLowerCase().includes(q) ||
    (optionDescription(o) ?? "").toLowerCase().includes(q);
  /** One shape for both facet kinds: an unlabelled section is a flat list. */
  const sections: ListFacetSection[] = facet
    ? (facet.sections ?? [{ title: "", options: facet.options ?? [] }]).map(
        (sec) => ({ ...sec, options: sec.options.filter(match) })
      )
    : [];
  const hits = sections.reduce((n, sec) => n + sec.options.length, 0);

  const scrolls = height !== undefined;

  return (
    <div className={cn("flex", className)} style={height ? { height } : undefined}>
      <div
        className={cn(
          "flex shrink-0 flex-col gap-1 border-r border-border p-2",
          scrolls && "overflow-auto"
        )}
        style={{ width: menuWidth }}
      >
        {history && history.length > 0 && (
          <button
            type="button"
            onClick={() => {
              setFacetKey(HISTORY);
              setQuery("");
            }}
            className={cn(
              "flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-left text-sm outline-none transition-colors hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring/50",
              showHistory ? "bg-accent text-accent-foreground" : "text-muted-foreground hover:text-foreground"
            )}
          >
            <History className="size-4 shrink-0" />
            <span className="flex-1 truncate">Recent history</span>
            <span className="text-xs tabular-nums text-muted-foreground">{history.length}</span>
          </button>
        )}
        {facets.map((f) => {
          const n = facetOptions(f).filter((o) =>
            checked.has(`${f.key}:${o}`)
          ).length;
          return (
            <button
              key={f.key}
              type="button"
              onClick={() => {
                setFacetKey(f.key);
                setQuery("");
              }}
              className={cn(
                "flex h-8 shrink-0 items-center gap-2 rounded-md px-2 text-left text-sm outline-none transition-colors hover:bg-accent/60 focus-visible:ring-2 focus-visible:ring-ring/50",
                facetKey === f.key
                  ? "bg-accent text-accent-foreground"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <span className="flex-1 truncate">{f.label}</span>
              {n > 0 && (
                <span className="text-xs tabular-nums text-muted-foreground">
                  {n}
                </span>
              )}
            </button>
          );
        })}
      </div>

      {showHistory ? (
        /* EACH SET AS IT WAS APPLIED, by category — a press puts its ticks
           back; Apply applies them. */
        <div className={cn("flex min-w-0 flex-1 flex-col gap-1.5 p-2", scrolls && "min-h-0 overflow-auto")}>
          {history!.map((e) => {
            const on = e.ids.length === checked.size && e.ids.every((id) => checked.has(id));
            return (
              <button
                key={e.at}
                type="button"
                aria-pressed={on}
                onClick={() => onPickHistory?.(e.ids)}
                className={cn(
                  "flex flex-col gap-1 rounded-md border px-3 py-2 text-left outline-none transition-colors hover:bg-fp-row-hover focus-visible:ring-2 focus-visible:ring-ring/50",
                  on ? "border-selected-border bg-selected" : "border-border"
                )}
              >
                {groupIds(facets, e.ids).map((g) => (
                  <span key={g.key} className="flex min-w-0 gap-1.5 text-sm">
                    <span className="shrink-0 text-muted-foreground">{g.label}</span>
                    <span className="truncate text-foreground">{g.values.join(", ")}</span>
                  </span>
                ))}
                <span className="text-xs text-muted-foreground">{ago(e.at)}</span>
              </button>
            );
          })}
        </div>
      ) : (
      <div className="flex min-w-0 flex-1 flex-col">
        {facet?.searchable && (
          <div className="p-2">
            <div className="relative">
              <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder={`Search ${facet.label.toLowerCase()}…`}
                className="h-8 pl-8"
              />
            </div>
          </div>
        )}
        <div
          className={cn(
            "flex-1 px-2 pb-2",
            scrolls && "min-h-0 overflow-auto",
            !facet?.searchable && "pt-2"
          )}
        >
          {sections.map((sec) =>
            sec.options.length === 0 ? null : (
              <div key={sec.title || "flat"} className="flex flex-col">
                {sec.title && (
                  <p className="px-0.5 pt-2 pb-1 text-xs font-medium tracking-wide text-muted-foreground uppercase">
                    {sec.title}
                  </p>
                )}
                {sec.options.map((opt) => {
                  const value = optionValue(opt);
                  const description = optionDescription(opt);
                  const id = `${facet.key}:${value}`;
                  return (
                    <label
                      key={id}
                      className="flex min-h-8 cursor-pointer items-start gap-2 py-1"
                    >
                      <Checkbox
                        checked={checked.has(id)}
                        onCheckedChange={() => onToggle(id)}
                        aria-label={value}
                        /* Nudged down so it centres on the FIRST line, not on
                           the two-line block. */
                        className="mt-0.5"
                      />
                      <span className="flex min-w-0 flex-col">
                        <span className="text-sm">{value}</span>
                        {description && (
                          <span className="text-xs text-muted-foreground">
                            {description}
                          </span>
                        )}
                      </span>
                    </label>
                  );
                })}
              </div>
            )
          )}
          {hits === 0 && (
            <p className="px-2 py-1 text-sm text-muted-foreground">No matches.</p>
          )}
        </div>
      </div>
      )}
    </div>
  );
}

/** "Just now", "12 min ago", "3 h ago" — inside the 24 hours history keeps. */
function ago(at: number) {
  const min = Math.round((Date.now() - at) / 60_000);
  if (min < 1) return "Just now";
  if (min < 60) return `${min} min ago`;
  return `${Math.round(min / 60)} h ago`;
}

import * as React from "react";
import { ArrowDown, ArrowUp, ChevronRight, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { useA11y } from "@/components/theme/a11y";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { OverflowChip, type BreakdownRow } from "./BreakdownCard";
import {
  GroupHeaderRow,
  TableColumnHeader,
  useTableColumns,
  type GroupNode,
} from "@/components/tables-layout";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

/**
 * Generic list table — the chrome only, with cells supplied by the caller.
 *
 * The chrome is the DS DataTable's (Figma 28165:3758) and is copied from
 * FuelOrdersTable rather than re-derived, so the three lists are identical
 * where they should be: outer stroke on `border`, sticky Surface-1a header with
 * a bottom hairline so rows scroll under it, 40px header row, 56px body rows,
 * px-3 cells, the asc → desc → unsorted sort glyph cycle, and a pinned trailing
 * actions column whose opaque fill re-applies the row's hover/selected tint as a
 * `before` overlay (otherwise the pinned cell hides it).
 *
 * FuelOrdersTable is deliberately NOT refactored onto this. Its Product and Tags
 * cells carry measured-width truncation with a ResizeObserver, which nothing
 * else needs; moving it would be churn without benefit. This exists so Asset
 * Orders and Customers do not each re-copy the chrome a third and fourth time.
 *
 * DS FOLLOW-UP: this shell, `TwoLineCell` and `OverflowBadge` are not
 * screen-specific. They belong beside `tables-layout/DataTable` once the DS
 * version can take a column set and a cell renderer as props.
 */

/** A value that reads as one thing — a record number or code (no spaces),
    or a date ("Oct 23, 2026"). */
const ONE_LINE = /^(\S+|[A-Z][a-z]{2} \d{1,2}, \d{4})$/;

export interface ListColumn<K extends string> {
  key: K;
  label: string;
  width: number;
  sortable?: boolean;
  /**
   * `right` for money and for counts that are compared down the column —
   * the digits line up and the eye reads magnitude without reading numbers.
   * `center` for a short count that is READ rather than compared, where a
   * right edge miles from the header looks like a mistake.
   */
  align?: "left" | "right" | "center";
}

export interface ListSort<K extends string> {
  key: K;
  dir: "asc" | "desc";
}

export interface ListTableProps<Row, K extends string> {
  /** A ROW ABOVE THE HEADER, inside the table's frame and outside its scroll —
   *  for the table's own tools (see `ListToolbarProps.tableToolsInto`). */
  topBar?: React.ReactNode;
  /** Every cell sits at the top of its row — for rows that grow tall with
   *  stacked lines, so the record's own cells read first. */
  alignTop?: boolean;
  rows: Row[];
  columns: ListColumn<K>[];
  hidden?: Set<K>;
  sort: ListSort<K> | null;
  onSort: (key: K) => void;
  /** Stable identity for the React key. */
  rowId: (row: Row) => string;
  /** Cell content per column. `actions` is supplied by this component. */
  renderCell: (row: Row, key: K) => React.ReactNode;
  /** Opens the row's side sheet, via the pinned chevron. */
  onOpenRow?: (row: Row) => void;
  /** Accessible label for that chevron, e.g. `Open order 4592866`. */
  openLabel: (row: Row) => string;
  /** Which column key holds the pinned chevron. */
  actionsKey: K;
  /**
   * SELECTION IS OPT-IN. A list with nothing to do to a selection should not
   * spend 44px on a checkbox column that leads nowhere, so the column exists
   * only when the handlers for it do — the same rule the bulk bar follows.
   */
  selectedIds?: ReadonlySet<string>;
  onToggleRow?: (id: string) => void;
  /** `next` is the state the header checkbox is moving TO, so the caller does
   *  not have to re-derive it from the current selection. */
  onToggleAll?: (next: boolean) => void;
  /**
   * Skeleton rows in place of content. Not a spinner: a list that collapses to
   * a spinner loses its own height, and the page jumps when the rows land.
   */
  loading?: boolean;
  skeletonRows?: number;
  /**
   * Column order, as keys. Supply with `onReorderColumns` to keep it in a saved
   * view; leave both off and the table remembers it for the session only. The
   * pinned chevron column never moves.
   */
  columnOrder?: string[];
  onReorderColumns?: (next: string[]) => void;
  /** Reader-set column widths in px, by key. Same dual-mode as the order. */
  columnWidths?: Record<string, number>;
  onResizeColumns?: (next: Record<string, number>) => void;
  /**
   * Grouped render list from `groupRows`. Omitted, the table renders `rows`
   * flat — which is what every ungrouped list does.
   */
  nodes?: GroupNode<Row>[];
  collapsedGroups?: ReadonlySet<string>;
  onToggleGroupCollapse?: (id: string) => void;
  /**
   * A BOX PER COLUMN, UNDER THE HEADERS.
   *
   * The question "where is the Halvorsen order" is asked OF a column, so it is
   * answered at the column. A single search box asks it of the whole row and
   * brings back everything that mentions the word anywhere; a popover that
   * searches one named column asks it properly but only once, so two
   * conditions meant two searches and remembering the first.
   *
   * The boxes are AND-ed, because that is what typing in two of them looks
   * like it should do. The row only exists while the reader has asked for it —
   * see `ListToolbarProps.onToggleColumnFilters` — because 40px of empty
   * inputs above every table is a permanent cost for an occasional question.
   */
  columnFilters?: Record<string, string>;
  onColumnFilterChange?: (key: K, value: string) => void;
  showColumnFilters?: boolean;
  /** What one record is called in a group header — "asset", "account". */
  groupNoun?: string;
  /** Unit for the summed measure the headers carry, e.g. `gal`. */
  groupUnit?: string;
  /**
   * A NESTED LAYER — the DS expandable row (`tables-layout/DataTable`,
   * Pavan, 2026-10-17). Given, the first column's cell leads with a small
   * chevron that turns down and opens this content in a full-width row
   * beneath: pinned to the visible width, WHITE (the content layer), and a
   * 2px GREEN rail that runs unbroken from the parent row's left edge into
   * it. The open parent keeps a tint and drops its bottom divider (DS ui
   * §10j).
   */
  renderExpanded?: (row: Row) => React.ReactNode;
  /** The chevron's label, e.g. `Show tanks for REQ-1115`. */
  expandLabel?: (row: Row, open: boolean) => string;
}

export function ListTable<Row, K extends string>({
  rows,
  columns,
  hidden,
  sort,
  onSort,
  rowId,
  renderCell,
  onOpenRow,
  openLabel,
  actionsKey,
  selectedIds,
  onToggleRow,
  onToggleAll,
  loading = false,
  skeletonRows = 10,
  nodes,
  collapsedGroups,
  onToggleGroupCollapse,
  groupNoun = "record",
  groupUnit = "",
  columnOrder,
  onReorderColumns,
  columnWidths,
  onResizeColumns,
  columnFilters,
  onColumnFilterChange,
  showColumnFilters = false,
  renderExpanded,
  expandLabel,
  alignTop = false,
  topBar,
}: ListTableProps<Row, K>) {
  const expandable = Boolean(renderExpanded);
  const [expanded, setExpanded] = React.useState<ReadonlySet<string>>(() => new Set());
  const toggleExpand = (id: string) =>
    setExpanded((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  /* THE FRAME'S WIDTH — what the columns fill, and what a nested layer
     spans (the visible width, not the scrolled one). */
  const frame = React.useRef<HTMLDivElement>(null);
  const [frameWidth, setFrameWidth] = React.useState<number | undefined>();
  React.useEffect(() => {
    if (!frame.current) return;
    const el = frame.current;
    const ro = new ResizeObserver(() => setFrameWidth(el.clientWidth));
    ro.observe(el);
    return () => ro.disconnect();
  }, []);
  /* THE PINNED CHEVRON IS THE FRAME, not a column: it is how a row is opened
     and it is stuck to the right edge so it survives a sideways scroll. It
     does not move, and nothing can be dropped past it. */
  /* Columns move and resize because the DS header does it — see
     `useTableColumns`. Nothing here but which column is structure. */
  const cols = useTableColumns({
    keys: React.useMemo(() => columns.map((c) => c.key), [columns]),
    fixed: React.useMemo(() => [actionsKey], [actionsKey]),
    order: columnOrder,
    onOrderChange: onReorderColumns,
    widths: columnWidths,
    onWidthsChange: onResizeColumns,
  });
  /* NO CHEVRON COLUMN (Pavan, 2026-10-19): the row itself opens the
     record — a click anywhere on it, or Enter on a focused row — so the
     pinned chevron cell at the end is gone from every list. `actionsKey`
     names that column so it is dropped here. */
  const visible = cols.arrange(columns.filter((c) => !hidden?.has(c.key) && c.key !== actionsKey));

  /* THE CHECKBOX COLUMN IS NOT A COLUMN. It cannot be hidden, reordered,
     resized or sorted, so it sits outside `cols` entirely and is drawn as a
     fixed 44px cell at the head of every row — the mirror of the pinned
     chevron at the tail. */
  const selectable = Boolean(selectedIds && onToggleRow);
  const ids = rows.map(rowId);
  const allSelected = selectable && ids.length > 0 && ids.every((id) => selectedIds!.has(id));
  const someSelected = selectable && ids.some((id) => selectedIds!.has(id));
  const span = visible.length + (selectable ? 1 : 0);
  /* NO EMPTY SPACE ON THE RIGHT, EVER (Pavan, 2026-10-22). Each column starts
     at the width its longest value needs (DS ui §10p); when the table is
     narrower than its frame, the spare width goes to the columns that hold
     the most — a column gets a share in proportion to how far it is wider
     than 120px, so an icon, a count or a short code stays as it is and a
     name, an address or a contact takes the room. Wider than the frame, the
     table scrolls. */
  /* RECORD NUMBERS AND DATES STAY ON ONE LINE (Pavan, 2026-10-23). At a
     bigger Text size the other cells wrap inside their column, but a value
     like "D-105370" or "Oct 23, 2026" broken in two stops reading as one, so
     its column widens by exactly what the value lacks. Measured after paint;
     it only ever grows while the text size holds, so it can't see-saw. */
  const textSize = useA11y().text;
  const [oneLine, setOneLine] = React.useState<{ at: number; need: Record<string, number> }>({ at: 0, need: {} });
  const need = oneLine.at === textSize ? oneLine.need : {};
  React.useLayoutEffect(() => {
    const root = frame.current;
    if (!root || textSize === 0) return;
    const lead = selectedIds && onToggleRow ? 1 : 0;
    const next: Record<string, number> = { ...need };
    let grew = false;
    root.querySelectorAll<HTMLTableRowElement>("tbody tr").forEach((tr) => {
      if (tr.children.length !== visible.length + lead) return;
      visible.forEach((c, i) => {
        const td = tr.children[i + lead] as HTMLElement;
        td.querySelectorAll<HTMLElement>(".truncate").forEach((el) => {
          if (!ONE_LINE.test(el.textContent?.trim() ?? "")) return;
          el.dataset.oneLine = "";
          const short = el.scrollWidth - el.clientWidth;
          if (short <= 1) return;
          const want = Math.ceil(td.offsetWidth + short);
          if (want > (next[c.key] ?? 0)) {
            next[c.key] = want;
            grew = true;
          }
        });
      });
    });
    if (grew || oneLine.at !== textSize) setOneLine({ at: textSize, need: next });
    /* Re-measured when the text size, the rows or the columns change. */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [textSize, rows, frameWidth, visible.map((c) => c.key).join(), oneLine]);
  const base = visible.map((c) => Math.max(cols.widthOf(c), need[c.key] ?? 0));
  const widths = (() => {
    const lead = selectable ? 44 : 0;
    const spare = (frameWidth ?? 0) - lead - base.reduce((a, b) => a + b, 0);
    if (spare <= 0) return base;
    const weight = base.map((w) => Math.max(0, w - 120));
    const total = weight.reduce((a, b) => a + b, 0) || base.reduce((a, b) => a + b, 0);
    const share = total === 0 ? base.map(() => 0) : (weight.some((w) => w > 0) ? weight : base).map((w) => w / total);
    const out = base.map((w, i) => Math.floor(w + spare * share[i]));
    /* What rounding left goes on the widest column, so the edge lands exactly. */
    const left = (frameWidth ?? 0) - lead - out.reduce((a, b) => a + b, 0);
    const widest = out.indexOf(Math.max(...out));
    if (widest >= 0) out[widest] += Math.max(0, left);
    return out;
  })();

  const body = (
    <div
      ref={frame}
      className={cn(
        "overflow-auto [&_[data-slot=table-container]]:overflow-visible",
        topBar ? "min-h-0 flex-1" : "h-full rounded-md border border-border"
      )}
    >
      <Table style={{ tableLayout: "fixed", width: widths.reduce((a, b) => a + b, selectable ? 44 : 0) }}>
        <colgroup>
          {selectable && <col style={{ width: "44px" }} />}
          {visible.map((c, i) => (
            <col key={c.key} style={{ width: `${widths[i]}px` }} />
          ))}
        </colgroup>
        <TableHeader className="sticky top-0 z-20">
          <TableRow className="h-10">
            {selectable && (
              <TableHead className="border-b border-fp-outline-1 bg-fp-table-header px-3">
                <Checkbox
                  checked={allSelected ? true : someSelected ? "indeterminate" : false}
                  onCheckedChange={() => onToggleAll?.(!allSelected)}
                  aria-label={allSelected ? "Clear selection" : "Select all rows on this page"}
                />
              </TableHead>
            )}
            {visible.map((col) => {
              const active = sort?.key === col.key;
              /* THE SORTED COLUMN (Pavan, 2026-10-21): a real arrow, not a
                 chevron, on a darker grey header; its cells a very light grey. */
              const SortIcon = !active
                ? ChevronsUpDown
                : sort.dir === "asc"
                  ? ArrowUp
                  : ArrowDown;
              return (
                <TableColumnHeader
                  key={col.key}
                  cols={cols}
                  col={col}
                  aria-sort={
                    active
                      ? sort.dir === "asc"
                        ? "ascending"
                        : "descending"
                      : undefined
                  }
                  className={cn(
                    "border-b border-fp-outline-1 bg-fp-table-header px-3 text-xs font-medium text-muted-foreground",
                    col.key === actionsKey && "sticky right-0 z-30"
                  )}
                >
                  {col.label && col.sortable ? (
                    <button
                      type="button"
                      onClick={() => onSort(col.key)}
                      aria-label={`Sort by ${col.label}`}
                      className={cn(
                        "inline-flex items-center gap-1 outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50",
                        active && "text-foreground"
                      )}
                    >
                      {col.label}
                      <SortIcon
                        className={cn(
                          "size-3.5",
                          active ? "opacity-100" : "opacity-50"
                        )}
                      />
                    </button>
                  ) : col.label ? (
                    <span>{col.label}</span>
                  ) : null}
                </TableColumnHeader>
              );
            })}
          </TableRow>
          {showColumnFilters && onColumnFilterChange && (
            /* THE SECOND HEADER ROW, not a first body row: it scrolls and
               sticks with the headers it belongs to, and the table's own
               `<thead>` is what tells a screen reader these are not records. */
            /* THE BAND IS QUIETER THAN THE HEADER IT SITS UNDER. At the same
               fill the two read as one 80px header, and the boxes looked like
               part of the column names rather than something you do to them.
               On the content layer's own surface the strip recedes and the
               inputs are the only thing in it with an edge — which is right,
               because they are the only thing in it you can touch. */
            <TableRow className="h-11 hover:bg-transparent">
              {selectable && (
                <TableHead className="border-b border-fp-outline-1 bg-fp-surface-1b px-3" />
              )}
              {visible.map((col) => (
                <TableHead
                  key={col.key}
                  className={cn(
                    "border-b border-fp-outline-1 bg-fp-surface-1b px-2",
                    col.key === actionsKey && "sticky right-0 z-30"
                  )}
                >
                  {col.label ? (
                    <Input
                      value={columnFilters?.[col.key] ?? ""}
                      onChange={(e) => onColumnFilterChange(col.key, e.target.value)}
                      /* THE PLACEHOLDER GOES WHERE IT WOULD BE CUT. A column
                         narrow enough to clip the word shows an empty box
                         instead — "Filte" reads as a bug, and the row of
                         identical boxes has already said what they are. */
                      placeholder={(columnWidths?.[col.key] ?? col.width) >= 96 ? "Filter…" : ""}
                      aria-label={`Filter by ${col.label}`}
                      /* `data-no-row-open` keeps a click in the box from being
                         read as a click on the row it sits above. */
                      data-no-row-open
                      /* `rounded-md` and no shadow — the DS's field shape.
                         A pill is the chip vocabulary, and a raised field in a
                         strip of fields lifts a row of boxes off a surface
                         they belong to. */
                      className="h-7 rounded-md px-2.5 text-xs shadow-none"
                    />
                  ) : null}
                </TableHead>
              ))}
            </TableRow>
          )}
        </TableHeader>
        <TableBody>
          {loading
            ? Array.from({ length: skeletonRows }, (_, i) => (
                <TableRow key={`sk-${i}`} className="h-14">
                  {selectable && (
                    <TableCell className="px-3">
                      <Skeleton className="size-4 rounded-[4px]" />
                    </TableCell>
                  )}
                  {visible.map((col) => (
                    <TableCell key={col.key} className="px-3">
                      {col.key === actionsKey ? null : (
                        <Skeleton
                          className="h-4"
                          /* Widths vary per column and per row so the block
                             reads as text arriving, not as a loading bar. */
                          style={{ width: `${45 + ((i * 17 + col.key.length * 11) % 45)}%` }}
                        />
                      )}
                    </TableCell>
                  ))}

                </TableRow>
              ))
            : (nodes ??
            rows.map((row) => ({
              kind: "row" as const,
              id: rowId(row),
              depth: 0,
              row,
            }))
          ).map((node) =>
            node.kind === "group" ? (
              <GroupHeaderRow
                key={node.id}
                colSpan={span}
                depth={node.depth}
                label={node.label}
                dimLabel={node.dimLabel}
                count={node.count}
                measure={node.measure}
                unit={groupUnit}
                noun={groupNoun}
                collapsed={Boolean(collapsedGroups?.has(node.id))}
                onToggle={() => onToggleGroupCollapse?.(node.id)}
              />
            ) : (
            /* THE WHOLE ROW OPENS THE RECORD.
               The chevron stays — it is where the eye goes to learn that a row
               CAN be opened, and it is the only part of a 1,400px row a
               keyboard can reach. But making it the only target means a reader
               who has just finished reading a row at the far left has to travel
               the width of the table to act on what they read, and clicking the
               row is what everybody tries first anyway.

               CLICKS THAT LAND ON SOMETHING ELSE ARE NOT ROW CLICKS. A
               checkbox, the chevron, a link inside a cell — each is its own
               act, and an ancestor handler that fired as well would make one
               press do two things. `closest` on the real target is how the row
               tells the difference; a text selection dragged across a cell is
               not a click either. */
            <React.Fragment key={node.id}>
            <TableRow
              className={cn(
                "group/row h-14",
                onOpenRow && "cursor-pointer outline-none focus-visible:bg-fp-row-hover focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50",
                /* The open parent keeps a tint and drops its divider, so the
                   rail runs on into its layer (DS). */
                expanded.has(node.id) && "border-b-0 bg-fp-row-hover hover:bg-fp-row-hover"
              )}
              data-state={selectedIds?.has(node.id) ? "selected" : undefined}
              data-expanded={expanded.has(node.id) ? "true" : undefined}
              /* THE ROW IS THE CONTROL — reachable by keyboard, Enter or
                 Space opens it, and it says what it opens. */
              tabIndex={onOpenRow ? 0 : undefined}
              aria-label={onOpenRow ? openLabel(node.row) : undefined}
              onKeyDown={(e) => {
                if (!onOpenRow || e.target !== e.currentTarget) return;
                if (e.key === "Enter" || e.key === " ") {
                  e.preventDefault();
                  onOpenRow(node.row);
                }
              }}
              onClick={(e) => {
                if (!onOpenRow) return;
                const t = e.target as HTMLElement | null;
                if (t?.closest("button,a,input,label,[role='checkbox'],[data-no-row-open]"))
                  return;
                if (window.getSelection()?.toString()) return;
                onOpenRow(node.row);
              }}
            >
              {selectable && (
                <TableCell className={cn("px-3", expanded.has(node.id) && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70")}>
                  <Checkbox
                    checked={selectedIds!.has(node.id)}
                    onCheckedChange={() => onToggleRow!(node.id)}
                    aria-label={`Select ${openLabel(node.row).replace(/^Open /, "")}`}
                  />
                </TableCell>
              )}
              {visible.map((col, ci) => (
                <TableCell
                  key={col.key}
                  className={cn(
                    "px-3",
                    alignTop && "align-top py-3",
                    /* THE RAIL STARTS ON THE OPEN PARENT'S FIRST CELL. */
                    ci === 0 && !selectable && expanded.has(node.id) && "relative before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70",
                    sort?.key === col.key && "fp-sorted-cell",
                    col.key === actionsKey &&
                      /* THE PINNED CELL WEARS THE ROW'S STATE — hover, an open
                         nested layer, selection — so it never reads as a
                         white box at the end of a tinted row. */
                      "sticky right-0 z-10 bg-fp-surface-1b before:pointer-events-none before:absolute before:inset-0 group-hover/row:before:bg-fp-row-hover group-data-[expanded=true]/row:before:bg-fp-row-hover group-data-[state=selected]/row:before:bg-fp-row-selected"
                  )}
                >
                  <span className={cn(col.key === actionsKey && "relative")}>
                    {col.key === actionsKey ? (
                      <div className="flex justify-end">
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          aria-label={openLabel(node.row)}
                          onClick={() => onOpenRow?.(node.row)}
                        >
                          <ChevronRight />
                        </Button>
                      </div>
                    ) : expandable && ci === 0 ? (
                      /* THE CHEVRON LEADS THE FIRST CELL (DS) — not a column. */
                      <span className="flex min-w-0 items-center gap-1.5">
                        <button
                          type="button"
                          onClick={() => toggleExpand(node.id)}
                          aria-expanded={expanded.has(node.id)}
                          aria-label={expandLabel?.(node.row, expanded.has(node.id)) ?? (expanded.has(node.id) ? "Collapse row" : "Expand row")}
                          className="-ml-1 shrink-0 rounded p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                        >
                          <ChevronRight className={cn("size-4 transition-transform", expanded.has(node.id) && "rotate-90")} />
                        </button>
                        <span className="min-w-0">{renderCell(node.row, col.key)}</span>
                      </span>
                    ) : (
                      renderCell(node.row, col.key)
                    )}
                  </span>
                </TableCell>
              ))}

            </TableRow>
            {expandable && expanded.has(node.id) && (
              <TableRow className="hover:bg-transparent data-[state=selected]:bg-transparent">
                {/* THE LAYER IS WHITE (the content layer), end to end, pinned to
                    the visible width so its columns stay put. Its rail is the
                    parent's — the same 2px strip at the same left edge, so the
                    two meet without a step (Pavan, 2026-10-17). */}
                <TableCell colSpan={span} className="bg-fp-surface-1b p-0">
                  <div className="sticky left-0 bg-fp-surface-1b before:pointer-events-none before:absolute before:inset-y-0 before:left-0 before:w-0.5 before:bg-status-success/70" style={{ width: frameWidth }}>
                    {renderExpanded!(node.row)}
                  </div>
                </TableCell>
              </TableRow>
            )}
            </React.Fragment>
              )
            )}
        </TableBody>
      </Table>
    </div>
  );
  if (!topBar) return body;
  return (
    <div className="flex h-full flex-col overflow-hidden rounded-md border border-border">
      <div className="shrink-0 border-b border-fp-outline-1 bg-fp-surface-1b">{topBar}</div>
      {body}
    </div>
  );
}

/** Primary over a muted secondary — the DS two-line cell. */
/**
 * THE PART OF THE CELL THAT ANSWERED THE FILTER, marked.
 *
 * Reordering the cell so the matched value comes first says WHICH value; this
 * says which part of it. On a column of near-identical names — Clear Diesel #2
 * beside Dyed Diesel — "dies" fetches both and the eye still has to work out
 * what it typed. A mark puts the answer where the question was asked.
 *
 * THE BRAND, AT A QUARTER. The DS binds no meaning to a colour until a usage
 * rule does, and this is the rule: brand is already "the thing you have
 * pointed at" — the active tab, the primary act — and a search match is the
 * same claim about a word. A quarter keeps it a tint under body text rather
 * than a block of fill with letters on top.
 */
export function Hit({
  text,
  q,
}: {
  text: string;
  /**
   * One needle or several. The list search and a column's own filter box are
   * both live at once and both narrowed this row, so both are marked: a reader
   * who typed in two places should see both answers, not whichever the cell
   * happened to be told about.
   */
  q?: string | (string | undefined)[];
}) {
  const needles = (Array.isArray(q) ? q : [q])
    .map((n) => n?.trim().toLowerCase())
    .filter((n): n is string => Boolean(n));
  if (needles.length === 0) return <>{text}</>;

  /* EVERY RUN ANY NEEDLE HITS, merged. Two needles that overlap — "diesel" in
     the search box and "dies" in the column — would otherwise mark the same
     letters twice and split the word into fragments. */
  const hay = text.toLowerCase();
  const spans: [number, number][] = [];
  for (const n of needles) {
    let at = hay.indexOf(n);
    while (at !== -1) {
      spans.push([at, at + n.length]);
      at = hay.indexOf(n, at + 1);
    }
  }
  if (spans.length === 0) return <>{text}</>;
  spans.sort((a, b) => a[0] - b[0]);
  const merged: [number, number][] = [];
  for (const [from, to] of spans) {
    const last = merged[merged.length - 1];
    if (last && from <= last[1]) last[1] = Math.max(last[1], to);
    else merged.push([from, to]);
  }

  const parts: React.ReactNode[] = [];
  let at = 0;
  for (const [from, to] of merged) {
    if (from > at) parts.push(text.slice(at, from));
    parts.push(
      <mark
        key={`${from}-${to}`}
        className="rounded-xs bg-brand/25 font-medium text-foreground"
      >
        {text.slice(from, to)}
      </mark>
    );
    at = to;
  }
  if (at < text.length) parts.push(text.slice(at));
  return <>{parts}</>;
}

export function TwoLineCell({
  title,
  description,
  q,
}: {
  title: string;
  description: string;
  /** Filter text for this column — the matched run is marked. */
  q?: string | (string | undefined)[];
}) {
  return (
    <div className="flex min-w-0 flex-col">
      <span className="truncate text-sm text-foreground">
        <Hit text={title} q={q} />
      </span>
      <span className="truncate text-xs text-muted-foreground">
        <Hit text={description} q={q} />
      </span>
    </div>
  );
}

/**
 * First value plus a `+N` chip for the rest. The chip opens the shared
 * breakdown card ON CLICK (Pavan, 2026-10-14 — one way everywhere; was a
 * hover list). The count is the information here; the first value is only
 * an anchor. Rows may carry a sub-line and a figure (`rows`).
 */
export function OverflowList({
  values,
  label,
  rows,
}: {
  values: string[];
  label: string;
  /** Richer rows for the card — default: one per value. */
  rows?: BreakdownRow[];
}) {
  if (values.length === 0) {
    return <span className="text-sm text-muted-foreground">—</span>;
  }
  const [first, ...rest] = values;
  return (
    <div className="flex min-w-0 items-center gap-1.5">
      <span className="truncate text-sm text-foreground">{first}</span>
      {rest.length > 0 && (
        <OverflowChip
          count={rest.length}
          label={`Show all ${values.length} ${label}`}
          /* WIDER WHEN ROWS CARRY DETAIL — a sub-line and a figure. */
          width={rows ? 360 : undefined}
          card={{
            title: `All ${label} (${values.length})`,
            rows: rows ?? values.map((v) => ({ label: v })),
          }}
        />
      )}
    </div>
  );
}

import * as React from "react";
import { createPortal } from "react-dom";
import {
  Map as MapIcon,
  Columns3,
  GripVertical,
  LayoutList,
  List,
  Search,
  Settings2,
  TextSearch,
  X,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  HoverCard,
  HoverCardContent,
  HoverCardTrigger,
} from "@/components/ui/hover-card";
import { Checkbox } from "@/components/ui/checkbox";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Combobox } from "@/components/ui/combobox";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  GroupByMenu,
  type GroupByDimension,
} from "@/components/tables-layout/GroupByMenu";
import { DateFilter } from "./DateFilter";

/**
 * The action bar, generic over the list it serves.
 *
 * Composition is the DS's CURRENT Data Action Control toolbar
 * (`data-action-control/DataActionControl.tsx`, the finalized Option 1) and is
 * unchanged from what Fuel Orders proved:
 *
 *   LEFT   320px search (leading glyph, trailing clear ×) · Filters · Group By
 *   RIGHT  [date scope] │ view switch │ search-by-column · show/hide columns
 *          (on the board that last pair is replaced by the card-fields menu)
 *
 * Both dividers, `gap-3` left / `gap-1` right, the 32px control height, the
 * ghost `icon-sm` tools with tooltips and the `bg-accent` active state on the
 * view switch are the DS's values.
 *
 * WHAT THIS PARAMETERISES, and why it exists: the facet panel, the column list
 * and the search-by-column fields were welded to one screen's data, so a second
 * list could not reuse the unit. They are props now. This is exactly the change
 * `docs/handoff-ds-adoption-2.md` asks the DS to make to `FilterPanel` and the
 * two column tools — done here first, across three screens, so the DS side has a
 * worked example rather than a description.
 *
 * `dateScope` is OPTIONAL and that is the point: a date stepper belongs on a list
 * whose every row sits on one date, and is meaningless on one that carries no
 * date at all. Fuel Orders and Asset Orders pass it; Customers does not.
 */

/**
 * `map` is opt-in: a list only offers it when its records have a PLACE, which
 * is true of vendors and of nothing else in the Directory. A view toggle that
 * shows a dead third option on every screen teaches people to ignore it.
 */
export type ListView = "table" | "board" | "map";

export interface ListSearchField {
  key: string;
  label: string;
}

export interface ListToolbarProps<K extends string> {
  searchValue: string;
  onSearchChange: (v: string) => void;
  searchPlaceholder: string;
  /** The screen's facet panel — a `Filters` trigger plus its popover. */
  filters: React.ReactNode;
  /**
   * QUICK FILTERS — a segmented control beside the facet panel.
   *
   * For the one or two splits a reader flips between constantly, where opening
   * a panel to tick a box and closing it again is the wrong amount of work.
   * It sits on the LEFT cluster with search and Filters because it narrows the
   * list, which is what everything on that side does; the right-hand side acts
   * on the view. See `docs/ds/ui/2-rules.md` §10.
   *
   * NOT A REPLACEMENT FOR THE PANEL. A split belongs here only when it is
   * exhaustive and short — All plus two or three — and when a reader changes
   * it several times a session. Everything else stays a facet.
   */
  quickFilters?: React.ReactNode;
  /** Right after the Filters button — e.g. Recommendations. */
  afterFilters?: React.ReactNode;
  /**
   * `group` makes an entry a CHILD of the entry with that key — one level, no
   * deeper. A board card is not a flat list of fields: "Customer Details" is a
   * heading with three lines under it, and a reader who wants the account but
   * not the street address had no way to say so while the unit was one switch.
   *
   * Turning a parent off takes its children with it, because the heading is
   * the only thing holding them together; turning the last child off leaves a
   * heading with nothing under it, so it takes the parent too.
   */
  columns: { key: K; label: string; group?: K }[];
  /**
   * THE SAME ORDER THE TABLE IS IN, EDITABLE HERE TOO.
   *
   * Dragging a header is the direct way to move a column and it is only
   * available to columns you can SEE — the one you want is usually the one
   * scrolled off the right edge, which is why you opened this menu. The list
   * is already every column in the table, in order; a grip makes it the place
   * you arrange them as well as the place you choose them.
   *
   * Supply both to turn it on. Left off, the list is still a list.
   */
  columnOrder?: string[];
  onReorderColumns?: (next: string[]) => void;
  hiddenColumns: Set<K>;
  onToggleColumn: (key: K) => void;
  onShowAllColumns: () => void;
  /** Columns the "Search by column" tool can be pointed at. */
  searchFields: ListSearchField[];
  colScope: string;
  onColScopeChange: (v: string) => void;
  colQuery: string;
  onColQueryChange: (v: string) => void;
  /**
   * A FILTER ROW IN THE TABLE, INSTEAD OF A POPOVER THAT SEARCHES ONE COLUMN.
   *
   * The popover asked you to name a column and then type in it — two controls
   * and a menu to do what a box under the header does by sitting there. It
   * also only ever held ONE column at a time, so "Halvorsen, in Fresno" was
   * two searches and the memory of the first. A row of boxes is the same
   * question asked of every column at once, and the answer is where the column
   * is.
   *
   * Supply this and the button becomes a toggle for that row. Leave it off and
   * the popover stays — a table that has not grown the row yet still needs a
   * way to search a column.
   */
  columnFiltersOpen?: boolean;
  onToggleColumnFilters?: () => void;
  /**
   * THE VIEW'S TOOLS IN A BAR ON THE VIEW (Pavan, 2026-10-22 — trial on 3PL
   * Delivery Orders): given, the table's and the board's own tools render
   * into this element — a row above the table header, or above the lanes —
   * with `viewStatement` on the left and the tools on the right ("Search by
   * column", 24px, the columns setting; or Card fields), instead of hanging
   * under the view icons.
   */
  viewToolsInto?: HTMLElement | null;
  /** What the bar says on its left — how many records, over what window. */
  viewStatement?: React.ReactNode;
  /** How many of the row's boxes have something in them. */
  columnFilterCount?: number;
  view: ListView;
  onViewChange: (v: ListView) => void;
  /** Offer the map view. Off unless the records are geographic. */
  mapView?: boolean;
  /**
   * WHETHER THIS LIST HAS A BOARD AT ALL. Default FALSE (2026-10-01) — most
   * lists here have no board, and the ones that do say so.
   *
   * The same call `mapView` makes, and for the same reason: a view switch that
   * offers a board to a list with no board is a dead control, and the rule
   * three lines down — the one that hides the column tools off the table —
   * exists precisely because a control with nothing behind it is worse than no
   * control. A list of standing arrangements has no lanes to put them in.
   */
  boardView?: boolean;
  /** Omit entirely on lists that are not date-scoped. */
  dateScope?: { date: Date; onDateChange: (d: Date) => void };
  /**
   * A DIFFERENT date control, in the same slot. 3PL scopes by a RANGE because a
   * broker's delivery windows run over weekends and a one-day view of those is
   * a lane that keeps looking empty — but that is 3PL's answer, not every
   * list's, so it is supplied rather than switched on. Wins over `dateScope`.
   */
  dateControl?: React.ReactNode;
  /**
   * Grouping. `dimensions` are a property of the list's DATA, so each screen
   * supplies its own; the menu is ordered and capped at two levels.
   */
  groupBy?: {
    dimensions: GroupByDimension[];
    value: string[];
    onChange: (next: string[]) => void;
  };
  /**
   * OFF WHERE THE VIEW IS ALREADY GROUPED.
   *
   * Grouping cuts a flat list into headed sections. A board has no flat list to
   * cut: it is already sections, one per lane, and that grouping is the view
   * itself rather than a setting on it. A second dimension over the top would
   * have to nest — groups inside lanes, or lanes inside groups — and neither is
   * a board any more. The control stayed on screen doing nothing, which is
   * worse than not offering it.
   */
  showGroupBy?: boolean;
  /**
   * WHAT IS ON THE CARD — the board's own version of the column menu.
   *
   * A card is not a table row: the reader is not choosing columns, they are
   * choosing which UNITS of the record the card carries, and those units nest.
   * "Customer Details" is a heading with three lines under it, and somebody who
   * wants the account but not the street address has to be able to say so.
   *
   * It is a SEPARATE control rather than the column menu re-aimed, because one
   * icon that changes its subject with the view is one icon nobody can read
   * (`docs/ds/ui/2-rules.md` §10). This one is named for the card, carries its
   * own icon, and appears only on the board.
   *
   * NO ORDERING HERE. A card's units read top to bottom in the order the work
   * happens — who it is for, when, what, and who is taking it — which is the
   * card's design, not a preference.
   */
  cardFields?: {
    units: { key: string; label: string; group?: string }[];
    hidden: ReadonlySet<string>;
    onToggle: (key: string) => void;
    onShowAll: () => void;
    /**
     * WHICH LANE THE MENU IS SPEAKING FOR. `null` is every lane at once.
     *
     * A board card is not one design repeated down the page — what a card in
     * the first lane should say is not what one in the last should — so a
     * single field list could only ever be right for one lane. The scope is
     * the first thing in the menu because it changes what every tick under it
     * means.
     */
    scope?: string | null;
    scopes?: { key: string; label: string }[];
    onScopeChange?: (scope: string | null) => void;
  };
}

/* A VIEW-BAR TOOL IS ITS ICON; its name slides out on hover (Pavan,
   2026-10-22) — 12px, a darker grey, never black. NO FILL, ever: not on
   hover, not when on. WHILE IT IS ON — the column search row open
   (aria-pressed), a menu open (aria-expanded; the tooltip owns data-state)
   — the name stays out. */
const BAR_TOOL =
  "group/tool h-8 gap-0 px-2 text-xs font-normal text-muted-foreground transition-[gap] duration-200 hover:bg-transparent hover:gap-1.5 hover:text-muted-foreground focus-visible:gap-1.5 aria-pressed:gap-1.5 aria-expanded:gap-1.5 dark:hover:bg-transparent";
function Reveal({ children }: { children: React.ReactNode }) {
  return (
    <span className="max-w-0 overflow-hidden whitespace-nowrap opacity-0 transition-all duration-200 group-hover/tool:max-w-48 group-hover/tool:opacity-100 group-focus-visible/tool:max-w-48 group-focus-visible/tool:opacity-100 group-aria-pressed/tool:max-w-48 group-aria-pressed/tool:opacity-100 group-aria-expanded/tool:max-w-48 group-aria-expanded/tool:opacity-100">
      {children}
    </span>
  );
}

/** STACKED CARDS — the board's icon in the display switch (Pavan's reference). */
function CardsIcon() {
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <rect x="4" y="3.5" width="16" height="7.5" rx="2.5" />
      <rect x="4" y="13" width="16" height="7.5" rx="2.5" />
    </svg>
  );
}

/** Icon button in the toolbar, wrapped in a tooltip. The DS's `IconTool`. */
export function IconTool({
  label,
  view,
  active,
  onClick,
  children,
}: {
  label: string;
  /** Which display it switches to — where the routing line starts. */
  view?: string;
  active?: boolean;
  onClick?: () => void;
  children: React.ReactNode;
}) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={label}
          data-view={view}
          onClick={onClick}
          // Same fill as the chips: `--chip`, not `--accent`. At #cad1db the
          // control-emphasis token sits far too heavy on white inside a 32px
          // button. Dark is unchanged — `--chip` is #2a2f37 there.
          className={cn(active && "bg-chip text-foreground")}
        >
          {children}
        </Button>
      </TooltipTrigger>
      <TooltipContent>{label}</TooltipContent>
    </Tooltip>
  );
}

export function ListToolbar<K extends string>({
  searchValue,
  onSearchChange,
  searchPlaceholder,
  filters,
  quickFilters,
  afterFilters,
  columns,
  hiddenColumns,
  onToggleColumn,
  onShowAllColumns,
  searchFields,
  colScope,
  onColScopeChange,
  colQuery,
  onColQueryChange,
  columnFiltersOpen,
  onToggleColumnFilters,
  viewToolsInto,
  viewStatement,
  columnFilterCount = 0,
  columnOrder,
  onReorderColumns,
  view,
  onViewChange,
  mapView = false,
  boardView = false,
  dateScope,
  dateControl,
  groupBy,
  showGroupBy = true,
  cardFields,
}: ListToolbarProps<K>) {
  const multiView = boardView || mapView;
  const colLabel =
    searchFields.find((f) => f.key === colScope)?.label ?? "column";
  const shown = columns.filter((c) => !hiddenColumns.has(c.key)).length;
  const cardShown = cardFields
    ? cardFields.units.filter((u) => !cardFields.hidden.has(u.key)).length
    : 0;

  /* THE LIST FOLLOWS THE TABLE. Reading them in a different sequence from the
     columns they stand for would make the menu a second opinion about the
     order rather than a view of it. Keys the order has not heard of keep their
     declared place, which is how a saved view survives a new column. */
  const reorderable = Boolean(columnOrder && onReorderColumns);
  const ordered = React.useMemo(() => {
    if (!columnOrder) return columns;
    const rank = new Map(columnOrder.map((k, i) => [k, i]));
    return [...columns].sort((a, b) => {
      const ai = rank.get(a.key) ?? columns.findIndex((c) => c.key === a.key);
      const bi = rank.get(b.key) ?? columns.findIndex((c) => c.key === b.key);
      return ai - bi;
    });
  }, [columns, columnOrder]);

  const [dragKey, setDragKey] = React.useState<string | null>(null);
  const [overKey, setOverKey] = React.useState<string | null>(null);
  /** Puts `key` where `target` sits. */
  const moveColumn = (key: string, target: string) => {
    if (!onReorderColumns || key === target) return;
    const keys = ordered.map((c) => c.key as string);
    const next = keys.filter((k) => k !== key);
    next.splice(next.indexOf(target), 0, key);
    onReorderColumns(next);
  };
  /** One step up or down — the keyboard's version of the same move. */
  const nudgeColumn = (key: string, delta: -1 | 1) => {
    const keys = ordered.map((c) => c.key as string);
    const at = keys.indexOf(key);
    const to = at + delta;
    if (at === -1 || to < 0 || to >= keys.length) return;
    onReorderColumns?.(
      (() => {
        const next = [...keys];
        next.splice(at, 1);
        next.splice(to, 0, key);
        return next;
      })()
    );
  };

  /* COLUMN TOOLS ARE A TABLE'S TOOLS, AND ONLY A TABLE'S.

            Search by column and Show/Hide columns both name a thing the reader
            can see: a header to type under, a column to take away. On a board
            or a map there are no columns on screen, so the controls were either
            doing nothing or — worse, on the board — quietly redefining
            themselves to mean the card's units, which is a second meaning for
            one button that nobody could guess from the icon.

            The board's units did not go away with the button: they have their
            own control below, named for the card and shown only on the board.

            THIS IS A LIST RULE, NOT A 3PL ONE: it lives here so every screen
            using this toolbar gets it. See `docs/ds/ui/2-rules.md` §10. */
  const inBar = Boolean(viewToolsInto);
  const tableTools = (
    <>
        {/* Search by column — the row, where the table has one. */}
        {onToggleColumnFilters ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size={inBar ? "sm" : "icon-sm"}
                aria-label="Search by column"
                aria-pressed={columnFiltersOpen}
                onClick={onToggleColumnFilters}
                className={cn(
                  inBar
                    ? BAR_TOOL
                    : (columnFiltersOpen || columnFilterCount > 0) && "bg-accent text-foreground"
                )}
              >
                <TextSearch />
                {inBar && <Reveal>Search by column</Reveal>}
              </Button>
            </TooltipTrigger>
            <TooltipContent className={cn(inBar && "hidden")}>
              {columnFiltersOpen ? "Hide column search" : "Search by column"}
            </TooltipContent>
          </Tooltip>
        ) : (
        <Popover>
          <Tooltip>
            <TooltipTrigger asChild>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size={inBar ? "sm" : "icon-sm"}
                  aria-label="Search by column"
                  className={cn(inBar ? BAR_TOOL : colQuery.trim() && "text-foreground")}
                >
                  <TextSearch />
                  {inBar && <Reveal>Search by column</Reveal>}
                </Button>
              </PopoverTrigger>
            </TooltipTrigger>
            <TooltipContent className={cn(inBar && "hidden")}>Search by column</TooltipContent>
          </Tooltip>
          <PopoverContent align="end" className="w-64 space-y-2 p-3">
            <div className="flex items-center gap-1.5 text-xs font-medium text-muted-foreground">
              <TextSearch className="size-3.5" /> Search by column
            </div>
            <Combobox
              size="sm"
              className="w-full"
              value={colScope}
              onValueChange={onColScopeChange}
              options={searchFields.map((f) => ({
                value: f.key,
                label: f.label,
              }))}
              placeholder="Choose a column"
              searchPlaceholder="Search columns…"
              emptyText="No column found."
            />
            <div className="relative">
              <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                value={colQuery}
                onChange={(e) => onColQueryChange(e.target.value)}
                placeholder={`Find in ${colLabel}…`}
                className={cn("h-8 pl-8", colQuery && "pr-8")}
              />
              {colQuery && (
                <button
                  type="button"
                  aria-label="Clear column search"
                  onClick={() => onColQueryChange("")}
                  className="absolute top-1/2 right-2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                >
                  <X className="size-3.5" />
                </button>
              )}
            </div>
          </PopoverContent>
        </Popover>
        )}

        {/* Show/Hide columns */}
        <Popover>
          <Tooltip>
            <TooltipTrigger asChild>
              <PopoverTrigger asChild>
                <Button
                  variant="ghost"
                  size={inBar ? "sm" : "icon-sm"}
                  aria-label="Show/Hide columns"
                  className={cn(inBar && BAR_TOOL)}
                >
                  {inBar ? <Settings2 /> : <Columns3 />}
                  {inBar && <Reveal>Show/hide columns</Reveal>}
                </Button>
              </PopoverTrigger>
            </TooltipTrigger>
            <TooltipContent className={cn(inBar && "hidden")}>Show/Hide columns</TooltipContent>
          </Tooltip>
          <PopoverContent align="end" className="w-56 p-1">
            <div className="flex items-center justify-between px-2 py-1.5">
              <span className="text-xs font-medium text-muted-foreground">
                Columns
              </span>
              <span className="rounded bg-fp-card-1 px-1.5 text-[11px] tabular-nums text-muted-foreground">
                {shown}/{columns.length}
              </span>
            </div>
            <div className="max-h-64 overflow-y-auto">
              {ordered.map((c) => {
                const draggable = reorderable && !c.group;
                return (
                  <div
                    key={c.key}
                    draggable={draggable}
                    onDragStart={
                      draggable
                        ? (e) => {
                            setDragKey(c.key);
                            e.dataTransfer.effectAllowed = "move";
                            /* Firefox starts no drag without payload. */
                            e.dataTransfer.setData("text/plain", c.key);
                          }
                        : undefined
                    }
                    onDragOver={
                      draggable
                        ? (e) => {
                            if (!dragKey || dragKey === c.key) return;
                            e.preventDefault();
                            setOverKey(c.key);
                          }
                        : undefined
                    }
                    onDrop={
                      draggable
                        ? (e) => {
                            e.preventDefault();
                            if (dragKey) moveColumn(dragKey, c.key);
                            setDragKey(null);
                            setOverKey(null);
                          }
                        : undefined
                    }
                    onDragEnd={() => {
                      setDragKey(null);
                      setOverKey(null);
                    }}
                    className={cn(
                      "flex items-center rounded-sm transition-colors hover:bg-accent has-[:focus-visible]:bg-accent",
                      dragKey === c.key && "opacity-40",
                      /* WHERE IT WILL LAND, on the row it will land on. A line
                         between rows would need to know which side of the gap
                         the pointer is on; tinting the target says the same
                         thing and cannot be off by one. */
                      overKey === c.key && dragKey && "bg-accent"
                    )}
                  >
                    {reorderable && (
                      <span
                        className={cn(
                          "flex w-5 shrink-0 items-center justify-center self-stretch",
                          draggable
                            ? "cursor-grab text-muted-foreground active:cursor-grabbing"
                            : "opacity-0"
                        )}
                        aria-hidden={!draggable}
                      >
                        {draggable && <GripVertical className="size-3.5" />}
                      </span>
                    )}
                    <label
                      className={cn(
                        "flex flex-1 cursor-pointer items-center gap-2 py-1.5 pr-2 text-sm",
                        /* THE INDENT IS THE ONLY THING SAYING "UNDER". A child
                           at the parent's left edge is a sibling with a smaller
                           label; the offset and the lighter weight say which
                           heading it belongs to without a line or a disclosure
                           arrow. */
                        c.group
                          ? "pl-5 text-[13px] text-muted-foreground"
                          : reorderable
                            ? "pl-0"
                            : "pl-2"
                      )}
                      /* THE KEYBOARD MOVES IT TOO. A grip nobody can reach
                         without a mouse is an ordering only some readers get
                         to change. */
                      onKeyDown={
                        draggable
                          ? (e) => {
                              if (e.key === "ArrowUp" || e.key === "ArrowDown") {
                                e.preventDefault();
                                nudgeColumn(c.key, e.key === "ArrowUp" ? -1 : 1);
                              }
                            }
                          : undefined
                      }
                    >
                      <Checkbox
                        checked={!hiddenColumns.has(c.key)}
                        onCheckedChange={() => onToggleColumn(c.key)}
                      />
                      <span className="flex-1 truncate">{c.label}</span>
                    </label>
                  </div>
                );
              })}
            </div>
            <Separator className="my-1" />
            {/* SHOW ALL, AND NOTHING FACING IT. Hide all emptied the table —
                a control whose only outcome is a screen with no data in it,
                sitting one slip of the hand from the one people actually use.
                Show all is a way BACK from a narrowing, which is the only one
                of the two anybody was reaching for; alone, it goes to the
                right, where the act in a footer belongs. */}
            <div className="flex justify-end">
              <Button
                variant="ghost"
                size="sm"
                disabled={hiddenColumns.size === 0}
                onClick={onShowAllColumns}
              >
                Show all
              </Button>
            </div>
          </PopoverContent>
        </Popover>
    </>
  );
  /* WHAT IS ON THE CARD — the board's own control, in the slot the
            column tools vacate. Same place, different subject, and the subject
            is written at the top of the menu and spoken by the icon, so the
            two can never be mistaken for one control that moved. */
  const boardTools = cardFields ? (
    <>
            <Popover>
              <Tooltip>
                <TooltipTrigger asChild>
                  <PopoverTrigger asChild>
                    <Button
                      variant="ghost"
                      size={inBar ? "sm" : "icon-sm"}
                      aria-label="Card fields"
                      className={cn(inBar && BAR_TOOL)}
                    >
                      <LayoutList />
                      {inBar && <Reveal>Card configuration</Reveal>}
                    </Button>
                  </PopoverTrigger>
                </TooltipTrigger>
                <TooltipContent className={cn(inBar && "hidden")}>Card fields</TooltipContent>
              </Tooltip>
              <PopoverContent align="end" className="w-60 p-1">
                <div className="flex items-center justify-between px-2 py-1.5">
                  <span className="text-xs font-medium text-muted-foreground">
                    Card fields
                  </span>
                  <span className="rounded bg-fp-card-1 px-1.5 text-[11px] tabular-nums text-muted-foreground">
                    {cardShown}/{cardFields.units.length}
                  </span>
                </div>
                {/* WHICH CARDS THIS IS ABOUT, above the ticks it governs. A
                    card in the first lane and one in the last are answering
                    different questions, so the field list has to be able to
                    differ between them — and the reader has to be told which
                    set they are editing BEFORE they edit it, not after. */}
                {cardFields.scopes && cardFields.onScopeChange && (
                  <div className="px-2 pb-2">
                    <Combobox
                      size="sm"
                      className="w-full"
                      value={cardFields.scope ?? ALL_LANES}
                      onValueChange={(v) =>
                        cardFields.onScopeChange?.(v === ALL_LANES ? null : v)
                      }
                      options={[
                        { value: ALL_LANES, label: "All lanes" },
                        ...cardFields.scopes.map((sc) => ({
                          value: sc.key,
                          label: sc.label,
                        })),
                      ]}
                      placeholder="All lanes"
                      searchPlaceholder="Search lanes…"
                      emptyText="No lane found."
                    />
                  </div>
                )}
                <div className="max-h-64 overflow-y-auto">
                  {/* A TOGGLE PER CATEGORY, a tick per field inside it (Pavan,
                      2026-09-23). The category — Customer, Asset & Fault — is
                      the decision somebody actually makes about a card, so it
                      is a switch: on or off, and it reads that way. Its fields
                      are the finer adjustment, shown only while the category
                      is on, because ticking a field inside a hidden block
                      changes nothing anybody can see. */}
                  {cardFields.units.map((u) => {
                    if (!u.group) {
                      const on = !cardFields.hidden.has(u.key);
                      return (
                        <label
                          key={u.key}
                          className="flex cursor-pointer items-center gap-2 rounded-sm px-2 py-1.5 text-sm transition-colors hover:bg-accent has-[:focus-visible]:bg-accent"
                        >
                          <span className="flex-1 truncate">{u.label}</span>
                          <Switch
                            size="sm"
                            checked={on}
                            onCheckedChange={() => cardFields.onToggle(u.key)}
                          />
                        </label>
                      );
                    }
                    if (cardFields.hidden.has(u.group)) return null;
                    return (
                      <label
                        key={u.key}
                        className="flex cursor-pointer items-center gap-2 rounded-sm py-1.5 pr-2 pl-5 text-[13px] text-muted-foreground transition-colors hover:bg-accent has-[:focus-visible]:bg-accent"
                      >
                        <Checkbox
                          checked={!cardFields.hidden.has(u.key)}
                          onCheckedChange={() => cardFields.onToggle(u.key)}
                        />
                        <span className="flex-1 truncate">{u.label}</span>
                      </label>
                    );
                  })}
                </div>
                <Separator className="my-1" />
                <div className="flex justify-end">
                  <Button
                    variant="ghost"
                    size="sm"
                    disabled={cardFields.hidden.size === 0}
                    onClick={cardFields.onShowAll}
                  >
                    Show all
                  </Button>
                </div>
              </PopoverContent>
            </Popover>
    </>
  ) : null;
  const activeTools = inBar ? null : view === "table" ? tableTools : view === "board" ? boardTools : null;

  /* WHERE THE ROUTING LINE DROPS FROM — the active icon's centre, measured. */
  const rightRef = React.useRef<HTMLDivElement>(null);
  const [routeX, setRouteX] = React.useState(0);
  React.useLayoutEffect(() => {
    const box = rightRef.current;
    if (!box) return;
    const place = () => {
      const icon = box.querySelector<HTMLElement>(`[data-view="${view}"]`);
      if (!icon) return;
      const a = box.getBoundingClientRect();
      const b = icon.getBoundingClientRect();
      setRouteX(Math.round(b.left - a.left + b.width / 2));
      /* THE CHIPS' RIGHT EDGE — they share the tools' row and stop short of
         the right cluster. Set on the parent: the chip row is a sibling. */
      box.parentElement?.parentElement?.style.setProperty("--fp-routed-w", `${Math.round(a.width) + 16}px`);
    };
    place();
    const ro = new ResizeObserver(place);
    ro.observe(box);
    return () => ro.disconnect();
  }, [view]);

  return (
    /* TOP-ALIGNED — the routed tools hang below the right cluster, and the
       search row stays level with the view icons. `data-routed` lets the
       filter chips that follow rise into the tools' row (index.css). */
    <div
      data-routed={multiView && activeTools ? "" : undefined}
      className="flex flex-wrap items-start justify-between gap-3"
    >
      {/* LEFT — quick filters · search · Filters · Group By

          THE QUICK FILTERS COME FIRST, before the search box, because they are
          the coarsest cut on the row: they decide WHICH SET you are searching
          and filtering inside. Reading left to right then matches the order
          somebody actually narrows — pick the book, then find the row. */}
      <div className="flex items-center gap-3">
        {quickFilters}
        {/* FIXED WIDTH — the list search box is the DS's 320px, the same on
            every list; it is not a row of fields. */}
        <div className="relative w-[320px]">
          <Search className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            value={searchValue}
            onChange={(e) => onSearchChange(e.target.value)}
            placeholder={searchPlaceholder}
            aria-label="Search all columns"
            className={cn("h-8 pl-8", searchValue && "pr-8")}
          />
          {searchValue && (
            <button
              type="button"
              aria-label="Clear search"
              onClick={() => onSearchChange("")}
              className="absolute top-1/2 right-2 -translate-y-1/2 rounded-sm p-0.5 text-muted-foreground outline-none hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <X className="size-3.5" />
            </button>
          )}
        </div>
        {filters}
        {afterFilters}
        {/* WHY (Pavan, 2026-10-07). Group By only when the screen hands it real
           dimensions. With none, the menu fell back to the DS demo dims and
           grouped nothing — a dead control on every screen that forgot to
           switch it off (G8). */}
        {showGroupBy && groupBy && groupBy.dimensions.length > 0 && (
          <GroupByMenu
            dimensions={groupBy.dimensions}
            value={groupBy.value}
            onChange={groupBy.onChange}
          />
        )}
      </div>

      {/* RIGHT — [date]   view switch, and under the view you are on, its own
          tools, joined to it by a line (Pavan, 2026-10-22). */}
      <div ref={rightRef} className="flex flex-col items-start">
      <div className="flex items-center gap-1">
        {(dateControl ?? dateScope) && (
          <>
            {dateControl ?? (
              <DateFilter
                value={dateScope!.date}
                onChange={dateScope!.onDateChange}
              />
            )}
            {/* SPACE, NOT A RULE (Pavan, 2026-10-05): 12px plus the row's 4px
                gap each side — 20px between the date and the view switch. */}
            <div className="w-3 shrink-0" aria-hidden />
          </>
        )}

        {/* ONE VIEW, NO SWITCH (Pavan, 2026-10-01). A table-only list gets no
            Table-view icon — a switch with one position switches nothing.
            The column tools after it stay: they belong to the table. */}
        {/* THE DISPLAY SWITCH — ONE SEGMENTED CONTROL (Pavan, 2026-10-23,
            after his reference): a bordered pill of segments, the view you
            are on filled grey; icons that say the view — a list for the
            table, stacked cards for the board, a map. */}
        {multiView && (
          <div role="group" aria-label="Display" className="inline-flex h-8 shrink-0 overflow-hidden rounded-md border border-border bg-fp-surface-1b">
            {[
              { key: "table" as const, label: "Table view", icon: <List />, on: true },
              { key: "board" as const, label: "Board view", icon: <CardsIcon />, on: boardView },
              { key: "map" as const, label: "Map view", icon: <MapIcon />, on: mapView },
            ]
              .filter((v) => v.on)
              .map((v, i) => (
                <Tooltip key={v.key}>
                  <TooltipTrigger asChild>
                    <button
                      type="button"
                      aria-label={v.label}
                      aria-pressed={view === v.key}
                      data-view={v.key}
                      onClick={() => onViewChange(v.key)}
                      className={cn(
                        "inline-flex w-9 items-center justify-center text-muted-foreground outline-none transition-colors hover:bg-fp-row-hover hover:text-foreground focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring/50 [&_svg]:size-4",
                        i > 0 && "border-l border-border",
                        view === v.key && "bg-muted text-foreground hover:bg-muted"
                      )}
                    >
                      {v.icon}
                    </button>
                  </TooltipTrigger>
                  <TooltipContent>{v.label}</TooltipContent>
                </Tooltip>
              ))}
          </div>
        )}

        {/* A ONE-VIEW LIST KEEPS ITS TOOLS IN THE ROW — there is no switch
            for them to hang from. */}
        {!multiView && view === "table" && !inBar && tableTools}
      </div>
      {/* THE ACTIVE VIEW'S TOOLS, ROUTED FROM ITS ICON — a line drops from
          under the icon and turns into the tools, so they read as the
          table's (or the board's) and nothing else's. */}
      {multiView && activeTools && (
        <div className="flex items-start" style={{ paddingLeft: routeX }}>
          <span aria-hidden className="h-4 w-3 shrink-0 rounded-bl-md border-b border-l border-muted-foreground/40" />
          <span className="flex items-center gap-1">{activeTools}</span>
        </div>
      )}
      </div>
      {viewToolsInto &&
        (view === "table" || view === "board") &&
        createPortal(
          <div className="flex h-11 items-center justify-between gap-3 px-3">
            <span className="min-w-0 truncate text-sm text-muted-foreground">{viewStatement}</span>
            <span className="flex shrink-0 items-center gap-1">{view === "table" ? tableTools : boardTools}</span>
          </div>,
          viewToolsInto
        )}
    </div>
  );
}

/* The scope option standing for "every lane". A sentinel rather than "" —
   the combobox treats an empty value as nothing chosen. */
const ALL_LANES = "__all__";

/** The active column-search chip the DS unit renders under the toolbar. */
export function ColumnSearchChip({
  searchFields,
  colScope,
  colQuery,
  onClear,
  className = "mt-3",
}: {
  searchFields: ListSearchField[];
  colScope: string;
  colQuery: string;
  onClear: () => void;
  /** Overridable so the chip can join a shelf that already has its own top
   *  margin — see `FilterChips`, which is the other thing on that shelf. */
  className?: string;
}) {
  if (!colQuery.trim()) return null;
  const label = searchFields.find((f) => f.key === colScope)?.label ?? "column";
  return (
    <div className={cn("flex shrink-0 items-center gap-2", className)}>
      <span className="inline-flex h-7 items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground">
        <Search className="size-3 text-muted-foreground" />
        {label}: “{colQuery}”
        <button
          type="button"
          aria-label="Clear column search"
          onClick={onClear}
          className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
        >
          <X className="size-3" />
        </button>
      </span>
    </div>
  );
}

/**
 * THE FILTERS THAT ARE ON, as one chip per facet under the toolbar.
 *
 * A COUNT IS NOT AN ANSWER. "Filters 7" says the list has been narrowed and
 * refuses to say how — the only way to find out was to open the panel, walk
 * six facets and read the checkboxes, which is the whole of what this shelf
 * does at a glance. And a narrowing you cannot see is one you forget you
 * applied: the short list that follows reads as "no customers" rather than "no
 * customers that match the seven things you asked for".
 *
 * ONE CHIP PER FACET, NOT PER VALUE. Per value, three cities were three chips
 * that said "City" three times to say one thing — and the row grew with the
 * TICKS rather than with the questions, so picking six cities buried the one
 * status filter that was also on. Grouped, the shelf is as long as the number
 * of QUESTIONS you have asked, which is a small number and a stable one, and
 * the shape of the narrowing is legible from across the room: Status, City,
 * Vendor.
 *
 * ONE VALUE SHOWS ITSELF; SEVERAL SHOW A COUNT. "City: Bakersfield" is shorter
 * than "City 1" and says more, so a lone value is never hidden behind a digit.
 * Past one there is no width to say them all and no honest way to pick which
 * one to print, so the chip says how many and the hover card says which —
 * WITH their own crosses, because the reason to look at this row is usually to
 * take ONE thing off, and a group that could only be removed whole would send
 * you back to the panel to do it.
 *
 * ONE LINE, ALWAYS — IT SCROLLS RATHER THAN WRAPS. This shelf sits between the
 * toolbar and the data and every pixel of it comes out of the data. Wrapped,
 * its height is a function of how many filters are on and how long their names
 * are. Grouping makes a second line unlikely; the scroller makes it
 * impossible, which is the only promise worth making about a strip in this
 * position.
 */
export function FilterChips({
  facets,
  selected,
  onChange,
  className,
  children,
}: {
  /** Key → label, in the order the panel lists them. */
  facets: { key: string; label: string }[];
  /** Applied ids, as `facetKey:option` — what `ListFilters` emits. */
  selected: ReadonlySet<string>;
  onChange: (next: ReadonlySet<string>) => void;
  className?: string;
  /** Anything else on the same shelf — the column-search chip, usually. */
  children?: React.ReactNode;
}) {
  const ids = [...selected];
  if (ids.length === 0) return children ? <>{children}</> : null;

  const drop = (gone: string[]) => {
    const next = new Set(selected);
    for (const id of gone) next.delete(id);
    onChange(next);
  };

  /* GROUPED IN THE PANEL'S OWN ORDER, so the shelf and the facet menu read the
     same way round. Ids whose facet is not declared keep their raw key and go
     last rather than disappearing. */
  const groups: { key: string; label: string; ids: string[] }[] = [];
  const bucket = (key: string, label: string) => {
    let g = groups.find((x) => x.key === key);
    if (!g) groups.push((g = { key, label, ids: [] }));
    return g;
  };
  for (const f of facets) {
    const mine = ids.filter((id) => id.startsWith(`${f.key}:`));
    if (mine.length) bucket(f.key, f.label).ids.push(...mine);
  }
  for (const id of ids) {
    /* SPLIT ON THE FIRST COLON ONLY — a ship-to option can hold one. */
    const key = id.slice(0, id.indexOf(":"));
    if (!facets.some((f) => f.key === key)) bucket(key, key).ids.push(id);
  }

  const valueOf = (id: string) => id.slice(id.indexOf(":") + 1);

  return (
    <div data-filter-chips className={cn("mt-3 flex shrink-0 items-center gap-2", className)}>
      {/* THE CHIPS TAKE ONLY THE WIDTH THEY NEED, so Clear all sits right
          after the last one (Pavan, 2026-10-09); past the row's width they
          still scroll rather than wrap. */}
      <div className="flex min-w-0 items-center gap-2 overflow-x-auto">
        {groups.map((g) => {
          const one = g.ids.length === 1;
          const chip = (
            <span
              className={cn(
                /* A REMOVABLE PILL (Pavan, 2026-10-09): the pill recipe with its ✕ inside. */
                "inline-flex h-7 max-w-[260px] shrink-0 items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground",
                !one && "cursor-default"
              )}
            >
              <span className="truncate">
                <span className="text-muted-foreground">
                  {g.label}
                  {one ? ": " : " "}
                </span>
                {one ? valueOf(g.ids[0]) : null}
              </span>
              {!one && (
                <span className="shrink-0 rounded-full bg-background px-1.5 tabular-nums">
                  {g.ids.length}
                </span>
              )}
              <button
                type="button"
                aria-label={
                  one
                    ? `Remove filter ${g.label}: ${valueOf(g.ids[0])}`
                    : `Remove all ${g.ids.length} ${g.label} filters`
                }
                onClick={() => drop(g.ids)}
                className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
              >
                <X className="size-3" />
              </button>
            </span>
          );

          if (one) return <React.Fragment key={g.key}>{chip}</React.Fragment>;

          return (
            <HoverCard key={g.key} openDelay={120} closeDelay={120}>
              <HoverCardTrigger asChild>{chip}</HoverCardTrigger>
              <HoverCardContent
                align="start"
                className="w-auto max-w-[280px] min-w-[180px] p-1.5"
              >
                <p className="px-1.5 pb-1 text-[10px] font-semibold tracking-[0.12em] text-muted-foreground uppercase">
                  {g.label}
                </p>
                <ul className="flex flex-col">
                  {g.ids.map((id) => (
                    <li
                      key={id}
                      className="flex items-center gap-2 rounded-sm py-0.5 pr-0.5 pl-1.5 hover:bg-accent/60"
                    >
                      <span className="min-w-0 flex-1 truncate text-xs text-foreground">
                        {valueOf(id)}
                      </span>
                      <button
                        type="button"
                        aria-label={`Remove filter ${g.label}: ${valueOf(id)}`}
                        onClick={() => drop([id])}
                        className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
                      >
                        <X className="size-3" />
                      </button>
                    </li>
                  ))}
                </ul>
              </HoverCardContent>
            </HoverCard>
          );
        })}
        {children}
      </div>
      {/* PINNED OUTSIDE THE SCROLLER, because the way out of a narrowing must
          not itself be somewhere you have to scroll to. Clear All is in the
          panel too — this is where you are when you decide you want none of
          it. */}
      <button
        type="button"
        onClick={() => onChange(new Set())}
        className="shrink-0 rounded-sm text-sm text-muted-foreground underline-offset-2 outline-none hover:text-foreground hover:underline focus-visible:ring-2 focus-visible:ring-ring/50"
      >
        Clear all
      </button>
    </div>
  );
}

/*
  THE VIEW BAR (Pavan, 2026-10-22) — a row ON the view: above the table
  header (`ListTable topBar`), or above the lanes (`BoardWithBar`). Its left
  says what is shown; its right carries the view's own tools, which the
  toolbar renders into it (`ListToolbar viewToolsInto`). Every list with a
  table or a board has one.
*/
export function useViewBar() {
  const [into, setInto] = React.useState<HTMLDivElement | null>(null);
  return { into, ref: setInto, slot: <div ref={setInto} /> };
}

/** "62 orders · Thu, Oct 22, 2026" — the count leads, the rest follows. */
export function ViewStatement({
  count,
  one,
  many,
  rest,
}: {
  count: number;
  one: string;
  many: string;
  /** What follows the count — the lanes, the window. */
  rest?: string;
}) {
  return (
    <>
      <span className="font-medium text-foreground">
        {count.toLocaleString()} {count === 1 ? one : many}
      </span>
      {rest ? ` ${rest}` : ""}
    </>
  );
}

/** A board under its view bar — the bar a white strip, the lanes below. */
export function BoardWithBar({
  barRef,
  children,
}: {
  barRef: (el: HTMLDivElement | null) => void;
  children: React.ReactNode;
}) {
  return (
    <div className="flex h-full min-h-0 flex-col gap-3">
      <div ref={barRef} className="shrink-0 rounded-md border border-border bg-fp-surface-1b" />
      <div className="min-h-0 flex-1">{children}</div>
    </div>
  );
}

import * as React from "react";
import { MapPin, Truck } from "lucide-react";
import { HoverCard, HoverCardContent, HoverCardTrigger } from "@/components/ui/hover-card";
import { StatusChip, type StatusTone } from "@/components/ui/status-chip";
import type { PillColor } from "@/components/ui/pill";
import { cn } from "@/lib/utils";
import { SHIP_TO_SITES } from "./threepl/orders";

/*
  Orders on a map — list left, plot right.

  WHY A MAP AT ALL. Every other question about an order is answered by a
  column; "what else is going out near this one" is not, because near is a
  relationship between two places and a table can only sort by one of them. A
  dispatcher deciding whether two drops can share a truck is doing geometry,
  and a list sorted by time is the wrong instrument for it.

  IT IS NOT A REAL MAP, and it does not pretend to be. There is no tile
  provider in this prototype and adding one would put a network dependency and
  an API key into a file that is meant to open from disk. What it draws is the
  geography the data actually has: every ship-to site carries its own latLng,
  so the arrangement is true. Swap the backdrop for tiles and the pins do not
  move.

  THE TWO HALVES ARE ONE SELECTION. Hovering a row lights its pin and hovering
  a pin lights its rows; clicking either opens the order.

  ONE MAP, EVERY ORDERS SCREEN. It takes `MapOrder`, not any module's row type:
  the four things a pin needs are an id, a number, a SITE and a status, and
  every orders list in the app can produce those. Forking it per module would
  mean the same screen behaving differently depending on which rail item you
  came in through, which is the one thing repeated patterns must not do.
*/

/** The least an order has to say to be a pin. Every orders list can say it. */
export interface MapOrder {
  id: string;
  /** Shown as the row's heading. */
  orderNo: string;
  /** Must match a `SHIP_TO_SITES` name, or the order is counted as unmapped. */
  site: string;
  /** The quieter second line — whose order this is. */
  subtitle: string;
  status: string;
  tone: StatusTone;
  /* A STAGE COLOUR THE USER CHOSE (Pavan, 2026-10-09) — Sales only. */
  color?: PillColor | null;
  /** Its own coordinates, for a site that is not one of `SHIP_TO_SITES`
      (the Customer Portal's ship-tos, 2026-10-13). */
  coords?: { lat: number; lng: number };
}

/*
  A TRUCK ON THE ROAD (Customer Portal, 2026-10-13 — live tracking). Drawn on
  the line from where it left to where it is going, `progress` of the way
  along; the caller moves it by handing a new progress.
*/
export interface MapTruck {
  id: string;
  /** The order it is carrying — pressing the truck opens it. */
  orderId: string;
  label: string;
  from: { lat: number; lng: number };
  to: { lat: number; lng: number };
  /** 0 at `from`, 1 at `to`. */
  progress: number;
  /** Where it left from — named beside a small mark there. */
  fromLabel?: string;
}

/** A site's own coordinates, parsed from the `lat, lng` its record carries. */
function siteCoords(shipTo: string) {
  const site = SHIP_TO_SITES.find((s) => s.name === shipTo);
  if (!site) return null;
  const [lat, lng] = site.latLng.split(",").map((n) => Number(n.trim()));
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng, city: site.city, state: site.state };
}

/** Percent from the left / top of the plot. Latitude runs the other way. */
function project(
  lat: number,
  lng: number,
  b: { minLat: number; maxLat: number; minLng: number; maxLng: number }
) {
  return {
    left: ((lng - b.minLng) / (b.maxLng - b.minLng)) * 100,
    top: ((b.maxLat - lat) / (b.maxLat - b.minLat)) * 100,
  };
}

const PIN_FILL: Record<string, string> = {
  success: "bg-status-success",
  processing: "bg-fp-banner-accent-caution",
  failed: "bg-status-failed",
  /* INFO IS BLUE, LIKE ITS CHIP (Pavan, 2026-10-07). It had no entry, so
     Scheduled and Dispatched fell through to neutral grey. */
  info: "bg-fp-banner-accent-info",
  neutral: "bg-muted-foreground",
};

export function OrderMapView({
  orders,
  onOpenOrder,
  hoverCard,
  trucks = [],
  minPad = 1.2,
}: {
  orders: MapOrder[];
  onOpenOrder: (id: string) => void;
  /** The pin's hover card — the orders at that site, primary details only.
      Left out, a pin has no hover card (every module before 2026-10-13). */
  hoverCard?: (rows: MapOrder[]) => React.ReactNode;
  trucks?: MapTruck[];
  /** The least margin round the pins, in degrees. 1.2 frames a region of a
      country; a customer's sites in one city want a few hundredths. */
  minPad?: number;
}) {
  const [hovered, setHovered] = React.useState<string | null>(null);

  /* Several orders share a ship-to, so pins are grouped by site — one dot per
     site with six orders under it is a map that hides what it was opened to
     show. */
  const groups = React.useMemo(() => {
    const by = new Map<
      string,
      { lat: number; lng: number; site: string; city: string; rows: MapOrder[] }
    >();
    orders.forEach((o) => {
      const p = o.coords ? { ...o.coords, city: "" } : siteCoords(o.site);
      if (!p) return;
      const g =
        by.get(o.site) ??
        { lat: p.lat, lng: p.lng, site: o.site, city: p.city, rows: [] };
      g.rows.push(o);
      by.set(o.site, g);
    });
    return [...by.values()];
  }, [orders]);

  /* The frame is the ORDERS' OWN SPREAD, not a fixed continent: a day whose
     work is all in one valley should not be three pins in the corner of a map
     of the country. */
  const bounds = React.useMemo(() => {
    if (groups.length === 0) {
      return { minLat: 24, maxLat: 49, minLng: -125, maxLng: -67 };
    }
    /* A truck's start counts too, so its road is on the map. */
    const lats = [...groups.map((g) => g.lat), ...trucks.map((t) => t.from.lat)];
    const lngs = [...groups.map((g) => g.lng), ...trucks.map((t) => t.from.lng)];
    const padLat = Math.max(minPad, (Math.max(...lats) - Math.min(...lats)) * 0.15);
    const padLng = Math.max(minPad, (Math.max(...lngs) - Math.min(...lngs)) * 0.15);
    return {
      minLat: Math.min(...lats) - padLat,
      maxLat: Math.max(...lats) + padLat,
      minLng: Math.min(...lngs) - padLng,
      maxLng: Math.max(...lngs) + padLng,
    };
  }, [groups, trucks, minPad]);

  const plotted = groups.reduce((n, g) => n + g.rows.length, 0);
  const missing = orders.length - plotted;

  return (
    <div className="flex h-full min-h-0 gap-4">
      {/* ── the list ── */}
      <div className="flex min-h-0 w-[340px] shrink-0 flex-col overflow-auto rounded-md border border-border">
        {orders.map((o) => {
          const on = hovered === o.site;
          return (
            <button
              key={o.id}
              type="button"
              onClick={() => onOpenOrder(o.id)}
              onMouseEnter={() => setHovered(o.site)}
              onMouseLeave={() => setHovered(null)}
              className={cn(
                "flex flex-col gap-1 border-b border-border px-3 py-2.5 text-left outline-none transition-colors last:border-b-0",
                "focus-visible:ring-2 focus-visible:ring-ring/50",
                on ? "bg-selected" : "hover:bg-accent"
              )}
            >
              <span className="flex items-center justify-between gap-2">
                <span
                  className={cn(
                    "font-mono text-sm font-semibold",
                    on ? "text-selected-foreground" : "text-foreground"
                  )}
                >
                  {o.orderNo}
                </span>
                <StatusChip tone={o.tone} color={o.color} variant="soft">
                  {o.status}
                </StatusChip>
              </span>
              <span className="truncate text-xs text-muted-foreground">
                {o.subtitle}
              </span>
              <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
                <MapPin className="size-3 shrink-0" />
                <span className="truncate">{o.site}</span>
              </span>
            </button>
          );
        })}
      </div>

      {/* ── the plot ── */}
      <div className="relative min-h-0 flex-1 overflow-hidden rounded-md border border-border bg-fp-surface-1a">
        {/* THE ROADS — a dashed line from where each truck left to where it
            is going, the part already driven solid. */}
        {trucks.length > 0 && (
          <svg aria-hidden className="pointer-events-none absolute inset-0 size-full" viewBox="0 0 100 100" preserveAspectRatio="none">
            {trucks.map((t) => {
              const a = project(t.from.lat, t.from.lng, bounds);
              const b = project(t.to.lat, t.to.lng, bounds);
              const mx = a.left + (b.left - a.left) * t.progress;
              const my = a.top + (b.top - a.top) * t.progress;
              return (
                <g key={t.id} vectorEffect="non-scaling-stroke">
                  <line x1={a.left} y1={a.top} x2={b.left} y2={b.top} className="stroke-muted-foreground/50" strokeWidth={1.5} strokeDasharray="4 4" vectorEffect="non-scaling-stroke" />
                  <line x1={a.left} y1={a.top} x2={mx} y2={my} className="stroke-fp-banner-accent-caution" strokeWidth={2.5} vectorEffect="non-scaling-stroke" />
                </g>
              );
            })}
          </svg>
        )}
        {groups.map((g) => {
          const pos = project(g.lat, g.lng, bounds);
          const on = hovered === g.site;
          const tone = g.rows[0].tone;
          const pin = (
            <button
              type="button"
              onClick={() => onOpenOrder(g.rows[0].id)}
              onMouseEnter={() => setHovered(g.site)}
              onMouseLeave={() => setHovered(null)}
              aria-label={`${g.site}, ${g.rows.length} ${g.rows.length === 1 ? "order" : "orders"}`}
              style={{ left: `${pos.left}%`, top: `${pos.top}%` }}
              className="absolute -translate-x-1/2 -translate-y-1/2 outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
            >
              <span className="flex flex-col items-center gap-1">
                <span
                  className={cn(
                    "flex items-center justify-center rounded-full text-[10px] font-semibold text-white ring-2 ring-fp-surface-1a transition-all",
                    PIN_FILL[tone] ?? PIN_FILL.neutral,
                    on ? "size-7 scale-110" : "size-5"
                  )}
                >
                  {g.rows.length}
                </span>
                <span
                  className={cn(
                    "rounded-sm px-1 text-[10px] whitespace-nowrap transition-opacity",
                    on
                      ? "bg-selected text-selected-foreground opacity-100"
                      : "text-muted-foreground opacity-0"
                  )}
                >
                  {g.site}
                </span>
              </span>
            </button>
          );
          return hoverCard ? (
            <HoverCard key={g.site} openDelay={80} closeDelay={120}>
              <HoverCardTrigger asChild>{pin}</HoverCardTrigger>
              <HoverCardContent side="top" className="w-80 p-0">
                {hoverCard(g.rows)}
              </HoverCardContent>
            </HoverCard>
          ) : (
            <React.Fragment key={g.site}>{pin}</React.Fragment>
          );
        })}
        {/* WHERE THE TRUCKS LEFT FROM — one mark per place, named. */}
        {[...new Map(trucks.filter((t) => t.fromLabel).map((t) => [t.fromLabel, t])).values()].map((t) => {
          const a = project(t.from.lat, t.from.lng, bounds);
          return (
            <span
              key={`from-${t.fromLabel}`}
              style={{ left: `${a.left}%`, top: `${a.top}%` }}
              className="pointer-events-none absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center gap-1"
            >
              <span className="size-3 rounded-sm bg-foreground ring-2 ring-fp-surface-1a" />
              <span className="text-[10px] whitespace-nowrap text-muted-foreground">{t.fromLabel}</span>
            </span>
          );
        })}
        {trucks.map((t) => {
          const a = project(t.from.lat, t.from.lng, bounds);
          const b = project(t.to.lat, t.to.lng, bounds);
          return (
            <button
              key={t.id}
              type="button"
              onClick={() => onOpenOrder(t.orderId)}
              aria-label={t.label}
              title={t.label}
              style={{
                left: `${a.left + (b.left - a.left) * t.progress}%`,
                top: `${a.top + (b.top - a.top) * t.progress}%`,
              }}
              className="absolute z-10 flex size-7 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-fp-banner-accent-caution text-white shadow-md ring-2 ring-fp-surface-1a outline-none transition-[left,top] duration-1000 ease-linear focus-visible:ring-ring [&_svg]:size-3.5"
            >
              <span aria-hidden className="absolute inset-0 rounded-full bg-fp-banner-accent-caution/40 motion-safe:animate-ping" />
              <Truck className="relative" />
            </button>
          );
        })}
        {missing > 0 && (
          <span className="absolute right-3 bottom-3 text-xs text-muted-foreground">
            {missing} without a mapped site
          </span>
        )}
      </div>
    </div>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight, CircleCheck, Info } from "lucide-react";

/**
 * THE PENDING STRIP — what a sheet's next act is still waiting on.
 *
 * SHARED, BECAUSE THE SECOND SHEET TO NEED IT IS THE PROMOTION SIGNAL. It was
 * written twice — once for the 3PL order and once for the service order — and
 * two copies of something this fiddly would have drifted in whichever half
 * gets opened less.
 *
 * It goes in `RecordSheet`'s `footerBanner`: the reason a primary is dead
 * belongs beside it, and beside it there is room for a clause, not for a list.
 * Each caller supplies its own items and its own section ids.
 */

export interface PendingItem {
  key: string;
  /** The INSTRUCTION — "Choose a customer", not "Customer". */
  label: string;
  /** The `id` of the section this item is about. Omitted = not pressable. */
  target?: string;
}

/**
 * SEND THE READER TO THE SECTION, and say which one it was.
 *
 * A strip that names a missing field and cannot take you to it is a label for
 * a hunt. The press scrolls the section into view and then blinks its outline
 * — because after a scroll the eye is on the MOVEMENT, not on the thing that
 * moved, and "it is this one" is a different statement from "here is some of
 * the form".
 *
 * ONCE, AND IT LEAVES NO TRACE (Pavan, 2026-09-22 — it was twice). Two flashes
 * is a thing asking to be watched; one is a thing pointing at itself and then
 * getting out of the way, and the reader is already looking because the scroll
 * took them there. Three times reads as an error, and a ring that stays is a
 * state — nothing about the record changed, so nothing about it should still
 * look different in a second.
 */
export function attend(id: string) {
  const el = document.getElementById(id);
  if (!el) return;

  /* SCROLL THE CONTAINER, NOT THE ELEMENT. `scrollIntoView` picks its own
     ancestor and hands the animation to the browser. Finding the scrollport
     and setting its offset is deterministic. */
  let port: HTMLElement | null = el.parentElement;
  while (port && port.scrollHeight <= port.clientHeight + 4) {
    port = port.parentElement;
  }
  if (!port) return;
  /* 12px of air above the section, so it does not sit flush against the header
     and read as clipped. */
  const top =
    port.scrollTop +
    el.getBoundingClientRect().top -
    port.getBoundingClientRect().top -
    12;

  /* ANIMATED BY HAND, because `behavior: "smooth"` does not survive in here.
     MEASURED in the running sheet: an instant scroll to 400 lands at 400; the
     same call with `smooth` lands at 0 — the sheet's scroll lock cancels the
     browser's animation the frame after it starts. The rAF loop is not
     decoration: without it the section either does not move or teleports, and
     the travel is what tells the reader this is the same sheet they were
     already in rather than a new screen. */
  const from = port.scrollTop;
  const distance = top - from;
  const started = performance.now();
  const DURATION = 320;
  const scroller = port;
  const step = (now: number) => {
    const t = Math.min((now - started) / DURATION, 1);
    /* ease-out cubic — fast away, slow into place, which is what makes an
       arrival read as an arrival. */
    scroller.scrollTop = from + distance * (1 - Math.pow(1 - t, 3));
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);

  /* NO FOCUS MOVE. Focusing the section, or a control inside it, was tried and
     dropped: inside a focus-trapped sheet the trap restores the scroll position
     of whatever it considers focused, which fights the travel. The blink is
     what says "this one", and focus stays on the strip — which is where the
     reader presses next if more than one item is outstanding.
     KEYBOARD GAP, KNOWN: a reader who presses this with the keyboard is shown
     the section but still has to Tab to it. */

  /* THE BLINK WAITS FOR THE SCROLL. Flashing a section that is still
     travelling spends the whole animation off screen. */
  window.setTimeout(() => blink(id), 320);
}

/** How long `blink` takes, start to finish — for anything sequencing after it. */
export const BLINK_MS = 800;

/**
 * THE FLASH ON ITS OWN, WITHOUT THE TRAVEL.
 *
 * FOR A SECOND, NARROWER "THIS ONE". After a section has been brought into
 * view and named, the thing actually worth reading inside it can be named
 * too — the Pricing unit, then the vendor's own column. Two statements, not
 * one longer one: "here" and then "this part of here". They must not overlap,
 * or the second reads as the first still going.
 */
export function blink(id: string) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.remove("fp-attention");
  /* Re-adding in the same frame does not restart a CSS animation; the reflow
     between the two is what does. */
  void el.offsetWidth;
  el.classList.add("fp-attention");
  window.setTimeout(() => el.classList.remove("fp-attention"), BLINK_MS);
}

/**
 * THE SAME FLASH, ACROSS SOMETHING THAT IS NOT ONE BOX.
 *
 * A column of a grid is a stack of separate cells: an outline round each of
 * them is a ladder, not a column. Every cell that belongs to the thing carries
 * `data-blink="<name>"`, and they flash a FILL together — which reads as the
 * one unit it is. (Pavan, 2026-09-22 — "blink should happen through this whole
 * unit".)
 */
export function blinkGroup(name: string) {
  const els = document.querySelectorAll<HTMLElement>(`[data-blink="${name}"]`);
  els.forEach((el) => {
    el.classList.remove("fp-attention-fill");
    /* Re-adding in the same frame does not restart a CSS animation; the reflow
       between the two is what does. */
    void el.offsetWidth;
    el.classList.add("fp-attention-fill");
    window.setTimeout(() => el.classList.remove("fp-attention-fill"), BLINK_MS);
  });
}

/**
 * One outstanding item at a time, with a counter and a way to step through
 * them, so three missing fields cost one line rather than three.
 *
 * THE WORD "PENDING" DOES NOT MOVE. It is the strip's subject and it is true
 * of every item under it; stepping swaps only the item. A label that changed
 * with the content would make the reader re-read what KIND of line this is on
 * every press.
 *
 * WHEN NOTHING IS OUTSTANDING IT SAYS SO, in the success channel, rather than
 * disappearing: an empty strip and a satisfied one are different states.
 */
export function PendingStrip({
  pending,
  /** What the strip says when the list is empty. */
  clearLabel = "Everything this record needs is filled in",
  tone = "neutral",
}: {
  pending: PendingItem[];
  clearLabel?: string;
  /**
   * `caution` once the strip is raised by pressing the primary with
   * something missing (2026-10-05) — it is the answer to a press and has to
   * be noticed. `neutral` (grey) where it simply stands on the sheet.
   */
  tone?: "neutral" | "caution";
}) {
  const [at, setAt] = React.useState(0);
  /* The list shortens as items are cleared, so the cursor has to be pulled
     back with it rather than pointing past the end. */
  const i = Math.min(at, Math.max(pending.length - 1, 0));
  React.useEffect(() => {
    if (at > pending.length - 1) setAt(Math.max(pending.length - 1, 0));
  }, [at, pending.length]);

  if (pending.length === 0) {
    return (
      <div className="flex items-center gap-2 text-sm text-fp-banner-accent-success">
        <CircleCheck className="size-4 shrink-0" />
        {clearLabel}
      </div>
    );
  }

  const step = pending[i];
  const chevron =
    "rounded-sm p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-30";

  return (
    /* IN THE STEP COLUMN (a narrow `@container`) the strip is two rows
       (Pavan, 2026-10-05): "Pending" on the left with the stepper on the
       right, and the item itself underneath, wrapping rather than truncating.
       No icon there. The first span dissolves (`contents`) so its pieces can
       be laid out against the counter. In the full-width footer band nothing
       changes. GREY, not caution orange (Pavan, 2026-10-05): what is left to
       do is information, not an alarm. */
    <div className="flex items-center justify-between gap-3 @max-[20rem]:flex-wrap @max-[20rem]:gap-y-1">
      <span
        className={cn(
          "flex min-w-0 items-center gap-2 text-sm @max-[20rem]:contents",
          tone === "caution" ? "text-fp-banner-accent-caution" : "text-muted-foreground"
        )}
      >
        <Info className="size-4 shrink-0 @max-[20rem]:hidden" />
        <span className="shrink-0 font-medium @max-[20rem]:order-1">Pending</span>
        {step.target ? (
          <button
            type="button"
            onClick={() => attend(step.target!)}
            className="min-w-0 truncate rounded-sm text-left @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal underline decoration-current/40 underline-offset-4 outline-none transition-[text-decoration-color] hover:decoration-current focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            {step.label}
          </button>
        ) : (
          <span className="truncate @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal">{step.label}</span>
        )}
      </span>
      <span className="flex shrink-0 items-center gap-0.5 text-xs tabular-nums text-muted-foreground @max-[20rem]:order-2">
        <button
          type="button"
          aria-label="Previous pending item"
          disabled={i === 0}
          onClick={() => setAt(i - 1)}
          className={chevron}
        >
          <ChevronLeft className="size-3.5" />
        </button>
        {i + 1} of {pending.length}
        <button
          type="button"
          aria-label="Next pending item"
          disabled={i >= pending.length - 1}
          onClick={() => setAt(i + 1)}
          className={chevron}
        >
          <ChevronRight className="size-3.5" />
        </button>
      </span>
    </div>
  );
}

import * as React from "react";
import { Check, Loader2, X } from "lucide-react";
import { StatusChip, type StatusTone } from "@/components/ui/status-chip";
import type { PillColor } from "@/components/ui/pill";
import { cn } from "@/lib/utils";
import { QuietPattern } from "@/components/ui/quiet-pattern";
import { Button } from "@/components/ui/button";
import { Sheet, SheetClose, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { SteppedFormBody } from "@/components/side-sheet/form-steps";
import { FormStepsContext } from "@/components/side-sheet/form-steps-context";
import { PendingStrip, attend, type PendingItem } from "./PendingStrip";

/**
 * Side-sheet shell for a single record — edit or create.
 *
 * Chrome is the DS's, taken from `side-sheet/SheetNarrow.tsx` (Figma "Side
 * Sheet" 27610:58293) and matched to the Fuel Orders order sheet so all three
 * sheets are identical where they should be:
 *   • SheetContent  w-560 (DS `narrow`), gap-0 p-0
 *   • header        border-b, p-4, items-start justify-between gap-4
 *   • body          p-4, flex-col gap-10   ← 40px between groups
 *   • footer        border-t, p-4, items-center justify-end gap-3
 *
 * The 40px group rhythm is the same deliberate override the order sheet
 * documents: these sheets carry far more fields than the DS reference, and at
 * the DS's gap-7 the groups stopped reading as groups. The 1:2 ratio against
 * SheetSection's gap-5 is preserved, so only the scale moved.
 *
 * CREATE AND EDIT ARE THE SAME SHEET. `mode="create"` swaps the title for the
 * create label and the submit button with it, and the caller seeds a blank
 * draft. One layout to learn, and no separate create form to drift.
 *
 * DS FOLLOW-UP: nothing here is screen-specific. This belongs beside
 * `side-sheet/` in the DS, with the order sheet moved onto it too.
 */
/**
 * A COLUMN'S COMFORTABLE WIDTH, by what it holds (Pavan, 2026-10-15). A
 * table-led sheet adds these up to find its width; one number per kind, so
 * the same column is the same width in every sheet.
 */
export const CELL = {
  /* TIGHTENED (Pavan, 2026-10-15): asset and product names are short, a
     quantity is at most six digits — the columns, and so the sheet, are only
     as wide as that. */
  /** A row's select checkbox, an expand chevron. */
  check: 44,
  /** "Top off" and other labelled checkboxes. */
  flag: 72,
  /** Top off — its label and the select-all, just before the quantity (DS ui §10i). */
  topOff: 104,
  /** A tank's level reading — gauge and % (portal, 2026-10-17). */
  level: 150,
  /** A tank monitor's battery. */
  battery: 100,
  /** The row's own thing — an asset, a product, a partner, a document. */
  name: 200,
  /** A pick from a short list — type, unit, condition, terminal. */
  pick: 160,
  /** A quantity or an amount, with its unit — six digits. */
  number: 110,
  date: 140,
  status: 140,
  /** Free text — a fault, a note. */
  text: 240,
  /** The row bin / a row menu. */
  bin: 52,
} as const;

export interface SheetFit {
  /** Each table's columns, as `CELL` widths; the widest table decides. */
  tables: number[][];
  /** The 340px right rail (summary · activity) beside the tables. */
  rail?: boolean;
}

/*
  THE PATTERN UNDER A SHORT FORM (Pavan, 2026-10-16). When what the sheet
  holds takes HALF the visible height or less, the DS quiet pattern fills
  the rest — to the body's left, right and bottom edges. Taller than that,
  there is no pattern and no space kept for it. Measured live, so a form
  that grows as it is filled loses the pattern when it passes half.
*/
const BODY_GAP = 40;
const BODY_PAD = 16;
function SheetPattern() {
  const ref = React.useRef<HTMLDivElement>(null);
  const [shown, setShown] = React.useState(false);
  React.useLayoutEffect(() => {
    const el = ref.current;
    const body = el?.parentElement;
    if (!el || !body) return;
    const measure = () => {
      const visible = body.clientHeight;
      if (!visible) return;
      const top = el.getBoundingClientRect().top - body.getBoundingClientRect().top + body.scrollTop;
      /* Where the content ends — the pattern's own gap taken out. */
      const content = top - BODY_PAD - (el.dataset.shown === "true" ? BODY_GAP : 0);
      setShown(content <= visible / 2);
    };
    const ro = new ResizeObserver(measure);
    ro.observe(body);
    for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
    const mo = new MutationObserver(() => {
      for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
      measure();
    });
    mo.observe(body, { childList: true });
    measure();
    return () => {
      ro.disconnect();
      mo.disconnect();
    };
  }, []);
  return (
    <div
      ref={ref}
      data-shown={shown}
      aria-hidden
      /* Hidden, it takes no room: zero height, and the gap above canceled. */
      className={cn(shown ? "-mx-4 -mb-4 flex min-h-24 flex-1" : "-mt-10 h-0 overflow-hidden")}
    >
      {shown && <QuietPattern className="flex-1" />}
    </div>
  );
}

/**
 * THE SHEET UNDERNEATH, for a sheet opened over it (Pavan, 2026-10-15). Now
 * that widths follow content, two sheets can be the same width, and the top
 * one would cover the other exactly — reading as the SAME sheet having
 * changed. A level-2 sheet is therefore never wider than the one beneath it
 * less the 56px gap, so a strip of it always shows.
 */
const ParentSheetWidth = React.createContext<number | null>(null);

/** BODY PADDING (16 + 16) AND THE TABLE BOX'S BORDERS. */
const FIT_PAD = 34;
const RAIL = 340 + 24;
export const FORM_WIDTH = 600;
export const DATA_WIDTH = 1200;
/** A data-intensive sheet's field grid — three across, at 1200. */
export const DATA_FIELDS = "grid grid-cols-3 gap-4";

/**
 * The width a table-led sheet takes. THE FORM SIDE IS NEVER NARROWER THAN A
 * 600 FORM'S (Pavan, 2026-10-15): beside a rail, small tables still leave the
 * fields two across at a readable width; the rail adds its own 364.
 */
export function fitWidth(fit: SheetFit): number {
  const widest = Math.max(0, ...fit.tables.map((t) => t.reduce((n, w) => n + w, 0)));
  return Math.max(FORM_WIDTH - FIT_PAD, widest) + FIT_PAD + (fit.rail ? RAIL : 0);
}

export interface RecordSheetProps {
  /**
   * THE WIDTH FOLLOWS WHAT IS IN THE SHEET (Pavan, 2026-10-15 — replaces the
   * fixed 560 / 864 / 1120 tiers and the 756 creation floor). A sheet sized
   * for more than it holds reads as empty.
   *
   *   `form`     600 — fields and text, no table. The default.
   *   `compact`  510 — CONTROLS rather than a form (a facet list).
   *   `data`     1200 at least — a DATA-INTENSIVE record's detail: many
   *              fields and several related-records tables (a 3PL customer,
   *              vendor, product, rental asset). Fields go three across
   *              (`DATA_FIELDS`); with `fit`, the wider of the two. Pavan,
   *              2026-10-15: "cramped … should have more width so that
   *              information can be easily consumed".
   *   `full`     the viewport less the gap — no form uses it now: every
   *              order sheet fits its tables (Pavan, 2026-10-15). Kept for a
   *              sheet showing its step column.
   *
   * A sheet that carries TABLES passes `fit` instead, and is as wide as its
   * widest table's columns at a comfortable width (`CELL`), plus the body's
   * padding, plus the 340px rail and its gap when it has one — never under
   * 600. Per step: a stepped sheet passes the tables of the step on show.
   *
   * THE GAP IS 56px AND IT IS THE ONE CONSTANT. Every width is clamped to
   * `100vw - 56px`, so no sheet reaches the edge or overflows a small screen.
   * A sheet opened OVER another one takes that gap TWICE — see `level`.
   */
  size?: "compact" | "form" | "data" | "full";
  /** Width from the sheet's tables — see `size` and `fitWidth`. */
  fit?: SheetFit;
  /**
   * HOW DEEP IN THE STACK THIS SHEET IS. `2` is a sheet opened OVER another
   * one — the invitation over an order, a partner's quote over an order.
   *
   * IT TAKES A SECOND GAP (Pavan, 2026-09-22). The 56px is what tells a reader
   * a sheet is over something; a second sheet at the same inset covers the
   * first exactly and reads as the SAME sheet having changed its contents.
   * 112px leaves a 56px strip of the sheet underneath showing, which says
   * "there is one of these behind this one" in the only language the stack
   * has.
   */
  level?: 1 | 2;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "edit" | "create";
  /** Header title when editing, e.g. `Order #: 6104420`. */
  editTitle: string;
  /** Header title when creating, e.g. `Create Asset Order`. */
  createTitle: string;
  /** Submit label when editing. Defaults to the DS's `Save Changes`. */
  /**
   * THE EDIT-MODE PRIMARY. "Confirm", not "Save Changes" — autosave is the
   * default now, so by the time anybody looks at the footer the change is
   * already written and a Save would be claiming credit for work already
   * done. What is left to do is agree that the record is right.
   *
   * It is a per-sheet word: a footer that commits the record to a NEXT ACT
   * should say that act instead. Changed 2026-09-22.
   */
  editAction?: string;
  /** Submit label when creating — usually the same words as `createTitle`. */
  createAction: string;
  /** Rendered beside the title, e.g. a StatusChip. */
  headerAside?: React.ReactNode;
  /**
   * A second line under the title, inside the sticky header.
   *
   * For a fact about the record that must not scroll away — "this partner
   * holds the order" is the answer to a question the reader has while they are
   * looking at any part of the sheet, and at the bottom of a long step it was
   * only true where nobody was looking.
   */
  headerSubtitle?: React.ReactNode;
  /**
   * DRAFT AUTOSAVE, SAID OUT LOUD.
   *
   * A sheet that keeps a draft has to tell the reader it is keeping it, or
   * they behave as though it does not — they finish fields they meant to come
   * back to, and they hesitate to close. Three states and nothing else:
   * `saving` while a change settles, `saved` once it has, and `idle` before
   * anything has been typed, which shows nothing at all because there is
   * nothing to reassure anybody about yet.
   *
   * It sits by the TITLE, not the footer: it is a statement about the record,
   * not a control, and beside Save it would read as a second button. The
   * caller passes it through `DraftStatusChip`, which on a Draft swaps the
