        aria-expanded={moreOpen}
        onClick={() => setMoreOpen((o) => !o)}
        className="flex w-fit items-center gap-2 rounded-sm text-left outline-none focus-visible:ring-2 focus-visible:ring-ring/50"
      >
        <ChevronDown
          className={cn(
            "size-4 shrink-0 text-muted-foreground transition-transform",
            !moreOpen && "-rotate-90"
          )}
        />
        <span className="text-base font-medium text-muted-foreground">
          Additional Details
        </span>
      </button>
      {moreOpen && (
      <div className="flex flex-col gap-10">
      {/* SUPPORTING IMAGES — what was attached, as tiles. Adding happens from
          the footer's "Attach supporting images" (2026-10-05). */}
      <SheetSection title="Supporting images">
        {draft.images.length === 0 ? (
          <p className="text-sm text-muted-foreground">No images attached yet.</p>
        ) : (
          <ul className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {draft.images.map((img) => (
              <li
                key={img.id}
                className="flex min-w-0 flex-col overflow-hidden rounded-lg border border-border"
              >
                <span className="flex aspect-[4/3] items-center justify-center bg-fp-surface-1a text-muted-foreground">
                  <ImageIcon className="size-6" aria-hidden />
                </span>
                <span className="flex min-w-0 flex-col px-3 py-2">
                  <span className="truncate text-sm text-foreground">{img.name}</span>
                  <span className="truncate text-xs text-muted-foreground">
                    {img.addedOn} · {img.addedBy}
                  </span>
                </span>
              </li>
            ))}
          </ul>
        )}
      </SheetSection>

      {/* ══ DOCUMENTS ════════════════════════════════════════════════════
          (Pavan, 2026-09-22.) The papers an order accrues — the BOL it moved
          on, the driver's ticket, the invoice that follows. Separate from the
          supporting image above it because the image is evidence somebody
          took and these are documents of record: accounting, the customer or
          a dispute asks for them BY KIND, and a single pile means the one you
          need is found by scrolling.

          A TABLE, AND THE KIND IS ITS FIRST COLUMN, for the same reason. */}
      <SheetSection
        title="Documents"
        flush
      >
        {/* ALWAYS A TABLE, never an empty-state panel standing in for one —
            the same rule the Delivery Order table above follows. An empty
            table with its columns showing says what a document on an order is
            made of; a paragraph in a padded card says only that there are
            none, and it makes the section change shape the moment one
            arrives. */}
        <DocumentsTable
          rows={draft.documents.map((d) => ({ id: d.id, kind: d.kind, name: d.name, added: d.addedOn, by: d.addedBy }))}
          emptyText="Nothing yet. A BOL arrives when the order is assigned; the ticket and the invoice follow the delivery."
        />
      </SheetSection>

      </div>
      )}
      </div>
      </FormStep>
      )}

      {/* NOTES WHILE CREATING — there is no rail yet, so they stay in the form
          as its last step; once the order exists they are a rail card. */}
      {inCreation && (
        <SheetSection title="Notes">
          <div className="flex flex-col gap-4">
                <SheetField label="Delivery Instructions">
                  <Textarea
                    value={draft.instructions}
                    placeholder="Enter any delivery instructions here"
                    onChange={(e) => set("instructions", e.target.value)}
                    className="min-h-24"
                  />
                </SheetField>
                <SheetField label="Internal Note">
                  <Textarea
                    value={draft.internalNote}
                    placeholder="Add an internal note"
                    onChange={(e) => set("internalNote", e.target.value)}
                    className="min-h-24"
                  />
                </SheetField>
              </div>
        </SheetSection>
      )}

      {/* ONE PARTNER'S QUOTE, OVER THE ORDER. A second sheet rather than a
          section in this one: it belongs to a partner, not to the order, and
          there are as many of them as there are rows in the table.

          MOUNTED ONLY WHILE OPEN, so it re-reads the quote each time — the
          broker can draft, close, and reopen the same row. */}
      {/* THE INVITATION, AS THE PARTNER WILL READ IT. Mounted only while open
          so it seeds its own wording each time. */}
      {attaching && (
        <AttachSheet
          what={attaching}
          open
          onOpenChange={(o) => !o && setAttaching(null)}
          onAttach={(files) => {
            const on = DATE_FMT.format(new Date());
            setDraft((d) =>
              !d
                ? d
                : attaching === "images"
                  ? {
                      ...d,
                      images: [
                        ...d.images,
                        ...files.map((f, k) => ({
                          id: `img-${Date.now()}-${k}`,
                          name: f.name,
                          size: f.size,
                          addedOn: on,
                          addedBy: "Dana Whitfield",
                        })),
                      ],
                    }
                  : {
                      ...d,
                      documents: [
                        ...d.documents,
                        ...files.map((f, k) => ({
                          id: `doc-${Date.now()}-${k}`,
                          kind: f.kind ?? "Other",
                          name: f.name,
                          addedOn: on,
                          addedBy: "Dana Whitfield",
                        })),
                      ],
                    }
            );
            /* Open the group, so what was just attached is in view. */
            setMoreOpen(true);
            toast.success(
              `${files.length} ${attaching === "images" ? (files.length === 1 ? "image" : "images") : files.length === 1 ? "document" : "documents"} attached`
            );
          }}
        />
      )}

      {inviting && (
        <InvitePartnerSheet
          open
          onOpenChange={(o) => !o && setInviting(null)}
          resend={inviting.resend}
          targets={inviting.ids.map((id) => {
            const v = vendorById(id);
            return {
              id,
              name: v?.name ?? "Partner",
              email: `dispatch@${(v?.name ?? "partner").toLowerCase().replace(/[^a-z]+/g, "")}.com`,
            };
          })}
          facts={inviteFacts}
          onSend={(ids) => {
            if (inviting.resend) {
              /* A RESEND reaches the partner again but changes no row: they
                 are already invited. Said out loud, because nothing on the
                 table moves to show it happened. */
              setDraft((d) => (d ? { ...d, quoteRequested: true } : d));
              const names = ids.map((id) => vendorById(id)?.name ?? "partner");
              toast.success(
                names.length === 1 ? `Invitation resent to ${names[0]}` : `Invitation resent to ${names.length} partners`
              );
            } else {
              inviteAndQuote(ids);
            }
            setInviting(null);
          }}
        />
      )}

      {quoteSheet && (
        <VendorQuoteSheet
          open
          onOpenChange={(o) => !o && setQuoteSheet(null)}
          vendorName={vendorById(quoteSheet.vendorId)?.name ?? "Partner"}
          mode={quoteSheet.mode}
          lines={draft.lines.filter((l) => l.asset)}
          quote={
            draft.quotes.find((q) => q.vendorId === quoteSheet.vendorId) ?? null
          }
          onQuoteChange={putQuote}
          chargesBase={chargesBase}
          notes={
            draft.quotes.find((q) => q.vendorId === quoteSheet.vendorId)?.note
          }
          onNotesChange={(v) => {
            const q = draft.quotes.find(
              (x) => x.vendorId === quoteSheet.vendorId
            );
            if (q) putQuote({ ...q, note: v });
          }}
          attachments={(
            draft.quotes.find((q) => q.vendorId === quoteSheet.vendorId)
              ?.attachments ?? []
          ).map((name) => ({ name }))}
          onAccept={() => acceptFromQuoteSheet(quoteSheet.vendorId)}
          onReject={() => rejectQuote(quoteSheet.vendorId)}
        />
      )}

      {/* FINALISING IS THE ONE PRESS THAT PICKS WHO GETS PAID, so it is
          confirmed against the figures rather than on trust. (Pavan,
          2026-09-22.) The broker has been comparing three prices; the dialog
          restates the one they landed on, in full, so the confirmation is a
          reading rather than a nod. */}
      <AlertDialog
        open={finalizing !== null}
        onOpenChange={(o) => !o && setFinalizing(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              Finalize {vendorById(finalizing ?? "")?.name ?? "this partner"} as the vendor?
            </AlertDialogTitle>
            <AlertDialogDescription>
              They will hold the order. You can finalize somebody else until it
              moves to Assigned.
            </AlertDialogDescription>
          </AlertDialogHeader>

          {finalizing &&
            (() => {
              const q = quotes.find((x) => x.vendorId === finalizing);
              if (!q) return null;
              const total = quoteTotal(q, draft.lines, chargesBase);
              const rows: { label: string; value: number }[] = [
                { label: "Product", value: quoteProductTotal(q, draft.lines) },
                {
                  label: "Margin",
                  value: quoteChargeTotal(q, draft.lines, "Margin"),
                },
                {
                  label: "Fees",
                  value: quoteChargeTotal(q, draft.lines, "Fee"),
                },
                {
                  label: "Taxes",
                  value: quoteChargeTotal(q, draft.lines, "Tax"),
                },
                { label: "Freight", value: q.freight },
              ];
              return (
                /* T2 — ITS OWN BOX, ruled correct 2026-09-22: a dialog body is
                   not a card, and nothing else here draws an edge. */
                <div
                  data-table-variant="T2"
                  className="overflow-hidden rounded-md border border-fp-outline-1"
                >
                  <table className="w-full text-sm">
                    <tbody>
                      {rows.map((r) => (
                        <tr
                          key={r.label}
                          className="border-b border-fp-outline-1"
                        >
                          <td className="px-3 py-2 text-muted-foreground">
                            {r.label}
                          </td>
                          <td className="px-3 py-2 tabular-nums text-foreground">
                            {money(r.value)}
                          </td>
                        </tr>
                      ))}
                      <tr className="bg-fp-table-header">
                        <td className="px-3 py-2.5 font-medium text-foreground">
                          Vendor cost
                        </td>
                        <td className="px-3 py-2.5 text-base font-semibold tabular-nums text-foreground">
                          {money(total)}
                        </td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              );
            })()}

          <AlertDialogFooter>
            <AlertDialogCancel>Keep comparing</AlertDialogCancel>
            <AlertDialogAction
              className="bg-status-success text-status-success-foreground hover:bg-status-success/90"
              onClick={() => {
                if (finalizing) awardFor(finalizing);
                setFinalizing(null);
              }}
            >
              Finalize vendor
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={confirmChangeVendor} onOpenChange={setConfirmChangeVendor}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Change vendor on {order?.orderNo}?</AlertDialogTitle>
            <AlertDialogDescription>
              {vendorById(holdingVendorId ?? "")?.name ?? "The vendor"} no longer holds the order. It moves back to
              Quoting with every quote kept.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep vendor</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                const was = vendorById(holdingVendorId ?? "")?.name ?? "Vendor";
                /* The holder leaves acceptedVendorIds too — otherwise it would
                   still read as the one holding the order. Its quote stays. */
                setDraft((d) =>
                  d
                    ? { ...d, vendorId: null, status: "Quoting", acceptedVendorIds: d.acceptedVendorIds.filter((id) => id !== holdingVendorId) }
                    : d
                );
                toast.success(`${was} released`, { description: "Back in Quoting." });
              }}
            >
              Change vendor
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={confirmCancel} onOpenChange={setConfirmCancel}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel {order?.orderNo}?</AlertDialogTitle>
            <AlertDialogDescription>
              It leaves the working lanes and moves to Canceled, keeping its
              history. Any vendor already invited is told it has gone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction variant="destructive" onClick={cancelOrder}>
              Cancel order
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* DELETING IS NOT CANCELLING, and the copy has to say which. Cancel
          leaves the order in the Canceled lane with its history; delete takes
          it away, and there is nothing to look at afterwards. */}
      <AlertDialog open={confirmDiscard} onOpenChange={setConfirmDiscard}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Discard this order?</AlertDialogTitle>
            <AlertDialogDescription>
              All the details you've added will be discarded.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep editing</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={() => onOpenChange(false)}
            >
              Discard
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={confirmDelete} onOpenChange={setConfirmDelete}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete {order?.orderNo}?</AlertDialogTitle>
            <AlertDialogDescription>
              The order and its history are removed for good. If you only want it
              out of the working lanes, cancel it instead — a canceled order keeps
              its trail and can still be read.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep it</AlertDialogCancel>
            <AlertDialogAction
              variant="destructive"
              onClick={() => {
                toast.success("Order deleted");
                onOpenChange(false);
              }}
            >
              Delete order
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {fieldsDrawer}

      {/* ── linked-record editing ─────────────────────────────────────────
          Both drawers stack a layer above the order sheet, so the draft behind
          them is never unmounted — the whole point is that noticing a wrong
          number should not cost somebody the order they were raising. */}
      <EditDrawer
        open={editingPoc !== null}
        onOpenChange={(o) => !o && setEditingPoc(null)}
        title="Edit contact details"
        subtitle={editingPocName}
        canSave={pocEdit.phone.trim() !== "" && pocEdit.email.includes("@")}
        onSave={() => {
          /* Written to the directory, because these belong to the PERSON: the
             next order that names them should show the corrected number. */
          POC_DIRECTORY[editingPocName] = { phone: pocEdit.phone, email: pocEdit.email };
          toast.success("Contact details saved");
        }}
      >
        <SheetField label="Phone" required>
          <Input
            type="tel"
            value={pocEdit.phone}
            onChange={(e) => setPocEdit((p) => ({ ...p, phone: e.target.value }))}
          />
        </SheetField>
        <SheetField
          label="Email"
          required
        >
          <Input
            type="email"
            value={pocEdit.email}
            onChange={(e) => setPocEdit((p) => ({ ...p, email: e.target.value }))}
          />
        </SheetField>
        <p className="text-xs text-muted-foreground">
          This is {editingPocName}&apos;s own record. Changing it here changes it on
          every order that names them.
        </p>
      </EditDrawer>

      <EditDrawer
        open={editingSales}
        onOpenChange={setEditingSales}
        title="Edit contact details"
        subtitle={draft.salesperson}
        canSave={salesEdit.trim() !== ""}
        onSave={() => {
          SALES_CONTACTS[draft.salesperson] = salesEdit;
          toast.success("Contact details saved");
        }}
      >
        <SheetField label="Phone" required>
          <Input
            type="tel"
            value={salesEdit}
            onChange={(e) => setSalesEdit(e.target.value)}
          />
        </SheetField>
        <p className="text-xs text-muted-foreground">
          This is {draft.salesperson}&apos;s own record. Changing it here changes it
          on every order they own.
        </p>
      </EditDrawer>

      <EditDrawer
        open={editing !== null}
        onOpenChange={(o) => !o && setEditing(null)}
        title={editing?.kind === "shipTo" ? "Edit ship-to details" : "Edit customer details"}
        subtitle={editing?.name}
        onSave={() => {
          if (!editing) return;
          if (editing.kind === "customer") {
            const c = BROKER_CUSTOMERS.find((x) => x.name === editing.name);
            if (c) {
              c.phone = recordEdit.a || null;
              c.email = recordEdit.b || null;
              c.billingEmail = recordEdit.c || null;
              c.customerInstruction = recordEdit.d || null;
            }
          } else {
            const st = SHIP_TO_SITES.find((x) => x.name === editing.name);
            if (st) {
              st.street = recordEdit.a;
              st.city = recordEdit.b;
              st.state = recordEdit.c;
              st.zip = recordEdit.d;
            }
          }
          toast.success(
            editing.kind === "shipTo" ? "Ship-to saved" : "Customer saved"
          );
        }}
      >
        {editing?.kind === "customer" ? (
          <>
            <SheetField label="Phone">
              <Input
                type="tel"
                value={recordEdit.a}
                onChange={(e) => setRecordEdit((r) => ({ ...r, a: e.target.value }))}
              />
            </SheetField>
            <SheetField label="Email">
              <Input
                type="email"
                value={recordEdit.b}
                onChange={(e) => setRecordEdit((r) => ({ ...r, b: e.target.value }))}
              />
            </SheetField>
            <SheetField label="Billing email">
              <Input
                type="email"
                value={recordEdit.c}
                onChange={(e) => setRecordEdit((r) => ({ ...r, c: e.target.value }))}
              />
            </SheetField>
            <SheetField
              label="Customer instruction"
            >
              <Textarea
                value={recordEdit.d}
                onChange={(e) => setRecordEdit((r) => ({ ...r, d: e.target.value }))}
              />
            </SheetField>
          </>
        ) : (
          <>
            <SheetField label="Street">
              <Input
                value={recordEdit.a}
                onChange={(e) => setRecordEdit((r) => ({ ...r, a: e.target.value }))}
              />
            </SheetField>
            <div className="grid grid-cols-3 gap-3">
              <SheetField label="City">
                <Input
                  value={recordEdit.b}
                  onChange={(e) => setRecordEdit((r) => ({ ...r, b: e.target.value }))}
                />
              </SheetField>
              <SheetField label="State">
                <Input
                  value={recordEdit.c}
                  onChange={(e) => setRecordEdit((r) => ({ ...r, c: e.target.value }))}
                />
              </SheetField>
              <SheetField label="Zip">
                <Input
                  value={recordEdit.d}
                  onChange={(e) => setRecordEdit((r) => ({ ...r, d: e.target.value }))}
                />
              </SheetField>
            </div>
            <p className="text-xs text-muted-foreground">
              This site belongs to the customer record. Changing it here changes it
              on every order that delivers to it.
            </p>
          </>
        )}
      </EditDrawer>
        {/* OPTION 2 — THE SUMMARY AS A PINNED BANNER (Pavan, 2026-10-06). The
          rail card's wash, laid out as one row across the centre column.
          ONE BAR, TWO SHAPES: once Pricing is on screen it MORPHS into
          Pricing's totals bar — the vendor band folds away, the title and
          the product facts close up, the wash fades to the bar's surface and
          the three money figures spread across — rather than leaving and
          letting a second bar arrive. Pricing's own bar stands down in this
          mode; this is it. */}
      {summaryMode === "banner" && shownQuote && !inCreation && (() => {
        const m = pricingInView;
        const ease = "duration-300 ease-out";
        const fold = (open: boolean) =>
          cn("grid transition-[grid-template-rows,opacity]", ease, open ? "grid-rows-[1fr] opacity-100" : "grid-rows-[0fr] opacity-0");
        const squeeze = (open: boolean) =>
          cn("overflow-hidden transition-[max-width,opacity,margin]", ease, open ? "max-w-60 opacity-100" : "max-w-0 opacity-0");
        return (
        /* THE LAST THING IN THE FORM, so it pins for the whole scroll. Beside
           the rail it is the centre column's width; merged with Pricing —
           which runs the full sheet — it widens to match (Pavan,
           2026-10-06). */
        <div
          className={cn(
            "sticky -bottom-4 z-30 -mx-4 -mb-4 transition-[margin]",
            ease,
            m ? "lg:-mr-4" : "lg:mr-87"
          )}
        >
          {/* THE VENDORS ON A BAND OF THEIR OWN, above the coloured card. */}
          {choosing && quotedIds.length > 1 && (
            <div className={fold(!m)}>
              <div className="overflow-hidden">
                <div className="border-t border-border bg-fp-surface-1b px-4 pt-1.5">
                  <Tabs
                    value={shownQuotedAt >= 0 ? (shownVendorId ?? quotedIds[0]) : quotedIds[0]}
                    onValueChange={(v) => setShownQuote(v)}
                  >
                    <TabsList variant="line" className="h-8 justify-start">
                      {quotedIds.map((id) => (
                        <TabsTrigger
                          key={id}
                          value={id}
                          className="flex-none px-2 text-xs data-[state=active]:text-foreground after:bg-foreground dark:data-[state=active]:text-foreground"
                        >
                          {vendorById(id)?.name ?? id}
                        </TabsTrigger>
                      ))}
                    </TabsList>
                  </Tabs>
                </div>
              </div>
            </div>
          )}
          <section className="relative overflow-hidden border-t border-border bg-popover">
            {/* THE WASH, as its own layer so it can fade into the bar. */}
            <div
              aria-hidden
              className={cn("absolute inset-0 transition-opacity", ease, m ? "opacity-0" : "opacity-100", "bg-[linear-gradient(170deg,color-mix(in_oklab,var(--pastel-violet)_55%,var(--fp-surface-1a))_0%,color-mix(in_oklab,var(--pastel-rose)_30%,var(--fp-surface-1a))_28%,var(--fp-surface-1a)_60%)] dark:bg-[linear-gradient(170deg,color-mix(in_oklab,var(--pastel-violet-foreground)_70%,var(--fp-surface-1a))_0%,color-mix(in_oklab,var(--pastel-rose-foreground)_35%,var(--fp-surface-1a))_30%,var(--fp-surface-1a)_65%)]")}
            />
            <div className="relative flex items-center px-4 py-3">
              <div className={cn("flex shrink-0 flex-col", squeeze(!m), m ? "mr-0" : "mr-8")}>
                <span className="whitespace-nowrap text-sm font-semibold text-foreground">Quotation summary</span>
                {!(choosing && quotedIds.length > 1) && (
                  <span className="truncate text-xs text-muted-foreground">
                    {vendorById(shownVendorId ?? "")?.name ?? ""}
                  </span>
                )}
              </div>
              <dl className="flex min-w-0 flex-1 items-end justify-between gap-x-6">
                {[
                  {
                    key: "products",
                    label: "Products",
                    value:
                      productNames.length === 0
                        ? "—"
                        : `${productNames.length} ${productNames.length === 1 ? "product" : "products"}`,
                    keep: false,
                  },
                  {
                    key: "gallons",
                    label: "Total gallons",
                    value: isAllTopOff(draft.lines)
                      ? "Top-off"
                      : gal > 0
                        ? `${gal.toLocaleString()} gal`
                        : "—",
                    keep: false,
                  },
                  /* THE BAR'S WORDS once merged — the same figures. */
                  { key: "vendor", label: m ? "Vendor pricing" : "Vendor quote", value: money(carrierTotal), keep: true },
                  { key: "customer", label: "Customer pricing", value: money(billed), keep: true },
                ].map((f) => (
                  <div key={f.key} className={cn("flex flex-col", !f.keep && squeeze(!m))}>
                    <dt className="whitespace-nowrap text-xs text-muted-foreground">{f.label}</dt>
                    <dd className="whitespace-nowrap text-sm tabular-nums text-foreground">{f.value}</dd>
                  </div>
                ))}
                <div className="flex flex-col items-end">
                  <dt className="whitespace-nowrap text-xs text-muted-foreground">
                    {m ? "Expected profit" : "Margin"}
                  </dt>
                  <dd
                    className={cn(
                      "font-semibold tabular-nums transition-[font-size]",
                      ease,
                      m ? "text-sm" : "text-base",
                      margin < 0 ? "text-destructive" : margin > 0 ? "text-status-success" : "text-foreground"
                    )}
                  >
                    {money(margin)}
                  </dd>
                </div>
              </dl>
            </div>
          </section>
        </div>
        );
      })()}
    </RecordSheet>
  );
}

import * as React from "react";
import { dateWindowOf } from "@/components/ui/date-picker";
import { CalendarOff, SearchX } from "lucide-react";
import {
  Dialog,
  DialogContent,
