/** Company-name parts, by the industries a fuel brokerage actually serves. */
const COMPANY_HEADS = [
  "Ironline", "Westbrook", "Cardinal", "Halvorsen", "Redwood", "Sierra",
  "Granite", "Coastal", "Meridian", "Harbor", "Summit", "Pioneer", "Cascade",
