export const lineOfProduct = (product: string): ServiceLine =>
  LINE_OF[product] ?? "Fuel";

/** Everything a line can carry, for a movement order that names no site asset. */
const LINE_PRODUCTS: Record<ServiceLine, string[]> = {
  Fuel: PRODUCTS.filter((p) => LINE_OF[p] === "Fuel"),
  Lubricants: PRODUCTS.filter((p) => LINE_OF[p] === "Lubricants"),
  Propane: PRODUCTS.filter((p) => LINE_OF[p] === "Propane"),
};

/** Weighted the way the business is: fuel is most of it. See the seed. */
const LINE_CYCLE: ServiceLine[] = [
  "Fuel",
  "Fuel",
  "Lubricants",
  "Fuel",
  "Propane",
  "Fuel",
  "Lubricants",
];

export const WINDOWS: { start: string; end: string }[] = [
  { start: "6:00 AM", end: "10:00 AM" },
  { start: "8:00 AM", end: "12:00 PM" },
  { start: "10:00 AM", end: "2:00 PM" },
  { start: "12:00 PM", end: "4:00 PM" },
  { start: "2:00 PM", end: "6:00 PM" },
  { start: "6:00 PM", end: "10:00 PM" },
];

const CREDIT_REASONS = [
  "Over credit limit",
  "Credit status unapproved",
  "42 days overdue",
];

const INSTRUCTIONS = [
  "Gate code 4417. Tanks are behind the shop, back in from the north side.",
  "Call the POC 30 minutes out. No entry before 7am.",
  "Fill both saddle tanks. Do not top the day tank.",
  "",
];

/* NEVER LEAVES THE BUILDING. Mostly empty, because most orders have nothing
   anyone needed to say twice. */
const INTERNAL_NOTES = [
  "Customer disputed the last delivery fee. Confirm the rate before invoicing.",
  "Site contact changes at the end of the month — check before the next run.",
  "",
  "",
  "",
  "",
];

/*
  Seed expansion.

  The board has SEVEN lanes, and a lane with one card in it teaches nothing about
  how the board behaves — so the generator distributes across all seven and puts
  a deliberate majority on TODAY, which is where the date stepper opens. Dates
  are offsets from today, computed at module load, so the relative labels
  (Today / Tomorrow / Yesterday) stay correct on whatever day this is opened.
*/

/** Deterministic pseudo-random, so the dataset is identical on every reload. */
function rng(seed: number) {
  let s = seed;
  return () => {
    s = (s * 1103515245 + 12345) & 0x7fffffff;
    return s / 0x7fffffff;
  };
}

/**
 * Which vendor fields a status implies. Encoded once so a seed cannot produce an
 * order that is `Assigned` with nobody holding it, or `Draft` with three invites
 * out — the exact class of contradiction `HANDOFF.md` open question 1 is about.
 */
function vendorStateFor(
  i: number,
  status: BrokerStatus,
  kind: OrderKind,
  pick: () => number
): {
  vendorId: string | null;
  invitedVendorIds: string[];
  acceptedVendorIds: string[];
} {
  if (status === "Draft" || status === "Blocked") {
    /* A DRAFT MAY ALREADY HAVE ITS PARTNERS PICKED. Sending is an explicit act,
       so "chosen but not sent" is a real state — and once the shortlist has
       gone out the card stops saying Draft and says Awaiting Quotation. A
       fixture that never produced a shortlist would leave half of that badge
       unreachable; see `sentVendorIds` below for which of them were sent. */
    const ready = pick() < 0.45;
    if (!ready) return { vendorId: null, invitedVendorIds: [], acceptedVendorIds: [] };
    const needsLine = kind === "Movement" ? "Asset Movement" : "Bulk Fuel";
    const picks = VENDORS.filter((v) =>
      v.businessLines.some((b) => b === needsLine)
    ).map((v) => v.id);
    const one = picks[Math.floor(pick() * picks.length)];
    const extra = picks.filter((id) => id !== one).slice(0, pick() < 0.35 ? 1 : 0);
    return {
      vendorId: null,
      invitedVendorIds: [one, ...extra],
      acceptedVendorIds: [],
    };
  }
  // THE POOL IS FILTERED BY BUSINESS LINE. The spec makes Business Lines a
  // filter on the vendor picker (§5.5 "Table View") precisely because a carrier
  // that only moves tanks cannot haul 2,200 gallons of diesel. Drawing from the
  // whole vendor list produced exactly that: a bulk fuel order out for
  // acknowledgement to Pacific Tank Movers, whose only line is Asset Movement.
  const needs = kind === "Movement" ? "Asset Movement" : "Bulk Fuel";
  const pool = VENDORS.filter((v) =>
    v.businessLines.some((b) => b === needs)
  ).map((v) => v.id);
  const first = pool[Math.floor(pick() * pool.length)];
  if (status === "Quoting") {
    /* OUT FOR ACKNOWLEDGEMENT, and nobody has been AWARDED yet — that is what
       Quoting means. Sometimes one invite, sometimes several; both are normal,
       and the difference is what the rejection rule turns on. */
    const extra = pool.filter((id) => id !== first);
    const n = pick() < 0.45 ? 1 + Math.floor(pick() * 2) : 0;
    /* AT LEAST TWO ON EVERY OTHER ORDER. Both draws above are still taken, so
       the stream is unchanged — this only raises the floor, and it is what
       gives the pricing unit's partner picker two quotes to sit between. A
       broker comparing prices is the whole of this stage; one invitee on most
       of them made that impossible to see. */
    const invited = [first, ...extra.slice(0, Math.max(n, i % 2 === 0 ? 1 : 0))];
    /* SOME OF THEM HAVE ALREADY ANSWERED. Quoting used to seed no acceptances
       at all, and a quote can only follow one — so the stage whose entire job
       is comparing prices could never show a price. Every other order accepts
       its first invitee, which puts both halves of the stage on the board: the
       ones still waiting and the ones with a number to compare.

       BY INDEX, NOT BY `pick()`. Every draw taken from the generator shifts
       every value after it, so seeding this from the random stream would have
       reshuffled the whole fixture — different vendors, different quotes,
       different lanes. Same reason `invoiceState` cycles. */
    /* SOMETIMES TWO HAVE ANSWERED, so the pricing unit's partner picker has
       something to pick between — comparing quotes is the whole of what this
       stage is for, and with one quote everywhere the control was a select of
       one on every order. */
    const answered = i % 2 === 0 ? invited.slice(0, 2) : [];
    return {
      vendorId: null,
      invitedVendorIds: invited,
      acceptedVendorIds: answered,
    };
  }
  const alsoInvited = pool.filter((id) => id !== first).slice(0, pick() < 0.4 ? 1 : 0);
  const invited = [first, ...alsoInvited];
  if (status === "Assigned") {
    /* ACCEPTED IS THE PARTNER'S ACT, NOT THE BROKER'S. At least one partner has
       said yes; whether the broker has taken anyone's quote is the next
       question, and on roughly half of these it has not been answered yet —
       which is the state step 2 of the sheet exists for. */
    const accepted =
      invited.length > 1 && pick() < 0.4 ? invited : [first];
    /* ASSIGNED MEANS A VENDOR IS ASSIGNED (Pavan, 2026-10-06) — the order
       only gets here once one is finalized. The draw is still taken so the
       rest of the fixture is unchanged. */
    pick();
    return {
      vendorId: first,
      invitedVendorIds: invited,
      acceptedVendorIds: accepted,
    };
  }
  // Completed and everything downstream: the broker has taken a quote, and the
  // partner holding the order is one that accepted the invitation.
  return {
    vendorId: first,
    invitedVendorIds: invited,
    acceptedVendorIds: [first],
  };
}

const FIRST_ORDER_NO = 104_620;

export const BROKER_ORDERS: BrokerOrder[] = (() => {
  const pick = rng(20260901);
  const today = startOfDay(new Date());
  const rows: BrokerOrder[] = [];

  // Day offsets: today is over-weighted so the board opens full.
  const OFFSETS = [0, 0, 0, 0, 0, 0, 1, 1, -1, 2, -2, 3];

  const TOTAL = 108;
  for (let i = 0; i < TOTAL; i++) {
    const status = BROKER_STATUSES[i % BROKER_STATUSES.length];
    const kind: OrderKind =
      i % 11 === 0 ? "Movement" : i % 4 === 0 ? "Recurring" : "Regular";
    const cust = CUSTOMERS[i % CUSTOMERS.length];
    /* ONE ship-to concept. `SHIP_TO_SITES` is the list — the site carries the
       name, the street, the city/state/ZIP and the coordinates together, so a
       ship-to can never be a name in one place and an address in another. The
       customer's own `shipTos` array is not used here for that reason. */
    const site = SHIP_TO_SITES[i % SHIP_TO_SITES.length];
    const shipTo = site.name;
    const offset = OFFSETS[i % OFFSETS.length];
    const when = new Date(today);
    when.setDate(when.getDate() + offset);

    const isMovement = kind === "Movement";
    /* An order's lines are the SITE'S assets, picked from its list — never
       invented tank names. That is what the sheet does, so the seed has to do
       it too or an existing order shows rows the site does not have and the
       Rental badge never appears on one. */
    /* AN ORDER BELONGS TO ONE LINE. A propane run and a lube drop are different
       trucks with different certificates — an order that mixed them would be a
       row no dispatcher could act on. The line is chosen first and the assets
       are drawn from the ones that serve it; where the site cannot serve that
       line at all, it keeps what the site does have and the order's line is
       read back off the products it actually got.

       Chosen by INDEX on a seven-long cycle, not from the random stream: a draw
       taken here would shift every value after it and reshuffle the fixture,
       and seven shares no factor with the 24-row day so one day walks the whole
       cycle rather than landing on the same line every time. */
    const wanted = LINE_CYCLE[i % LINE_CYCLE.length];
    const inLine = site.assets.filter((a) => lineOfProduct(a.product) === wanted);
    /* The fallback narrows too. Falling back to the site's whole list let one
       order draw a lube skid and a diesel tank together — a row no dispatcher
       could act on, and the invariant this block exists to hold. */
    const fallbackLine = lineOfProduct(
      site.assets[i % site.assets.length].product
    );
    const pool =
      inLine.length > 0
        ? inLine
        : site.assets.filter((a) => lineOfProduct(a.product) === fallbackLine);
    /* UP TO SIX PRODUCTS ON EVERY FIFTH ORDER (Pavan, 2026-09-22 — "add at
       least 1-6 products as different examples"). The pricing unit is a table
       of products now, and a fixture that never ran past three could not show
       what it does at six. ONE DRAW EITHER WAY, so the random stream is not
       lengthened; only what this one is multiplied by changes. Bray North Yard
       is the only site with six assets standing on it, so that is where a
       six-line order can actually land. */
    const nLines = isMovement
      ? 1
      : Math.min(pool.length, 1 + Math.floor(pick() * (i % 5 === 0 ? 6 : 3)));
    const lines: OrderLine[] = Array.from({ length: nLines }, (_, k) => {
      // Top-off lines exist on ~1 in 6 fuel lines and never on movement orders,
      // which carry an asset rather than a requested volume.
      const topOff = !isMovement && pick() < 0.17;
      const asset = pool[(i + k) % pool.length];
      return {
        asset: isMovement
          ? MOVEMENT_ASSET_NAMES[(i + k) % MOVEMENT_ASSET_NAMES.length]
          : asset.name,
        product: isMovement
          ? LINE_PRODUCTS[wanted][(i + k) % LINE_PRODUCTS[wanted].length]
          : asset.product,
        gal: topOff ? null : 150 + Math.floor(pick() * 34) * 50,
        topOff,
        rental: isMovement ? false : asset.rental,
        /* DELIVERED IS KNOWN ONLY ONCE IT HAS BEEN. Filled in below for the
           stages downstream of the delivery; null while the order is still
           being priced, where the broker may type an expected figure. */
        deliveredGal: null,
        /* The broker's own numbers, unset until someone prices the order.
           ONE OF EACH CHARGE TO BEGIN WITH — the common case, and the reader
           adds a second margin or a county tax when the load wants one. */
        pricePerGal: undefined,
        charges: defaultLineCharges(),
      };
    });

    /* Past the delivery, the gallons are a fact and the pricing is settled —
       an order in Verified with no numbers on it could not have
       been invoiced. */
    if (status === "Completed" || status.startsWith("Accounting")) {
      for (const l of lines) {
        l.deliveredGal = l.gal == null ? 50 + Math.floor(pick() * 20) * 25 : l.gal;
        l.pricePerGal = Number((3.1 + pick() * 0.8).toFixed(3));
        const margin = Number((0.18 + pick() * 0.34).toFixed(3));
        /* DERIVED, NOT DRAWN. Every `pick()` shifts every value after it, so a
           new field seeded from the random stream would have reshuffled the
           whole fixture — different vendors, different quotes, different
           lanes. Both come off figures already settled above. */
        const rate: Record<string, number> = {
          margin,
          tax: Number((l.pricePerGal * 0.06).toFixed(3)),
          fee: Number((margin * 0.12).toFixed(3)),
        };
        l.charges = l.charges.map((c) => ({ ...c, perGal: rate[c.id] ?? 0 }));
      }
    }

    /* THE STAGES PAST COMPLETED, which the branch above stopped reaching when
       the statuses were renamed (it still asks for "Accounting…"). Verified
       and Synced orders shipped with no delivered gallons and no price — an
       invoice with nothing on it. Fixed 2026-09-23 BY INDEX, not by moving
       them into the branch above: that branch draws from `pick()`, and the
       extra draws would have reshuffled the whole fixture. */
    if (status === "Review" || status === "Verified" || status === "Partially Synced" || status === "Synced") {
      lines.forEach((l, k) => {
        l.deliveredGal = l.gal ?? 50 + ((i + k) % 20) * 25;
        l.pricePerGal = Number((3.1 + ((i + k) % 9) * 0.09).toFixed(3));
        const margin = Number((0.18 + ((i + k) % 7) * 0.05).toFixed(3));
        const rate: Record<string, number> = {
          margin,
          tax: Number((l.pricePerGal * 0.06).toFixed(3)),
          fee: Number((margin * 0.12).toFixed(3)),
        };
        l.charges = l.charges.map((c) => ({ ...c, perGal: rate[c.id] ?? 0 }));
      });
    }

    const { vendorId, invitedVendorIds, acceptedVendorIds } = vendorStateFor(
      i,
      status,
      kind,
      pick
    );
    /* Movement orders always run the quote flow (§5.20); fuel orders sometimes
       — and an order sitting in the Quoting stage always has, because that is
       what the stage is.

       THE DRAW IS TAKEN EITHER WAY. `||` short-circuits, so reading the stage
       first would have skipped the `pick()` on those orders and shifted every
       value after it. */
    const quoteDraw = pick() < 0.25;
    const quoteRequested = isMovement || status === "Quoting" || quoteDraw;
    const gal = totalGal(lines);
    /* A QUOTE FOLLOWS AN ACCEPTANCE — a partner cannot price an order it has
       not agreed to take, so only `acceptedVendorIds` can appear here. Not all
       of them have got round to it: an accepted order with no quote yet is the
       first of the two notifications, and one with a quote is the second. */
    const quotes: VendorQuote[] =
      quoteRequested && acceptedVendorIds.length > 0
        ? acceptedVendorIds
            /* THE FIRST TWO ALWAYS PRICE IT, so an order with two partners on
               it has two quotes to compare. The draw is still taken for every
               index past the first, so the random stream — and the rest of the
               fixture — is unchanged. */
            .filter((_, k) => (k === 0 ? true : pick() < 0.6 || k === 1))
            .filter(() => (status === "Assigned" ? pick() < 0.7 : true))
            .map((vid) => {
              const quoteLines = lines.map((l) => ({
                asset: l.asset,
                ratePerGal: Number((2.85 + pick() * 0.9).toFixed(3)),
                /* KEYED BY THE LINE'S OWN CHARGES, so the partner's column can
                   be laid against the broker's row for row. */
                rates: {
                  margin: Number((0.08 + pick() * 0.22).toFixed(3)),
                } as Record<string, number>,
              }));
              /* The truck coming out — charged once, so it does not scale with
                 gallons. The partner's fee and tax do, and are on the lines. */
              const freight = Math.round(180 + pick() * 320);
              /* THE TWO DRAWS THAT USED TO BE `fees` AND `taxes` ARE STILL
                 TAKEN, IN THE SAME PLACE. Those were one figure each for the
                 whole run; they are now per gallon and per product. Dropping
                 the draws would have shifted every value after them and
                 reshuffled the whole fixture — different vendors, different
                 quotes, different lanes — so they are kept and spent on the
                 rate the lines carry instead. */
              const feeRate = Number((0.012 + pick() * 0.03).toFixed(3));
              const taxRate = Number((0.02 + pick() * 0.06).toFixed(3));
              for (const ql of quoteLines) {
                ql.rates.fee = feeRate;
                ql.rates.tax = taxRate;
              }
              return {
              vendorId: vid,
              lines: quoteLines,
              freight,
              /* BY INDEX, so the two states — a quote with a covering note and
                 one without — are both on the board without taking a draw. */
              note:
                i % 3 === 0
                  ? "Rate holds for 48 hours. Two hours' wait included; anything beyond is billed at the detention rate on our rate sheet."
                  : undefined,
              attachments:
                i % 3 === 0
                  ? ["Rate sheet.pdf", "Fuel supply agreement.pdf"]
                  : undefined,
              };
            })
        : [];

    /* AN ASSIGNED ORDER WAS FINALIZED ON A QUOTE (Pavan, 2026-10-06), so the
       finalized vendor always has one. Derived, not drawn — see below. */
    if (status === "Assigned" && vendorId && !quotes.some((q) => q.vendorId === vendorId)) {
      quotes.unshift({
        vendorId,
        lines: lines.map((l, k) => ({
          asset: l.asset,
          ratePerGal: Number((2.95 + ((i + k) % 7) * 0.08).toFixed(3)),
          rates: {
            margin: Number((0.12 + ((i + k) % 5) * 0.02).toFixed(3)),
          },
        })),
        freight: 210 + (i % 9) * 25,
      });
    }

    /* A DRAFT WITH A PRICE ALREADY WRITTEN DOWN (2026-09-22). In a draft the
       broker writes a partner's quote down themselves — "Add their quotation"
       in the row's menu, for a price given on a call — and that is the state
       the Orders lane badges as *N Quotations Received*. A fixture that never
       produced one would leave that badge, and the pricing unit it unlocks,
       unreachable without typing.

       BY INDEX AND DERIVED, NOT DRAWN. No `pick()` here: a draw would shift
       every value after it and reshuffle the whole board. */
    if (status === "Draft" && invitedVendorIds.length > 0 && i % 5 === 0) {
      quotes.push({
        vendorId: invitedVendorIds[0],
        lines: lines.map((l, k) => ({
          asset: l.asset,
          ratePerGal: Number((2.9 + ((i + k) % 7) * 0.09).toFixed(3)),
          rates: {
            margin: Number((0.1 + ((i + k) % 5) * 0.02).toFixed(3)),
            tax: Number((0.03 + ((i + k) % 3) * 0.01).toFixed(3)),
            fee: Number((0.02 + ((i + k) % 4) * 0.005).toFixed(3)),
          },
        })),
        freight: 180 + (i % 9) * 30,
      });
    }

    /* A PRICED QUOTE MEANS A PRICED ORDER (Pavan, 2026-09-23). An order with a
       partner's price on it but none of the broker's showed the customer
       paying only the order fees — D-104970 read $145 against an $8,815 quote,
       a −$8,670 "expected profit" no broker would ever be looking at. Once a
       quote is in, the broker has priced their side too: the dearest quote's
       rate plus a markup, so the comparison is always against a sale.

       DERIVED, NOT DRAWN — no `pick()`, for the same reason as above. */
    if (quotes.length > 0) {
      lines.forEach((l, k) => {
        if (l.pricePerGal !== undefined) return;
        const dearest = Math.max(...quotes.map((q) => q.lines[k]?.ratePerGal ?? 0));
        l.pricePerGal = Number((dearest + 0.35 + ((i + k) % 4) * 0.05).toFixed(3));
        const margin = Number((0.22 + ((i + k) % 5) * 0.03).toFixed(3));
        const rate: Record<string, number> = {
          margin,
          tax: Number((l.pricePerGal * 0.06).toFixed(3)),
          fee: Number((margin * 0.12).toFixed(3)),
        };
        l.charges = l.charges.map((c) => ({ ...c, perGal: rate[c.id] ?? 0 }));
      });

      /* AND THE SALE COVERS THE DEAREST QUOTE, whatever stage the order is
         in. A per-gallon markup cannot promise that on its own: freight is
         charged once, so on a small load it outweighs any markup, and the
         settled prices drawn for finished orders were never compared with the
         quotes at all. Top the price up to 10% over the dearest quote, spread
         across the gallons. Derived — still no `pick()`. */
      const worst = Math.max(...quotes.map((q) => quoteTotal(q, lines)));
      const sale = lines.reduce((sum, l) => sum + customerLineTotal(l), 0);
      const gallons = lines.reduce((sum, l) => sum + billableGal(l), 0);
      if (gallons > 0 && sale < worst * 1.1) {
        const lift = (worst * 1.1 - sale) / gallons;
        for (const l of lines) {
          l.pricePerGal = Number(((l.pricePerGal ?? 0) + lift).toFixed(3));
        }
      }
    }

    /* SEEDED SO ALL THREE SHOW, and BY INDEX rather than by `pick()`. Every
       draw taken from the generator shifts every value after it, so seeding a
       new field from the random stream would have quietly reshuffled the whole
       fixture — different vendors, different quotes, different lanes. The
       cycle costs nothing and guarantees the three states are all on the
       board.

       An invoice can only be chased once a partner is on the order, so orders
       without a vendor stay at `none`: there is nobody to ask. */
    const invoiceState: InvoiceState = vendorId
      ? INVOICE_CYCLE[i % INVOICE_CYCLE.length]
      : "none";

    rows.push({
      id: `bo-${i}`,
      orderNo: `${isMovement ? "M" : "D"}-${FIRST_ORDER_NO + i * 7}`,
      kind,
      orderType: isMovement
        ? "Asset Movement"
        : pick() < 0.14
          ? "Emergency"
          : pick() < 0.3
            ? "Delivery"
            : pick() < 0.42
              ? "Extraction"
              : "Core",
      customer: { title: cust.name, description: cust.erpId },
      shipTo,
      date: { title: DATE_FMT.format(when), description: relativeLabel(offset, when) },
      dateKey: dateKeyOf(when),
      window: WINDOWS[i % WINDOWS.length],
      lines,
      status,
      vendorId,
      invitedVendorIds,
      /* A SEEDED ORDER PAST DRAFT HAS BEEN ASKED — that is what leaving Draft
         meant before the field existed.

         A SEEDED DRAFT GOES BOTH WAYS (2026-09-22), because the Orders lane
         now holds two states and the card's badge is what tells them apart:
         nothing sent is a Draft, something sent is Awaiting Quotation. Every
         other Draft with a shortlist has sent it — BY INDEX, so no draw is
         taken from the generator and the rest of the fixture is unchanged. */
      /* NOT A MULTIPLE OF FOUR. The board buckets by date off the same index,
         and every Draft landing on one day turned out to share `i % 4` — so a
         quarter-split put the whole lane on one side of it. */
      sentVendorIds:
        status === "Draft" && i % 3 === 2 ? [] : [...invitedVendorIds],
      acceptedVendorIds,
      quoteRequested,
      quotes,
      /* SEEDED BY INDEX, so all three states — no run fee, one, and two — are
         on the board without taking a draw from the generator. */
      orderFees:
        i % 3 === 0
          ? [{ type: "Fee" as const, label: "Delivery fee", amount: 125 }]
          : i % 3 === 1
            ? []
            : [
                {
                  type: "Fee" as const,
                  label: "After-hours delivery",
                  amount: 85,
                },
                { type: "Fee" as const, label: "Wait time", amount: 60 },
              ],
      invoiceState,
      serviceLine: lines.length > 0 ? lineOfProduct(lines[0].product) : wanted,
      /* BY INDEX, NOT FROM THE RANDOM STREAM — a draw here would shift every
         value after it and reshuffle the whole fixture. Two in five are
         transports, which is roughly the mix and enough of both to see each
         tab do something. */
      business: (() => {
        const options = LINE_BUSINESSES[
          lines.length > 0 ? lineOfProduct(lines[0].product) : wanted
        ];
        return options.length === 0 ? null : options[i % 5 < 2 ? 0 : 1];
      })(),
      urgent: pick() < 0.14,
      signatureOnDelivery: pick() < 0.4,
      poNumber: pick() < 0.7 ? `PO-${70_000 + i * 13}` : "",
      zip: site.zip,
      state: site.state,
      createdBy:
        kind === "Recurring"
          ? "System — Recurring"
          : CREATED_BY[i % (CREATED_BY.length - 1)],
      tags: pick() < 0.45 ? [ORDER_TAGS[i % ORDER_TAGS.length]] : [],
      /* THE TRAIL STARTS AT CREATION. An empty history on a record that
         plainly exists is a history nobody trusts afterwards. */
      audit: [
        {
          at: new Date(when.getTime() - 86_400_000).toISOString(),
          by:
            kind === "Recurring"
              ? "System — Recurring"
              : CREATED_BY[i % (CREATED_BY.length - 1)],
          changes: ["Order created"],
        },
      ],
      /*
        BOTH FLOWS ON THE BOARD. An order either has a load order — the broker
        bought the fuel, and the partner only hauls it — or it does not, and
        the partner supplies the product as well. Every seeded order was the
        second kind, so the first was unreachable without building one by hand,
        and the pricing rule that turns on it could not be seen at all.

        Every third priced order gets one, BY INDEX rather than from the random
        stream: a draw taken here would shift every value after it and reshuffle
        the whole fixture. It is only filled where one loading account covers
        every product on the order, because that is the rule the form enforces —
        seeding a combination the form would refuse is seeding a lie.
      */
      loadOrder: seedLoadOrder(i, lines),
      recurrence:
        kind === "Recurring"
          ? {
              fromDateKey: dateKeyOf(when),
              /* CYCLED ON THE RECURRING ORDINAL, NOT THE GLOBAL INDEX.
                 Recurring orders are every fourth row, so `i % 6` only ever
                 landed on three of the six frequencies — Daily, Every weekday
                 and Monthly — and the other three were unreachable in the
                 fixture. A UI that distinguishes six schedule shapes needs all
                 six to exist or half of it cannot be seen to work. */
              frequency:
                RECURRENCE_FREQUENCIES[
                  Math.floor(i / 4) % RECURRENCE_FREQUENCIES.length
                ],
            }
          : null,
      /* WHEN IT ACTUALLY RAN. Inside the delivery window it was planned for
         and a few minutes off the hour, because a finished order whose
         completion time is exactly its window's start reads as a default
         rather than as a record. Null before the delivery. */
      completedAt: isDelivered(status)
        ? (() => {
            const at = new Date(when);
            at.setHours(
              timeToMinutes(WINDOWS[i % WINDOWS.length].start) / 60 + 1,
              (i * 7) % 60,
              0,
              0
            );
            return at.toISOString();
          })()
        : null,
      hub: HUBS[i % HUBS.length],
      /*
        NEARLY EVERY SEEDED ORDER IS BROKERAGE, and the exceptions are narrow
        on purpose. The transportation path — our own fleet, no vendor table —
        is not built in the ORDER SHEET, so seeding one there would be seeding
        a screen that does not exist.

        But the recurring lists now split first-party from third-party
        operations, and a segment that is always empty teaches nothing. So a
        third of the RECURRING orders that no partner holds are ours to run:
        coherent, because an own-fleet job has no partner BECAUSE we run it,
        and confined to rows the unbuilt sheet path is not reached from.
      */
      jobType:
        kind === "Recurring" && vendorId === null && i % 3 === 0
          ? "Transportation"
          : "Brokerage",
      primaryPoc: POCS[i % POCS.length],
      /* Every fifth order names a second person, and never the same one as the
         primary — a fallback contact that is the contact is not a fallback. */
      secondaryPocs: i % 5 === 0 ? [POCS[(i + 2) % POCS.length]] : [],
      salesperson: SALESPEOPLE[i % SALESPEOPLE.length],
      instructions: INSTRUCTIONS[i % INSTRUCTIONS.length],
      internalNote: INTERNAL_NOTES[i % INTERNAL_NOTES.length],
      /* A WINTER BLEND IS A FUEL THING. Lubricants and propane have no
         additive, so flagging one would read as a spec nobody can supply. */
      winterAdditive: lineOfProduct(lines[0]?.product ?? "") === "Fuel" && i % 7 === 0,
      /* Off on every seed, as it is on every new order. */
      notifyVendor: false,
      blockedReason:
        status === "Blocked" ? CREDIT_REASONS[i % CREDIT_REASONS.length] : null,
      movement: isMovement
        ? (() => {
            /* ALL FOUR ROUTES IN THE FIXTURE. Deliveries are the common case
               and stay the common case; the other three are seeded on strides
               that do not divide each other, so every one of them lands
               somewhere in the set instead of the board only ever showing the
               route that happens to be first. */
            const direction: MovementDirection =
              i % 22 === 0
                ? "Pickup"
                : i % 17 === 0
                  ? "Transfer"
                  : i % 13 === 0
                    ? "Relocate"
                    : "Delivery";
            const route = MOVEMENT_ROUTE[direction];
            const endName = (end: MovementEnd, k: number) =>
              end === "yard"
                ? YARDS[k % YARDS.length]
                : SHIP_TO_SITES[k % SHIP_TO_SITES.length].name;
            return {
            direction,
            from: endName(route.from, i),
            /* A ROUTE CANNOT END WHERE IT STARTED, and the two same-kind
               routes are the ones where it could. */
            to: endName(route.to, route.from === route.to ? i + 1 : i),
            tankType: TANK_TYPES[i % TANK_TYPES.length],
            capacityGal: [250, 500, 1000, 2000][i % 4],
            };
          })()
        : null,
    });
    void gal;
  }

  /* EVERY STATE THE UI DISTINGUISHES MUST EXIST IN THE FIXTURE, or nobody can
     see whether it works. Urgent (14%) and Recurring (25%) are drawn
     independently, so the both-at-once card — the one the card's stacked badges
     exist for — was absent by chance. Every third recurring order is forced
     urgent so the case lands on most days: the board is scoped to ONE date, so
     a single forced row would only be visible on the day it happens to fall. */
  rows
    .filter((r) => r.kind === "Recurring")
    .forEach((r, k) => {
      if (k % 3 === 0) r.urgent = true;
    });

  /* REVIEW IS NOT IN THE ROTATION EITHER — adding it there would reshuffle
     the whole fixture — so every third Completed order is sent to review
     here instead. */
  rows
    .filter((r) => r.status === "Completed")
    .forEach((r, k) => {
      if (k % 3 !== 1) return;
      r.status = "Review";
      r.audit = [
        ...r.audit,
        {
          at: new Date(Date.now() - 2_700_000).toISOString(),
          by: CREATED_BY[k % CREATED_BY.length],
          changes: ["Status: Completed → Review"],
        },
      ];
    });

  /* SO DOES PARTIALLY SYNCED, and for the same reason: it is not in the status
     rotation the generator walks, so without this the badge that distinguishes
     it inside the Synced lane would never appear on the board. Every third
     order that reached accounting stops half way — which is roughly how often
     it happens, and often enough to land on most days. */
  rows
    .filter((r) => r.status === "Synced")
    .forEach((r, k) => {
      if (k % 3 !== 1) return;
      r.status = "Partially Synced";
      r.syncError = SYNC_ERRORS[k % SYNC_ERRORS.length];
      r.audit = [
        ...r.audit,
        {
          at: new Date(Date.now() - 1_800_000).toISOString(),
          by: CREATED_BY[k % CREATED_BY.length],
          changes: ["Status: Synced → Partially Synced"],
        },
      ];
    });

  /* CANCELLED HAS TO EXIST TO BE SEEN. It is a terminal exit rather than a
     stage, so it is not in the status rotation the generator walks — without
     this the lane would ship permanently empty, which teaches nothing about
     how it behaves. Every eleventh order, from the ones that had not yet
     reached accounting. */
  rows.forEach((r, k) => {
    if (k % 11 !== 4) return;
    /* Past Completed the order has reached accounting and cannot be
       canceled. (Was `startsWith("Accounting")`, a name retired in the
       status rename, so Verified and Synced orders were being canceled.) */
    if (isDelivered(r.status)) return;
    r.status = "Canceled";
    r.blockedReason = null;
    r.audit = [
      ...r.audit,
      {
        at: new Date(Date.now() - 3_600_000).toISOString(),
        by: CREATED_BY[k % CREATED_BY.length],
        changes: ["Status: Quoting → Canceled", "Canceled by customer"],
      },
    ];
  });

  return rows;
})();

/*
  Invariants. Asserted rather than trusted, because every one of them is a rule
  the SPEC states and a seed could silently break.
*/
export function assertConsistent(rows: BrokerOrder[]): string[] {
  const problems: string[] = [];
  for (const r of rows) {
    /* A CANCELLED ORDER IS A SNAPSHOT of whatever it was when it stopped, so
       the stage rules below do not apply to it — they describe work in
       progress, and there is none. */
    if (r.status === "Canceled") continue;
    if (r.kind === "Movement") {
      if (!r.orderNo.startsWith("M-")) problems.push(`${r.orderNo}: movement order without an M prefix`);
      if (r.orderType !== "Asset Movement") problems.push(`${r.orderNo}: movement order typed ${r.orderType}`);
      if (!r.movement) problems.push(`${r.orderNo}: movement order with no movement detail`);
      if (r.lines.length !== 1) problems.push(`${r.orderNo}: movement orders carry exactly one asset`);
    } else if (!r.orderNo.startsWith("D-")) {
      problems.push(`${r.orderNo}: delivery order without a D prefix`);
    }
    const preVendor = r.status === "Draft" || r.status === "Blocked";
    /* A DRAFT MAY HAVE PARTNERS PICKED — sending is a separate act — but
       nobody can have accepted an invitation that has not gone out, and the
       order cannot have a partner holding it. */
    if (preVendor && (r.vendorId || r.acceptedVendorIds.length)) {
      problems.push(`${r.orderNo}: ${r.status} cannot have an accepted partner`);
    }
    /* QUOTING IS THE ROUND ITSELF (rewritten 2026-09-23). This rule predates
       the status rename and the finalize step: it still said Quoting meant
       "nobody has accepted", when Quoting is exactly where partners accept,
       price the order and one of them is finalized — a partner may hold the
       order before it moves to Assigned. What stays true: a round has to
       have somebody in it. */
    if (r.status === "Quoting" && r.invitedVendorIds.length === 0) {
      problems.push(`${r.orderNo}: Quoting with nobody invited`);
    }
    if (!preVendor && r.status !== "Quoting" && r.acceptedVendorIds.length === 0) {
      problems.push(`${r.orderNo}: ${r.status} with nobody having accepted`);
    }
    if (!preVendor && r.status !== "Quoting" && !r.vendorId) {
      problems.push(`${r.orderNo}: ${r.status} with no partner holding the order`);
    }
    for (const id of r.acceptedVendorIds) {
      if (!r.invitedVendorIds.includes(id)) {
        problems.push(`${r.orderNo}: a vendor accepted an invitation never sent`);
      }
    }
    if (r.vendorId && !r.acceptedVendorIds.includes(r.vendorId)) {
      problems.push(`${r.orderNo}: the order's partner never accepted the invitation`);
    }
    /* A QUOTE FOLLOWS AN ACCEPTANCE. A partner cannot price an order it has not
       agreed to take. */
    for (const q of r.quotes) {
      /* EXCEPT IN A DRAFT, where the broker writes down a price a partner
         gave on the phone — "Add their quotation" — before anything is sent. */
      if (r.status !== "Draft" && !r.acceptedVendorIds.includes(q.vendorId)) {
        problems.push(`${r.orderNo}: a quote from a partner that never accepted`);
      }
      for (const ql of q.lines) {
        if (!r.lines.some((l) => l.asset === ql.asset)) {
          problems.push(`${r.orderNo}: a quote line for an asset not on the order`);
        }
      }
    }
    // A partner has to actually run the line of business the order needs.
    const needs = r.kind === "Movement" ? "Asset Movement" : "Bulk Fuel";
    for (const id of r.invitedVendorIds) {
      const v = VENDORS.find((x) => x.id === id);
      if (v && !v.businessLines.some((b) => b === needs)) {
        problems.push(`${r.orderNo}: ${v.name} does not run ${needs}`);
      }
    }
    if ((r.status === "Blocked") !== (r.blockedReason !== null)) {
      problems.push(`${r.orderNo}: blocked reason and status disagree`);
    }
    if ((r.status === "Partially Synced") !== Boolean(r.syncError)) {
      problems.push(`${r.orderNo}: sync error and status disagree`);
    }
    /* A FALLBACK CONTACT THAT IS THE CONTACT IS NOT A FALLBACK, and a blank
       row in the list is not a person — both come from a form that lets you
       add a row before choosing who goes in it. */
    if (r.secondaryPocs.includes(r.primaryPoc)) {
      problems.push(`${r.orderNo}: the primary POC is also listed as a second contact`);
    }
    if (r.secondaryPocs.some((p) => p === "")) {
      problems.push(`${r.orderNo}: an empty second contact`);
    }
    /* A COMPLETION TIME IS THE RECORD OF A RUN THAT HAPPENED. An order still
       being arranged cannot have one, and one past the delivery cannot be
       missing it — the card in those lanes is built around it. */
    if (isDelivered(r.status) !== (r.completedAt !== null)) {
      problems.push(`${r.orderNo}: ${r.status} and its completion time disagree`);
    }
    /* A WINTER BLEND IS A FUEL THING — lubricants and propane have no
       additive, so the flag would describe a spec nobody can supply. */
    if (r.winterAdditive && r.serviceLine !== "Fuel") {
      problems.push(`${r.orderNo}: winter additive on a ${r.serviceLine} order`);
    }
    for (const l of r.lines) {
      if (l.topOff && l.gal !== null) {
        problems.push(`${r.orderNo}: a top-off line cannot also request gallons`);
      }
      if (!l.topOff && l.gal === null) {
        problems.push(`${r.orderNo}: a non-top-off line needs gallons`);
      }
    }
  }
  return problems;
}

export type BrokerSortDir = "asc" | "desc";
export interface BrokerSortState {
  key: BrokerColumnKey;
  dir: BrokerSortDir;
}

function sortValue(r: BrokerOrder, key: BrokerColumnKey): string | number {
  switch (key) {
    case "order":
      // Numeric part only, so D- and M- series interleave by number rather than
      // the prefix sorting every movement order to one end.
      return Number(r.orderNo.slice(2));
    case "customer":
      return r.customer.title.toLowerCase();
    case "shipTo":
      return r.shipTo.toLowerCase();
    case "date":
      return r.dateKey;
    case "window":
      return r.window.start;
    case "qty":
      return totalGal(r.lines);
    case "vendor":
      return (VENDORS.find((v) => v.id === r.vendorId)?.name ?? "").toLowerCase();
    case "status":
      // Lifecycle order, not alphabetical — sorting by status means "how far
      // along is this", and A-Z would put Synced before Draft.
      return BROKER_STATUSES.indexOf(r.status);
    case "type":
      // The disc's letter is a shorthand for the order type, so sort by the
      // thing it is short FOR rather than by the letter.
      return r.orderType.toLowerCase();
    case "products":
      // The first product is what the cell shows; the "+2" is a count of what
      // it could not. Sorting by what is written is the only honest option.
      return (r.lines[0]?.product ?? "").toLowerCase();
    case "createdBy":
      return r.createdBy.toLowerCase();
    case "business":
      return businessOf(r) ?? "";
    case "orderType":
      return r.orderType.toLowerCase();
    case "poNumber":
      // BLANKS LAST, both ways round. A PO number is a thing an order either
      // has or has not, and sorting the empty ones to the top on one press
      // buries every row that answers the question.
      return r.poNumber ? r.poNumber.toLowerCase() : "\uffff";
    case "hub":
      return r.hub.toLowerCase();
    case "salesperson":
      return r.salesperson.toLowerCase();
    case "tags":
      return r.tags.length ? r.tags.join(", ").toLowerCase() : "\uffff";
    default:
      return "";
  }
}

export function sortBrokerOrders(
  rows: BrokerOrder[],
  sort: BrokerSortState | null
): BrokerOrder[] {
  if (!sort) return rows;
  const dir = sort.dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const av = sortValue(a, sort.key);
    const bv = sortValue(b, sort.key);
    if (av === bv) return 0;
    return av > bv ? dir : -dir;
  });
}

export function matchesBrokerOrder(r: BrokerOrder, q: string): boolean {
  return [
    r.orderNo,
    r.customer.title,
    r.customer.description,
    r.shipTo,
    r.date.title,
    r.status,
    r.kind,
    r.orderType,
    r.poNumber,
    r.hub,
    r.primaryPoc,
    r.salesperson,
    VENDORS.find((v) => v.id === r.vendorId)?.name ?? "",
    ...r.lines.map((l) => `${l.asset} ${l.product}`),
  ]
    .join(" ")
    .toLowerCase()
    .includes(q);
}

export const BROKER_SEARCH_FIELDS = [
  { key: "order", label: "Order #", text: (r: BrokerOrder) => r.orderNo },
  { key: "type", label: "Type", text: (r: BrokerOrder) => r.orderType },
  {
    key: "customer",
    label: "Customer",
    text: (r: BrokerOrder) => `${r.customer.title} ${r.customer.description}`,
  },
  { key: "shipTo", label: "Ship To", text: (r: BrokerOrder) => r.shipTo },
  { key: "date", label: "Planned Date", text: (r: BrokerOrder) => r.date.title },
  {
    key: "vendor",
    label: "Vendor",
    text: (r: BrokerOrder) => VENDORS.find((v) => v.id === r.vendorId)?.name ?? "",
  },
  { key: "status", label: "Status", text: (r: BrokerOrder) => r.status },
  { key: "poNumber", label: "PO Number", text: (r: BrokerOrder) => r.poNumber },
];

/**
 * THE TEXT A COLUMN SHOWS, for the filter box that sits under it.
 *
 * `BROKER_SEARCH_FIELDS` is a different list on purpose: it is what the global
 * search looks INTO, which includes things no column draws. A box under a
 * header has to match what is written above the rows beneath it — filtering
 * "Vendor" on a name the Vendor cell does not print would hide rows for a
 * reason nobody could see.
 */
export function brokerColumnText(r: BrokerOrder, key: BrokerColumnKey): string {
  switch (key) {
    case "order":
      return r.orderNo;
    case "type":
      return r.orderType;
    case "customer":
      return `${r.customer.title} ${r.customer.description}`;
    case "shipTo":
      return r.shipTo;
    case "date":
      return `${r.date.title} ${r.date.description ?? ""}`;
    case "window":
      return `${r.window.start} ${r.window.end}`;
    case "products":
      return r.lines.map((l) => l.product).join(" ");
    case "qty": {
      const g = totalGal(r.lines);
      return isAllTopOff(r.lines) ? "Top-off" : g ? g.toLocaleString() : "";
    }
    case "vendor":
      return (
        VENDORS.find((v) => v.id === r.vendorId)?.name ??
        (r.invitedVendorIds.length ? `${r.invitedVendorIds.length} invited` : "")
      );
    case "status":
      return r.status;
    case "createdBy":
      return r.createdBy;
    case "business":
      return r.business ?? "";
    case "orderType":
      return r.orderType;
    case "poNumber":
      return r.poNumber;
    case "hub":
      return r.hub;
    case "salesperson":
      return r.salesperson;
    case "tags":
      return r.tags.join(" ");
    default:
      return "";
  }
}

export function matchesBrokerOrderIn(
  r: BrokerOrder,
  q: string,
  scope: string
): boolean {
  if (!q) return true;
  const f = BROKER_SEARCH_FIELDS.find((x) => x.key === scope);
  return f ? f.text(r).toLowerCase().includes(q) : true;
}

/*
  ── The app's own status mappings ──────────────────────────────────────────────
  Per the DS's colour governance a status carries no colour until a usage rule
  binds it: the DS ships visual CHANNELS (`StatusTone`) and lane FILLS
  (`--fp-lane-*`), and each application declares its own mapping. This is 3PL's,
  declared once here so the board, the table and the sheet cannot drift — exactly
  how `statusTone()` in `tables-layout/data.ts` does it for the DS's own table.
*/

/** Lane fills, following the lifecycle: neutral -> in-flight -> done, with the
 *  credit hold as the one red. */
export const BROKER_LANE_COLOR: Record<BrokerStatus, LaneColorName> = {
  Draft: "grey",
  Blocked: "red",
  Quoting: "blue",
  Assigned: "cyan",
  Completed: "green",
  Review: "orange",
  Verified: "yellow",
  "Partially Synced": "yellow",
  Synced: "purple",
  Canceled: "grey",
};

/** The DS lane palette's key names. Kept as a local type so this data module
 *  does not import from a component. */
type LaneColorName =
  | "grey"
  | "blue"
  | "yellow"
  | "green"
  | "cyan"
  | "purple"
  | "violet"
  | "pink"
  | "orange"
  | "red";

/**
 * Chip tones. The DS ships four channels and this lifecycle has seven stages, so
 * three of them share `processing` — which is correct rather than a compromise:
 * Quoting, Assigned and Verified are all "in flight", and the DS's rule is that
 * colour is never the only carrier of meaning. The label spells the stage out in
 * every case.
 */
export const BROKER_STATUS_TONE = statusTones<BrokerStatus>({
  /* A record that exists, not yet a state. */
  Draft: "neutral",
  /* Something has gone wrong and the plan has to change. */
  Blocked: "critical",
  /* Waiting on partners to quote, then on the dispatcher to award. */
  Quoting: "caution",
  /* A partner is on it. True, and asks nothing. */
  Assigned: "info",
  Completed: "success",
  /* Somebody is checking the numbers — waiting on a person. */
  Review: "caution",
  /* A human has agreed the numbers — the part that needed a person is done. */
  Verified: "success",
  /* The sync was tried and failed. A problem to fix, not a step forward. */
  "Partially Synced": "critical",
  Synced: "success",
  Canceled: "neutral",
});

/** Half-hour grid for the §5.3 start/end window selects. */
export const TIME_OPTIONS: string[] = (() => {
  const out: string[] = [];
  for (let h = 0; h < 24; h++) {
    for (const m of [0, 30]) {
      const hour12 = h % 12 === 0 ? 12 : h % 12;
      out.push(`${hour12}:${m === 0 ? "00" : "30"} ${h < 12 ? "AM" : "PM"}`);
    }
  }
  return out;
})();

/**
 * "6:00 AM" -> 360. The delivery window is stored as the formatted strings the
 * UI shows, so anything that ORDERS by time has to parse them — sorting the
 * strings puts "10:00 AM" before "6:00 AM".
 */
export function timeToMinutes(t: string): number {
  const m = /^(\d{1,2}):(\d{2})\s*(AM|PM)$/i.exec(t.trim());
  if (!m) return 0;
  let h = Number(m[1]) % 12;
  if (m[3].toUpperCase() === "PM") h += 12;
  return h * 60 + Number(m[2]);
}

import { DATE_FMT, dateKeyOf, relativeLabel, startOfDay } from "../data";
import type { TwoLine } from "../types";
import { decodeFrequency, toSchedule } from "./RuleFrequency";
import {
  BROKER_ORDERS,
  isDelivered,
  type BrokerOrder,
  type BrokerStatus,
  type OrderLine,
} from "./orders";

/*
  RECURRING ORDERS — V2, THE PARENT/CHILD MODEL.

  This is the shape the product has TODAY, transcribed from the "Recurring
  Orders - 3PL" engineering doc (2026-09-18) rather than guessed. It is one of
  two versions built deliberately side by side so the difference can be SEEN
  rather than argued about:

    V2 (this file) — the recurring order IS an order. It carries the schedule
                     and it is also the first delivery. Everything after it is
                     a child of that order.
    V1 (not built) — the schedule is a RULE that is not an order, and every
                     delivery, including the first, is generated by it.

  WHAT THE DOC FIXES, AND THIS FILE OBEYS

    • A generated order is a COMPLETE, INDEPENDENT ORDER — its own number, its
      own products, its own status, its own history. Not an "occurrence".
    • CHANGES FLOW DOWNWARD ONLY. The parent can rewrite its children; a child
      never writes back.
    • NOTHING GENERATES UNTIL A PARTNER IS LOCKED IN. Not at setup, not on the
      start date. That is why `stalledReason` exists below — a series can be
      perfectly healthy and producing nothing, and the doc names that as the
      commonest support call there is.
    • THE HORIZON IS A ROLLING MONTH — today through one month out, and never
      a date in the past. A schedule that started in March does not back-fill.
    • THE PARENT'S OWN DATE IS SKIPPED, so day one does not produce two orders.

  THE DOUBLE LIFE IS SHOWN, NOT HIDDEN. Because the parent is both the rule and
  a delivery, it appears twice in this module: once as the series, and once as
  the first row inside its own list of deliveries, flagged `isParent`. That is
  not a bug in the model — it IS the model, and V1 exists precisely because of
  it. Smoothing it over in the prototype would hide the thing being compared.

  INVENTED, and flagged: the child order numbers (drawn from a band above the
  seeded ones so they cannot collide), the delivered history before today, and
  the reading of "Custom" as a fortnightly schedule — see `parseSchedule`.
*/

/**
 * §"Where a broker sees it" — the six states a series can be in.
 *
 * SIX WORDS, FOUR TONES. The DS ships four status tones and no more, so two
 * pairs must share one. Canceled/Ended/Expired all read neutral, which the
 * doc explicitly warns about: "if they share a visual treatment, the
 * difference disappears — and the difference is the whole audit story."
 *
 * The answer is NOT a fifth colour. It is the second line: a series that was
 * stopped by a person says who and when, and one that simply ran out of road
 * says the date it ran out. The word carries the state and the line under it
 * carries the difference — which is the same call the DS makes everywhere
 * else (§11: a status is its word).
 */
export type SeriesStatus =
  | "Upcoming"
  | "Active"
  | "Paused"
  | "Canceled"
  | "Ended"
  | "Expired";

export const SERIES_STATUSES: SeriesStatus[] = [
  "Upcoming",
  "Active",
  "Paused",
  "Canceled",
  "Ended",
  "Expired",
];

/** What each one means, in the doc's own words. Shown in the filter menu. */
export const SERIES_STATUS_MEANING: Record<SeriesStatus, string> = {
  Upcoming: "Set up, but the start date hasn't arrived",
  Active: "Running and generating orders",
  Paused: "Temporarily stopped; will resume",
  Canceled: "Stopped by the broker; stays visible and editable",
  Ended: "The broker deliberately ended it on a date",
  Expired: "Its end date simply passed",
};

/* ---------------------------------------------------------------------------
 * The schedule
 * ------------------------------------------------------------------------ */

const WEEKDAYS = [
  "Sunday",
  "Monday",
  "Tuesday",
  "Wednesday",
  "Thursday",
  "Friday",
  "Saturday",
];

const MONTHS = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

export interface Schedule {
  /** The stored string, kept so the sheet can show what was actually set. */
  raw: string;
  /** Plain words for the list — "Every Thursday", not "Weekly On Thursday". */
  label: string;
  /** Whether a given day is on the schedule. */
  hits: (d: Date) => boolean;
  /**
   * WHICH WEEKDAYS IT LANDS ON, 0 = Sunday … 6 = Saturday.
   *
   * The list renders this as a row of seven letters with the ones it hits lit,
   * which answers "when does this run" at a glance in a way "Monthly On First
   * Thursday" never will — a reader scanning twenty rules is comparing
   * SHAPES, and seven dots compare instantly where a sentence has to be read.
   *
   * EMPTY WHERE THE PATTERN IS NOT A WEEKDAY ONE. A yearly date is not a
   * weekday habit, and lighting the weekday it happens to fall on this year
   * would be a lie about what the rule says.
   */
  days: number[];
  /**
   * A SINGLE NAMED BADGE INSTEAD OF THE ROW, where seven lit letters would say
   * less than one word. `Daily` lights all seven, which is a row nobody needs
   * to read; `Yearly` lights none, which is a row that says nothing.
   */
  badge: string | null;
  /** CUSTOM CYCLE — one weekday list per week, drawn as a row each. */
  cycle?: number[][];
  /**
   * THE LINE UNDER THE BADGES — how often the pattern repeats, which the
   * letters cannot carry. The same three lit letters mean every week, every
   * second week, or the first week of the month, and that difference is the
   * whole schedule.
   */
  cadence: string;
}

function dayFromKey(key: string): Date {
  const [y, m, d] = key.split("-").map(Number);
  return new Date(y, m - 1, d);
}

/** Which occurrence of its weekday a date is — 1 for the first Thursday, etc. */
function nthWeekdayOfMonth(d: Date): number {
  return Math.floor((d.getDate() - 1) / 7) + 1;
}

/**
 * Turns the stored frequency string into something that can be both READ and
 * COMPUTED. The seed stores phrases like "Monthly On First Thursday"; the list
 * needs "First Thursday of the month" and the generator needs a predicate, and
 * deriving both from one place is what stops the two drifting apart.
 *
 * "CUSTOM" IS READ AS FORTNIGHTLY, and this is the one liberty taken. The seed
 * ships "Custom" as a frequency with nothing behind it, which would leave those
 * rows with no schedule to describe and no dates to generate — a row that looks
 * broken rather than one that teaches anything. Anchoring it to every second
 * week on the start date's own weekday keeps it derived from real data rather
 * than invented from nothing. What "Custom" should actually offer a broker is
 * an open question, not a decision this file is making.
 */
export function parseSchedule(raw: string, anchorKey: string): Schedule {
  /* THE RULE'S FREQUENCY UNIT, set on an order (Pavan, 2026-10-20). */
  const unit = decodeFrequency(raw);
  if (unit) return toSchedule(unit);
  const anchor = dayFromKey(anchorKey);

  if (raw === "Daily") {
    return {
      raw,
      label: "Every day",
      hits: () => true,
      days: [0, 1, 2, 3, 4, 5, 6],
      badge: "Daily",
      cadence: "Every day, weekends included",
    };
  }

  if (raw === "Every Weekday (Monday To Friday)") {
    return {
      raw,
      label: "Every weekday",
      hits: (d) => d.getDay() >= 1 && d.getDay() <= 5,
      days: [1, 2, 3, 4, 5],
      badge: null,
      cadence: "Every week",
    };
  }

  const weekly = /^Weekly On (\w+)$/.exec(raw);
  if (weekly) {
    const wd = WEEKDAYS.indexOf(weekly[1]);
    return {
      raw,
      label: `Every ${weekly[1]}`,
      hits: (d) => d.getDay() === wd,
      days: [wd],
      badge: null,
      cadence: "Every week",
    };
  }

  const monthly = /^Monthly On (\w+) (\w+)$/.exec(raw);
  if (monthly) {
    const nth = ["First", "Second", "Third", "Fourth"].indexOf(monthly[1]) + 1;
    const wd = WEEKDAYS.indexOf(monthly[2]);
    return {
      raw,
      label: `${monthly[1]} ${monthly[2]} of the month`,
      hits: (d) => d.getDay() === wd && nthWeekdayOfMonth(d) === nth,
      days: [wd],
      badge: null,
      cadence: `${monthly[1]} week of every month`,
    };
  }

  const yearly = /^Annually On (\w+) (\d+)$/.exec(raw);
  if (yearly) {
    const mo = MONTHS.indexOf(yearly[1]);
    const day = Number(yearly[2]);
    return {
      raw,
      label: `Every year on ${yearly[1]} ${day}`,
      hits: (d) => d.getMonth() === mo && d.getDate() === day,
      /* A DATE, NOT A WEEKDAY. September 3 is a Thursday this year and a
         Friday the next; lighting Thursday would describe the calendar rather
         than the rule. */
      days: [],
      badge: "Yearly",
      cadence: `Every year on ${yearly[1]} ${day}`,
    };
  }

  /* Custom — see the note above. */
  const wd = anchor.getDay();
  return {
    raw,
    label: `Every 2 weeks on ${WEEKDAYS[wd]}`,
    days: [wd],
    badge: null,
    cadence: "Every 2 weeks",
    hits: (d) => {
      if (d.getDay() !== wd) return false;
      const weeks = Math.round(
        (startOfDay(d).getTime() - startOfDay(anchor).getTime()) /
          (7 * 86_400_000)
      );
      return weeks % 2 === 0;
    },
  };
}

/* ---------------------------------------------------------------------------
 * A generated order
 * ------------------------------------------------------------------------ */

/**
 * ONE DELIVERY IN A SERIES.
 *
 * Deliberately a SMALL record rather than a whole `BrokerOrder`. A generated
 * order really is a complete order in the product, but this screen only ever
 * shows six of its fields, and materialising 300 full orders to render 300
 * table cells would put a second, divergent copy of the orders fixture in the
 * prototype. Opening one is what hands the reader the real order.
 */
export interface Delivery {
  id: string;
  orderNo: string;
  dateKey: string;
  /** Formatted date over its relative label — the same cell the lists use. */
  date: TwoLine;
  status: BrokerStatus;
  vendorId: string | null;
  lines: OrderLine[];
  /**
   * TRUE ON THE ONE ROW THAT IS ALSO THE RECURRING ORDER. In V2 the first
   * delivery and the schedule are the same record, so this row is the parent
   * seen from below. It is flagged rather than dropped because hiding it would
   * hide the thing V1 exists to fix.
   */
  isParent: boolean;
  /** Canceled by a pause, not by a person — restored when the pause lifts. */
  cancelledByPause: boolean;
}

/* ---------------------------------------------------------------------------
 * A series
 * ------------------------------------------------------------------------ */

export interface PauseRecord {
  fromKey: string;
  /** `null` is "until I say so" — the doc's Pause now. */
  toKey: string | null;
  by: string;
  at: string;
}

export interface RecurringSeries {
  id: string;
  /** The recurring order itself. It carries the schedule AND is delivery one. */
  parent: BrokerOrder;
  schedule: Schedule;
  /** The anchor: the parent's own delivery date. */
  startKey: string;
  /** `null` is the doc's "Never". */
  endKey: string | null;
  status: SeriesStatus;
  /**
   * WHY NOTHING IS BEING GENERATED, in plain words, or `null` when it is.
   *
   * Straight out of the doc's "When nothing gets created" table, which it
   * introduces as "the list to consult when a broker reports my orders stopped
   * appearing". Every one of those situations is silent in the product today —
   * logged, never shown. A row that says "Active" over an empty delivery list
   * and offers no reason is the single most expensive screen in this feature.
   */
  stalledReason: string | null;
  /** The rolling month, plus a short tail of delivered history. */
  deliveries: Delivery[];
  /** The next date an order will land on, or `null` when none will. */
  nextKey: string | null;
  pauses: PauseRecord[];
}

/** The rolling horizon the doc fixes: today through one month out. */
const HORIZON_DAYS = 31;

/** How much delivered history to keep on screen. */
const HISTORY_KEPT = 3;

/** Child numbers are drawn above every seeded one so they cannot collide. */
const CHILD_NO_BASE = 200_000;

function twoLineDate(d: Date, today: Date): TwoLine {
  const offset = Math.round(
    (startOfDay(d).getTime() - startOfDay(today).getTime()) / 86_400_000
  );
  return { title: DATE_FMT.format(d), description: relativeLabel(offset, d) };
}

function addDays(d: Date, n: number): Date {
  const out = new Date(d);
  out.setDate(out.getDate() + n);
  return out;
}

/**
 * Every date the schedule wants between two days, inclusive. Walking day by day
 * rather than stepping by the frequency is what makes one function serve all
 * five shapes — "first Thursday of the month" has no interval to step by.
 */
function datesBetween(schedule: Schedule, from: Date, to: Date): Date[] {
  const out: Date[] = [];
  for (let d = startOfDay(from); d <= to; d = addDays(d, 1)) {
    if (schedule.hits(d)) out.push(new Date(d));
  }
  return out;
}

/**
 * THE DELIVERED TAIL. A series that has been running has orders behind it, and
 * a list that starts at today reads as a series that started at today. Only
 * dates the schedule actually wanted, only before today, only the last few —
 * and never re-dated or moved by anything, which is the doc's own rule about
 * completed work.
 */
function history(
  schedule: Schedule,
  startKey: string,
  today: Date,
  seedIndex: number
): { date: Date; status: BrokerStatus }[] {
  const start = dayFromKey(startKey);
  if (start >= today) return [];
  const past = datesBetween(schedule, start, addDays(today, -1)).filter(
    (d) => dateKeyOf(d) !== startKey
  );
  /* The settled statuses, cycled by index so every one of them is reachable
     somewhere in the fixture rather than left to chance. */
  const settled: BrokerStatus[] = ["Completed", "Review", "Verified", "Synced"];
  return past.slice(-HISTORY_KEPT).map((d, k) => ({
    date: d,
    status: settled[(seedIndex + k) % settled.length],
  }));
}

/**
 * Builds one series from its recurring order.
 *
 * `override` is how the screen's own pause / end / cancel actions reach this —
 * the seed is static, so a broker pausing a series hands the change back in
 * here and the whole series is rebuilt from it. Rebuilding beats patching for
 * the reason the doc gives about schedule edits: the rules live in one place,
 * and a second place that decides which orders exist is a second place to get
 * it wrong.
 */
export interface SeriesOverride {
  canceled?: boolean;
  endKey?: string | null;
  pauses?: PauseRecord[];
}

export function buildSeries(
  parent: BrokerOrder,
  seedIndex: number,
  today: Date,
  override: SeriesOverride = {}
): RecurringSeries {
  const startKey = parent.recurrence?.fromDateKey ?? parent.dateKey;
  const schedule = parseSchedule(
    parent.recurrence?.frequency ?? "Custom",
    startKey
  );
  const endKey = override.endKey ?? null;
  const pauses = override.pauses ?? [];
  const start = dayFromKey(startKey);
  const todayKey = dateKeyOf(today);

  /* ── The series' own state ──────────────────────────────────────────────
     Order matters. A canceled series is canceled whatever its dates say, a
     paused one is paused whatever its schedule says, and only then do the
     dates get a vote. */
  const activePause = pauses.find(
    (p) => p.fromKey <= todayKey && (p.toKey === null || p.toKey >= todayKey)
  );

  let status: SeriesStatus;
  if (override.canceled || parent.status === "Canceled") status = "Canceled";
  else if (activePause) status = "Paused";
  else if (endKey && endKey < todayKey) status = "Ended";
  else if (start > today) status = "Upcoming";
  else status = "Active";

  /* An end date that arrived on its own is EXPIRED; one a person set and then
     passed is ENDED. Same dates, different stories — which is exactly the
     distinction the doc says must survive. */
  if (status === "Ended" && override.endKey === undefined) status = "Expired";

  /* ── Why it is producing nothing, if it is ───────────────────────────────
     The doc's table, in the doc's order. Only ONE reason is shown: a series
     that is both paused and unassigned is paused, and a list of every reason
     at once is a list nobody reads. */
  const vendorLocked = parent.vendorId !== null;
  let stalledReason: string | null = null;
  if (status === "Paused") {
    stalledReason = activePause?.toKey
      ? `Paused until ${DATE_FMT.format(dayFromKey(activePause.toKey))}`
      : "Paused — no resume date set";
  } else if (status === "Canceled") {
    stalledReason = "Canceled — the schedule is kept, generation stopped";
  } else if (status === "Ended" || status === "Expired") {
    stalledReason = "Past its end date";
  } else if (!vendorLocked) {
    /* THE ONE THE DOC CALLS OUT. Setup does not generate; a partner accepting
       does. Until then the series is healthy, visible, and silent. */
    stalledReason = "No partner assigned — nothing will be created yet";
  } else if (parent.status === "Blocked") {
    stalledReason = "The order is blocked on a credit issue";
  }

  /* ── The deliveries ─────────────────────────────────────────────────────
     History first, then the parent on its own date, then the rolling month.
     Nothing is generated at all unless a partner is locked in. */
  const deliveries: Delivery[] = [];

  history(schedule, startKey, today, seedIndex).forEach((h, k) => {
    deliveries.push({
      id: `${parent.id}-h${k}`,
      orderNo: `D-${CHILD_NO_BASE + seedIndex * 40 + k}`,
      dateKey: dateKeyOf(h.date),
      date: twoLineDate(h.date, today),
      status: h.status,
      vendorId: parent.vendorId,
      lines: parent.lines,
      isParent: false,
      cancelledByPause: false,
    });
  });

  deliveries.push({
    id: parent.id,
    orderNo: parent.orderNo,
    dateKey: startKey,
    date: twoLineDate(start, today),
    status: parent.status,
    vendorId: parent.vendorId,
    lines: parent.lines,
    isParent: true,
    cancelledByPause: false,
  });

  if (vendorLocked && status !== "Upcoming") {
    const from = start > today ? start : today;
    const to = addDays(today, HORIZON_DAYS);
    const wanted = datesBetween(schedule, from, to)
      /* THE PARENT'S OWN DATE IS SKIPPED — day one must not produce two. */
      .filter((d) => dateKeyOf(d) !== startKey)
      /* NEVER PAST THE END DATE. */
      .filter((d) => !endKey || dateKeyOf(d) <= endKey);

    wanted.forEach((d, k) => {
      const key = dateKeyOf(d);
      const inPause = pauses.some(
        (p) => p.fromKey <= key && (p.toKey === null || p.toKey >= key)
      );
      deliveries.push({
        id: `${parent.id}-g${k}`,
        orderNo: `D-${CHILD_NO_BASE + seedIndex * 40 + HISTORY_KEPT + k}`,
        dateKey: key,
        date: twoLineDate(d, today),
        /* THE DOC'S OWN WORD: a generated order arrives ready for the partner,
           which in this module's vocabulary is Assigned. */
        status: inPause ? "Canceled" : "Assigned",
        vendorId: parent.vendorId,
        lines: parent.lines,
        isParent: false,
        cancelledByPause: inPause,
      });
    });
  }

  deliveries.sort((a, b) => a.dateKey.localeCompare(b.dateKey));

  const next =
    deliveries.find(
      (d) =>
        d.dateKey >= todayKey &&
        !isDelivered(d.status) &&
        d.status !== "Canceled"
    )?.dateKey ?? null;

  return {
    id: parent.id,
    parent,
    schedule,
    startKey,
    endKey,
    status,
    stalledReason,
    deliveries,
    nextKey: next,
    pauses,
  };
}

/** How many orders of this series are still ahead — what the list counts. */
export function upcomingCount(s: RecurringSeries, today: Date): number {
  const key = dateKeyOf(today);
  return s.deliveries.filter(
    (d) => d.dateKey >= key && d.status !== "Canceled" && !isDelivered(d.status)
  ).length;
}

/** The recurring orders in the fixture, in the order the board shows them. */
export const RECURRING_PARENTS: BrokerOrder[] = BROKER_ORDERS.filter(
  (o) => o.kind === "Recurring"
);

/** Free-text match — the same fields the orders list is findable by. */
export function matchesSeries(s: RecurringSeries, q: string): boolean {
  const needle = q.trim().toLowerCase();
  if (!needle) return true;
  return [
    s.parent.orderNo,
    s.parent.customer.title,
    s.parent.customer.description,
    s.parent.shipTo,
    s.schedule.label,
    s.status,
  ]
    .join(" ")
    .toLowerCase()
    .includes(needle);
}

import { DATE_FMT, dateKeyOf, relativeLabel, startOfDay } from "../data";
import { HUBS, SHIP_TO_SITES, type BrokerOrder } from "./orders";
import {
  liveTargets,
  programRunsOn,
  targetSkips,
  type RecurringProgram,
} from "./recurringPrograms";

/*
  A RULE CUTS REAL ORDERS (Pavan, 2026-09-24).

  On every date the rule's frequency hits, each live ship-to on it gets its
  own Delivery Order — daily means one a day, per site. The order lands in the
  Orders lane as a Draft with the Recurring badge, carrying what the rule and
  the ship-to row say. From there it is an ordinary order: the broker edits
  it, invites, finalizes, and it moves on like any other.

  CUT AHEAD, NOT FOREVER. Orders exist from today up to LEAD_DAYS ahead, so
  a broker can see and prepare the coming week; later dates are cut as the
  days arrive. Nothing is cut for the past — those days were either run or
  missed, and a fresh Draft dated yesterday would be neither.

  ONCE PER RULE · SHIP-TO · DATE. The id is built from those three, so an
  order already cut is never cut again, and the broker's edits to it stand.
*/

export const LEAD_DAYS = 7;

export const recurringOrderId = (programId: string, targetId: string, dateKey: string) =>
  `rec-${programId}-${targetId}-${dateKey}`;

/** The days in [from, to] that orders may be cut for — today to LEAD_DAYS on. */
export function cuttableDays(from: Date, to: Date): Date[] {
  const today = startOfDay(new Date());
  const last = new Date(today);
  last.setDate(last.getDate() + LEAD_DAYS);
  const start = from > today ? startOfDay(from) : today;
  const end = to < last ? startOfDay(to) : last;
  const out: Date[] = [];
  for (const d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) out.push(new Date(d));
  return out;
}

/**
 * The orders the rules owe for these days that do not exist yet. Numbers
 * start at `firstNo` and go up by one.
 */
export function ordersFromPrograms(
  programs: RecurringProgram[],
  days: Date[],
  existing: ReadonlySet<string>,
  firstNo: number
): BrokerOrder[] {
  const out: BrokerOrder[] = [];
  let no = firstNo;
  const today = startOfDay(new Date());
  for (const day of days) {
    const dateKey = dateKeyOf(day);
    const offset = Math.round((day.getTime() - today.getTime()) / 86_400_000);
    for (const p of programs) {
      if (!programRunsOn(p, day)) continue;
      for (const t of liveTargets(p)) {
        /* A ship-to that sits this day out — a resolved clash. */
        if (targetSkips(t, day)) continue;
        const id = recurringOrderId(p.id, t.id, dateKey);
        if (existing.has(id)) continue;
        const site = SHIP_TO_SITES.find((s) => s.name === t.shipTo);
        out.push({
          id,
          orderNo: `D-${no++}`,
          kind: "Recurring",
          orderType: p.orderType,
          customer: t.customer,
          shipTo: t.shipTo,
          date: { title: DATE_FMT.format(day), description: relativeLabel(offset, day) },
          dateKey,
          window: t.window,
          lines: t.lines.map((l) => ({ ...l })),
          status: "Draft",
          vendorId: null,
          /* The rule's partners are listed on the order, not yet asked —
             inviting is still the broker's act. */
          invitedVendorIds: [...p.vendorIds],
          sentVendorIds: [],
          acceptedVendorIds: [],
          quoteRequested: false,
          quotes: [],
          orderFees: [],
          invoiceState: "none",
          serviceLine: p.serviceLine,
          business: p.business,
          audit: [
            {
              at: new Date().toISOString(),
              by: "System — Recurring",
              changes: [`Order created from rule ${p.programNo}`],
            },
          ],
          urgent: false,
          signatureOnDelivery: p.signatureOnDelivery,
          poNumber: t.poNumber,
          zip: site?.zip ?? "",
          state: site?.state ?? t.state,
          createdBy: "System — Recurring",
          tags: [...p.tags],
          loadOrder: p.loadOrder
            ? p.loadRows.flatMap((r) =>
                r.products.map((product) => ({
                  product,
                  terminal: r.terminal,
                  supplier: r.supplier,
                  loadingAccount: r.loadingAccount,
                }))
              )
            : null,
          recurrence: { fromDateKey: p.startKey, frequency: p.schedule.label },
          hub: HUBS[0],
          jobType: p.jobType,
          primaryPoc: t.poc,
          secondaryPocs: [],
          salesperson: "",
          instructions: t.instructions,
          internalNote: p.internalNote,
          winterAdditive: t.lines.some((l) => p.winterProducts.includes(l.product)),
          notifyVendor: false,
          completedAt: null,
          blockedReason: null,
          movement: null,
        });
      }
    }
  }
  return out;
}

import * as React from "react";
import { DATE_FMT, dateKeyOf, startOfDay } from "../data";
import { CUSTOMERS } from "../customers";
import type { TwoLine } from "../types";
import {
  LOADING_ACCOUNTS,
  SHIP_TO_SITES,
  defaultLineCharges,
  type BrokerOrderType,
  type JobType,
  type OrderLine,
  type ServiceLine,
} from "./orders";
import { parseSchedule, type Schedule, type SeriesStatus } from "./recurring";
import type { RuleFrequency } from "./RuleFrequency";
import { VENDORS, type Vendor } from "./vendors";

/*
  RECURRING ORDERS — V1.1, THE LANE-FIRST PROGRAMME.

  IT SITS BESIDE V1 AND V2 AND REPLACES NEITHER (Pavan, 2026-09-21).

  THE INVERSION IS THE WHOLE IDEA. V1 is customer-first: pick the customer, then
  find somebody to haul it. Here you pick the PARTNER first, and the only
  customers and ship-tos on offer are the ones that partner can actually reach.
  You are filling a haulier's capacity across a region, not servicing one
  account — and that is a different act, which is why it is its own version
  rather than a switch on V1.

  WHAT THE INVERSION FIXES. Three things break when one rule spans many sites:
  the partner's service area, where product is lifted from, and the price. The
  first is fixed by making the partner the gate — an unreachable site is never
  offered, so a programme cannot be built that the partner cannot run. The
  second is a broker's own judgement and is left free. The third does not fan
  out at all, and that is what the second layer is for.

  TWO LAYERS.

    The programme  what is true of every delivery it will ever make — the
                   partner, where it loads, the product, and the FREQUENCY.
    The targets    a row per ship-to for everything that moves: the tanks and
                   quantities, the window, the contacts, and both prices.

  BOTH PRICES SIT ON THE ROW, SO THE ROW CARRIES THE MARGIN. That makes the
  programme a margin table for a whole book of work — twelve lanes and what
  each one earns, in one grid. It is the thing this version can show that
  neither of the others can.

  FREQUENCY IS CONSTITUTIVE, and this is the sharpest rule here. A site that
  wants a different day is not on this programme; it belongs to another one.
  No per-site override, ever. Two things follow, and both are worth having:
  a programme DESCRIBES ITSELF — partner · product · frequency, and you can
  read it from its title without opening it — and putting one ship-to on two
  programmes for the same product becomes a collision worth catching at the
  moment somebody adds it, rather than when two trucks turn up.

  A TARGET IS A SHIP-TO, NOT AN ASSET. A truck filling three tanks at one site
  is one order, not three. So the unit is the site, assets are lines inside it,
  and the grid stays two-dimensional — targets down, dates across.

  INVENTED, and flagged: the programme numbers, the lane prices, which lanes
  have been accepted, and which sites have fallen out of coverage.
*/

/* ---------------------------------------------------------------------------
 * Coverage — the gate
 * ------------------------------------------------------------------------ */

export interface ShipToSite {
  name: string;
  city: string;
  state: string;
  zip: string;
  assets: { name: string; product: string; rental?: boolean }[];
}

/**
 * CAN THIS PARTNER REACH THIS SITE?
 *
 * Read off the partner's own service area, in the terms that area is declared
 * in — a zip list is not a state list and treating them alike would offer a
 * site the partner has never heard of. `radius` and `custom` have no geometry
 * in this fixture, so they fall back to the states, which is the honest
 * approximation: it is the widest thing the record actually says.
 */
export function canServe(v: Vendor, site: ShipToSite): boolean {
  if (!v.active || !v.approvedForAssignment) return false;
  switch (v.serviceAreaType) {
    case "zip":
      return v.coveredZips.includes(site.zip);
    case "state":
      return v.serviceStates.includes(site.state);
    default:
      return (
        v.coveredCities.includes(site.city) ||
        v.serviceStates.includes(site.state)
      );
  }
}

export const siteByName = (name: string): ShipToSite | undefined =>
  SHIP_TO_SITES.find((s) => s.name === name) as ShipToSite | undefined;

/** Every customer + ship-to pair this partner could be given. */
export function reachableTargets(
  v: Vendor
): { customer: TwoLine; shipTo: string; site: ShipToSite }[] {
  const out: { customer: TwoLine; shipTo: string; site: ShipToSite }[] = [];
  for (const c of CUSTOMERS) {
    for (const name of c.shipTos) {
      const site = siteByName(name);
      if (!site || !canServe(v, site)) continue;
      out.push({
        customer: { title: c.name, description: c.erpId },
        shipTo: name,
        site,
      });
    }
  }
  return out;
}

/* ---------------------------------------------------------------------------
 * A target — one ship-to on the programme
 * ------------------------------------------------------------------------ */

/**
 * WHERE A LANE HAS GOT TO WITH THE PARTNER.
 *
 * One partner, many lanes, priced per lane — so acceptance happens per lane,
 * and a programme can be PARTLY LIVE. Eight sites delivering while four are
 * still being argued over is the ordinary case, not an edge one, and it is the
 * state the screen exists to show.
 */
export type LaneState = "Draft" | "Invited" | "Quoted" | "Accepted" | "Declined";

export const LANE_STATES: LaneState[] = [
  "Draft",
  "Invited",
  "Quoted",
  "Accepted",
  "Declined",
];

/** Only an accepted lane generates anything. */
export const laneIsLive = (s: LaneState) => s === "Accepted";

export interface ProgramTarget {
  id: string;
  customer: TwoLine;
  shipTo: string;
  city: string;
  state: string;
  /** The tanks at this site the programme fills, with what each takes. */
  lines: OrderLine[];
  /** This site's own window. You cannot be at thirty sites at eight o'clock. */
  window: { start: string; end: string };
  /** Preferred times inside the window, minutes from midnight (2026-10-20). */
  preferred?: { start: number; end: number }[];
  poc: string;
  instructions: string;
  poNumber: string;
  /** What the partner charges for THIS lane. Null until they have priced it. */
  vendorPrice: number | null;
  /** What this customer is billed. Their contract, not the programme's. */
  customerPrice: number | null;
  state_: LaneState;
  /**
   * COVERAGE IS NOT STATIC. A partner's area changes, they go inactive, their
   * compliance lapses — and a site that qualified when the programme was built
   * can stop qualifying. Quiet until the day it matters, which is why it is
   * stored rather than recomputed only at the picker.
   */
  serviceable: boolean;
  /**
   * DAYS THIS SHIP-TO SITS OUT (Pavan, 2026-10-01) — the resolution to a clash
   * with another rule at the same ship-to. Weekdays (0 = Sunday) for a Days
   * rule; dates of the month for a Date rule. The rule still runs everywhere
   * else on those days.
   */
  skip?: { weekdays: number[]; monthDays: number[] };
  /**
   * DRAFT ONLY — "stop the other rule here on these days" (Pavan,
   * 2026-10-01). Held on the draft and written onto that rule's ship-to when
   * this rule is created, so cancelling the form changes nothing.
   */
  othersSkip?: { programId: string; weekdays: number[]; monthDays: number[] }[];
}

/** Does this ship-to sit this day out? */
export const targetSkips = (t: ProgramTarget, day: Date) =>
  Boolean(
    t.skip &&
      (t.skip.weekdays.includes(day.getDay()) ||
        t.skip.monthDays.includes(day.getDate()))
  );

/* ---------------------------------------------------------------------------
 * The programme
 * ------------------------------------------------------------------------ */

export interface RecurringProgram {
  id: string;
  /** `P-2140`. Not an order number and not a rule number — its own series. */
  programNo: string;
  createdAt: string;

  /* ── who runs it ── */
  /**
   * BROKERAGE OR OUR OWN FLEET. On `Transportation` there is no partner and
   * no gate: we are the haulier, so reaching a site is our problem rather
   * than a constraint on which sites may be on the programme.
   */
  jobType: JobType;

  /* ── the gate, on brokerage only ── */
  /**
   * EVERY PARTNER THE RULE'S LANES GO OUT TO. Usually one; a rule put out to
   * several is offered to all of them, and the sites it can cover are the
   * union of their service areas rather than the overlap.
   */
  vendorIds: string[];

  /* ── where it loads. A broker's judgement, not a constraint. ── */
  loadOrder: boolean;
  /**
   * A ROW PER LOADING ACCOUNT. One number normally carries the whole load, so
   * a row holds as many of the rule's products as its account can take; a
   * second row exists only when something has to load somewhere else.
   */
  loadRows: {
    products: string[];
    terminal: string;
    supplier: string;
    loadingAccount: string;
  }[];

  /* ── what goes on the truck ── */
  /** One rule can carry several. The tanks offered per site follow these. */
  products: string[];
  /** Which of those products the rule delivers as a winter blend. */
  winterProducts: string[];
  serviceLine: ServiceLine;
  business: string | null;
  orderType: BrokerOrderType;
  signatureOnDelivery: boolean;

  /* ── when. CONSTITUTIVE — no target may override it. ── */
  schedule: Schedule;
  /** The form's own answer, kept so the rule can be reopened in the form. */
  frequency?: RuleFrequency;
  startKey: string;
  endKey: string | null;

  tags: string[];
  internalNote: string;

  targets: ProgramTarget[];
  status: SeriesStatus;
}

/** The partners on a programme, in the order they were picked. */
export const programVendors = (p: RecurringProgram) =>
  p.vendorIds
    .map((id) => VENDORS.find((v) => v.id === id))
    .filter((v): v is NonNullable<typeof v> => Boolean(v));

/**
 * ONE NAME AND A COUNT. A cell wide enough for three partner names is a cell
 * that fits nothing else, and the first one picked is the one a reader is
 * looking for.
 */
export function programPartnerLabel(p: RecurringProgram): string {
  const names = programVendors(p).map((v) => v.name);
  if (names.length === 0) return "No partner";
  return names.length === 1 ? names[0] : `${names[0]} +${names.length - 1}`;
}

/** Partner · product · frequency — a programme read without opening it. */
export function programTitle(p: RecurringProgram): string {
  return `${programPartnerLabel(p)} · ${p.products.join(" + ")} · ${p.schedule.label}`;
}

export const liveTargets = (p: RecurringProgram) =>
  p.targets.filter((t) => laneIsLive(t.state_) && t.serviceable);

export const waitingTargets = (p: RecurringProgram) =>
  p.targets.filter((t) => !laneIsLive(t.state_) || !t.serviceable);

/** What the whole programme costs and earns on ONE run of the live lanes. */
export function programMoney(p: RecurringProgram) {
  const live = liveTargets(p);
  const cost = live.reduce((s, t) => s + (t.vendorPrice ?? 0), 0);
  const revenue = live.reduce((s, t) => s + (t.customerPrice ?? 0), 0);
  return { cost, revenue, margin: revenue - cost };
}

/** Gallons per run across the live lanes. Top-offs contribute nothing. */
export function programGallons(p: RecurringProgram): number {
  return liveTargets(p).reduce(
    (s, t) => s + t.lines.reduce((a, l) => a + (l.topOff ? 0 : (l.gal ?? 0)), 0),
    0
  );
}

/**
 * ALREADY ON ANOTHER PROGRAMME FOR THE SAME PRODUCT.
 *
 * The collision that `frequency is constitutive` makes checkable: two
 * programmes covering one site with one product will send two trucks, and the
 * only moment anybody can be told cheaply is while they are adding the site.
 */
/**
 * A REAL CLASH (Pavan, 2026-10-01). Another rule at the same ship-to clashes
 * on a day both run when it fills ONE OF THE SAME ASSETS, or when its
 * delivery window OVERLAPS this one. The same product into a different tank
 * is not a clash — picking the asset already settles that. Looks 16 weeks
 * ahead from whichever starts later. One entry per clashing rule: the dates,
 * the assets both fill (with their product), whether the windows overlap, and
 * every date this rule runs in that window (so "every Tuesday" can be told
 * from "some Tuesdays").
 */
export interface Clash {
  program: RecurringProgram;
  dates: Date[];
  assets: { asset: string; product: string }[];
  window: { start: string; end: string } | null;
  mineDates: Date[];
}

const toMin = (label: string) => {
  const m = label.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
  if (!m) return null;
  let h = Number(m[1]) % 12;
  if (m[3].toUpperCase() === "PM") h += 12;
  return h * 60 + Number(m[2]);
};
const windowsOverlap = (
  a: { start: string; end: string },
  b: { start: string; end: string }
) => {
  const [a0, a1, b0, b1] = [a.start, a.end, b.start, b.end].map(toMin);
  if (a0 === null || a1 === null || b0 === null || b1 === null) return false;
  return a0 < b1 && b0 < a1;
};

export function clashesFor(
  shipTo: string,
  mine: {
    assets: string[];
    window: { start: string; end: string };
    schedule: Schedule;
    startKey: string;
    endKey: string | null;
    skip?: ProgramTarget["skip"];
  },
  exceptProgramId: string,
  all: RecurringProgram[]
): Clash[] {
  const out: Clash[] = [];
  for (const p of all) {
    if (p.id === exceptProgramId || p.status === "Canceled") continue;
    const theirs = p.targets.find((t) => t.shipTo === shipTo);
    if (!theirs) continue;
    const assets = theirs.lines
      .filter((l) => l.asset && mine.assets.includes(l.asset))
      .map((l) => ({ asset: l.asset, product: l.product }));
    const overlap = windowsOverlap(mine.window, theirs.window);
    if (assets.length === 0 && !overlap) continue;
    const from = [mine.startKey, p.startKey, dateKeyOf(startOfDay(new Date()))].sort()[2];
    const [y, m, d] = from.split("-").map(Number);
    const dates: Date[] = [];
    const mineDates: Date[] = [];
    for (let i = 0; i < 112; i++) {
      const day = new Date(y, m - 1, d + i);
      const key = dateKeyOf(day);
      if (mine.endKey && key > mine.endKey) break;
      if (!mine.schedule.hits(day)) continue;
      if (mine.skip && targetSkips({ skip: mine.skip } as ProgramTarget, day)) continue;
      mineDates.push(day);
      if (!programRunsOn(p, day) || targetSkips(theirs, day)) continue;
      dates.push(day);
    }
    if (dates.length)
      out.push({
        program: p,
        dates,
        assets,
        window: overlap ? theirs.window : null,
        mineDates,
      });
  }
  return out;
}

export function clashFor(
  shipTo: string,
  products: string[],
  exceptProgramId: string,
  all: RecurringProgram[]
): RecurringProgram | null {
  return (
    all.find(
      (p) =>
        p.id !== exceptProgramId &&
        p.products.some((x) => products.includes(x)) &&
        p.status !== "Canceled" &&
        p.targets.some((t) => t.shipTo === shipTo)
    ) ?? null
  );
}

/* ---------------------------------------------------------------------------
 * The seed
 * ------------------------------------------------------------------------ */

const WINDOWS = [
  { start: "6:00 AM", end: "10:00 AM" },
  { start: "8:00 AM", end: "12:00 PM" },
  { start: "10:00 AM", end: "2:00 PM" },
  { start: "1:00 PM", end: "5:00 PM" },
];

const POCS = [
  "Ray Obuya",
  "Colleen Marsh",
  "Marisol Vega",
  "Dwight Feeney",
  "Anita Kaur",
  "Tom Alvarez",
];

const INSTRUCTIONS = [
  "Gate code 4471. Call ahead.",
  "Deliver to the rear tank only.",
  "Yard closes at 4pm sharp.",
  "",
  "Weighbridge on the left as you enter.",
  "",
];

/** Which frequencies a programme may run on — no `Custom`, it has no meaning
 *  across a book of sites. */
const PROGRAM_FREQUENCIES = [
  "Weekly On Tuesday",
  "Every Weekday (Monday To Friday)",
  "Monthly On First Thursday",
  "Weekly On Thursday",
];

const PROGRAM_PRODUCTS = [
  "Clear Diesel #2",
  "Dyed Diesel",
  "Unleaded 87",
  "Engine Oil 15W-40",
];

/** Deterministic pseudo-random, so the fixture is the same every load. */
function rng(seed: number) {
  let s = seed;
  return () => {
    s = (s * 1664525 + 1013904223) % 4294967296;
    return s / 4294967296;
  };
}

export const RECURRING_PROGRAMS: RecurringProgram[] = (() => {
  const pick = rng(20260921);
  const today = startOfDay(new Date());
  const todayKey = dateKeyOf(today);
  const out: RecurringProgram[] = [];

  /* Only partners who can actually reach somewhere. A programme built on a
     partner with no reachable site would be a screen demonstrating nothing. */
  const usable = VENDORS.filter(
    (v) => v.active && v.approvedForAssignment && reachableTargets(v).length >= 4
  ).slice(0, 7);

  usable.forEach((v, i) => {
    const product = PROGRAM_PRODUCTS[i % PROGRAM_PRODUCTS.length];
    const account =
      LOADING_ACCOUNTS.find((a) => a.products.includes(product)) ??
      LOADING_ACCOUNTS[0];
    const raw = PROGRAM_FREQUENCIES[i % PROGRAM_FREQUENCIES.length];
    /* TWO OF THE BOOK CARRY A SECOND PRODUCT off the same account — a rule
       can, and the list has to show it (Pavan, 2026-10-01). */
    const products = [
      product,
      ...(i === 1 || i === 2
        ? account.products.filter((x) => x !== product).slice(0, 1)
        : []),
    ];

    /* THE START IS IN THE PAST FOR MOST — a programme nobody has run yet
       teaches nothing about a screen whose whole job is showing a book of
       work in flight. */
    const start = new Date(today);
    start.setDate(start.getDate() - (i % 3) * 21);
    const startKey = dateKeyOf(start);
    const schedule = parseSchedule(raw, startKey);

    const reach = reachableTargets(v);
    /* Between three and seven sites, AND NEVER ALL OF THEM. A programme that
       has already consumed every site its partner can reach makes Add ship-to
       permanently empty — which hides the one thing this version exists to
       show. Two lanes of headroom is what makes the gate demonstrable. */
    const count = Math.max(
      2,
      Math.min(reach.length - 1, 3 + Math.floor(pick() * 4))
    );

    const targets: ProgramTarget[] = reach.slice(0, count).map((r, k) => {
      /* The tanks AT that site that take this product. A site with none is
         still a legitimate target — it takes the product into a bulk tank —
         so it falls back to one unnamed line rather than being dropped. */
      const tanks = r.site.assets.filter((a) => a.product === product);
      const lines: OrderLine[] =
        tanks.length > 0
          ? tanks.slice(0, 2).map((a, n) => ({
              asset: a.name,
              product,
              /* TOP-OFF IS THE PORTABLE QUANTITY. "Fill it" travels across a
                 book of sites; a number belongs to one tank. Most lanes top
                 off; some name a figure. */
              gal: n === 0 && k % 3 === 0 ? 500 + ((k * 137) % 900) : null,
              topOff: !(n === 0 && k % 3 === 0),
              rental: a.rental,
              charges: defaultLineCharges(),
            }))
          : [
              {
                asset: "Bulk tank",
                product,
                gal: null,
                topOff: true,
                charges: defaultLineCharges(),
              },
            ];

      /* ACCEPTANCE IS A MATRIX. Most lanes are away; a few are still being
         argued over and one has said no — which is the partly-live state the
         version exists to show. */
      const laneState: LaneState =
        k % 7 === 5
          ? "Declined"
          : k % 5 === 3
            ? "Quoted"
            : k % 5 === 4
              ? "Invited"
              : "Accepted";

      const gal = lines.reduce((s, l) => s + (l.gal ?? 900), 0);
      const priced = laneState === "Accepted" || laneState === "Quoted";

      return {
        id: `${v.id}-t${k}`,
        customer: r.customer,
        shipTo: r.shipTo,
        city: r.site.city,
        state: r.site.state,
        lines,
        window: WINDOWS[(i + k) % WINDOWS.length],
        poc: POCS[(i + k) % POCS.length],
        instructions: INSTRUCTIONS[(i + k) % INSTRUCTIONS.length],
        poNumber: k % 4 === 0 ? `PO-${81_000 + i * 40 + k}` : "",
        vendorPrice: priced ? Number((gal * (0.29 + pick() * 0.1)).toFixed(2)) : null,
        customerPrice: priced ? Number((gal * (0.38 + pick() * 0.1)).toFixed(2)) : null,
        state_: laneState,
        /* One site in the book has fallen out of the partner's area since the
           programme was built. It is the case nobody designs for. */
        serviceable: !(i === 1 && k === 2),
      };
    });

    out.push({
      id: `prog-${i}`,
      programNo: `P-${2140 + i * 7}`,
      createdAt: new Date(
        start.getTime() - (3 + i) * 86_400_000
      ).toISOString(),
      jobType: "Brokerage",
      vendorIds: [v.id],
      loadOrder: i % 3 !== 2,
      loadRows:
        i % 3 !== 2
          ? [
              {
                products,
                terminal: account.terminal,
                supplier: account.supplier,
                loadingAccount: account.name,
              },
            ]
          : [],
      products,
      winterProducts: product.includes("Diesel") && i % 4 === 0 ? [product] : [],
      serviceLine:
        product === "Engine Oil 15W-40" ? "Lubricants" : "Fuel",
      business:
        product === "Engine Oil 15W-40" ? "Packaged Goods" : "Transport",
      orderType: "Core",
      signatureOnDelivery: i % 2 === 0,
      schedule,
      startKey,
      endKey: null,
      tags: i % 3 === 0 ? ["Contracted"] : [],
      internalNote: "",
      status: startKey > todayKey ? "Upcoming" : i === 4 ? "Paused" : "Active",
      targets,
    });
  });

  return out;
})();

/** Free-text across everything a programme is findable by. */
export function matchesProgram(p: RecurringProgram, q: string): boolean {
  const needle = q.trim().toLowerCase();
  if (!needle) return true;
  return [
    p.programNo,
    programTitle(p),
    ...p.loadRows.map((l) => `${l.terminal} ${l.supplier} ${l.loadingAccount}`),
    ...p.targets.map((t) => `${t.customer.title} ${t.shipTo} ${t.city}`),
  ]
    .join(" ")
    .toLowerCase()
    .includes(needle);
}

/** The next few dates this programme will cut orders on. */
export function nextDates(p: RecurringProgram, n = 5): string[] {
  const today = startOfDay(new Date());
  const out: string[] = [];
  const d = new Date(today);
  for (let i = 0; i < 400 && out.length < n; i++) {
    if (p.schedule.hits(d) && dateKeyOf(d) >= p.startKey) out.push(dateKeyOf(d));
    d.setDate(d.getDate() + 1);
  }
  return out;
}

export const fmtKey = (key: string) =>
  DATE_FMT.format(new Date(`${key}T00:00:00`));

/** One money format across the programme screens. */
/** Re-exported so the programme screens keep one import. One helper, app-wide. */
export { MONEY } from "../data";

/* ---------------------------------------------------------------------------
 * ONE LIST OF RULES, SHARED (Pavan, 2026-09-24). The rules screen edits it and
 * Delivery Orders reads it to cut orders, so it lives here rather than in
 * either screen's state — a rule made on one has to be seen by the other.
 * ------------------------------------------------------------------------ */

let programStore: RecurringProgram[] = RECURRING_PROGRAMS;
const programListeners = new Set<() => void>();

export function setPrograms(
  next: RecurringProgram[] | ((prev: RecurringProgram[]) => RecurringProgram[])
) {
  programStore = typeof next === "function" ? next(programStore) : next;
  programListeners.forEach((l) => l());
}

export function usePrograms(): [RecurringProgram[], typeof setPrograms] {
  const list = React.useSyncExternalStore(
    (l) => {
      programListeners.add(l);
      return () => programListeners.delete(l);
    },
    () => programStore
  );
  return [list, setPrograms];
}

/** Stopped rules cut nothing. Upcoming starts cutting on its start date. */
const RUNNING: SeriesStatus[] = ["Upcoming", "Active"];

/** Does this rule cut orders on this day? */
export function programRunsOn(p: RecurringProgram, day: Date): boolean {
  const key = dateKeyOf(day);
  return (
    RUNNING.includes(p.status) &&
    key >= p.startKey &&
    (p.endKey === null || key <= p.endKey) &&
    p.schedule.hits(day)
  );
}

/* THE SHIP-TOS THAT GET AN ORDER are `liveTargets` above — a rule can be
   partly live (decision 4, 2026-09-21). */

import type { Asset } from "../../customer-portal/orders";

/*
  TANK MONITORS ON 3PL SITE ASSETS (Pavan, 2026-10-20) — the readings the
  portal's tanks carry (level, battery, daily use), so a 3PL Delivery Order
  shows the same tank columns and suggests the same quantity. INVENTED and
  deterministic: seeded from the site and asset name, so a tank reads the
  same every time. Most tanks wear a monitor; a few don't, and show dashes.
*/

const hash = (s: string) => {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
};
const rng = (seed: number) => () => {
  seed = (seed + 0x6d2b79f5) >>> 0;
  let t = seed;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};

/** A tank's size from its name — "LP Tank 500" is 500 gal; a tote, a skid, a rack by kind. */
function capacityOf(name: string, r: () => number): number {
  const n = /(\d{3,5})\s*$/.exec(name);
  if (/LP|Propane/i.test(name) && n) return Number(n[1]);
  if (/Tote/i.test(name)) return 330;
  if (/Skid/i.test(name)) return 120;
  if (/Drum|Rack/i.test(name)) return 220;
  return [500, 1000, 1000, 2000, 3000][Math.floor(r() * 5)];
}

const cache = new Map<string, Asset>();

/** The tank at a ship-to, with its monitor's last reading. */
export function siteTank(shipTo: string, assetName: string, product: string, rental = false): Asset {
  const key = `${shipTo}::${assetName}`;
  const hit = cache.get(key);
  if (hit) return { ...hit, product, products: [product] };
  const r = rng(hash(key));
  const capacity = capacityOf(assetName, r);
  const monitor = r() < 0.9;
  const tank: Asset = {
    id: `3pl:${key}`,
    name: assetName,
    code: "",
    rfid: "",
    erpId: "",
    type: "Tank",
    categories: [],
    products: [product],
    product,
    capacity,
    rented: rental,
    monitor,
    monitorId: monitor ? `TM-${(hash(key) % 90000) + 10000}` : "",
    level: monitor ? Math.round(5 + r() * 90) : 0,
    battery: monitor ? Math.round(5 + r() * 95) : 0,
    dailyUse: monitor ? Math.max(1, Math.round(capacity * (0.02 + r() * 0.06))) : 0,
    lat: null,
    lng: null,
    status: "Active",
    notes: "",
  };
  cache.set(key, tank);
  return tank;
}

/*
  3PL vendors — the carriers a broker dispatches to.

  PROVENANCE. The vendor ATTRIBUTES the ORDER FLOW uses are the ones the source
  spec names as filters on the vendor picker: Business Lines, Safety Score
  Range, Distance Range (`3PL - 102` §5 "Table View"), plus the per-vendor Email
  Status toggle from §6 "Vendors Page". Everything past that is what a vendor
  RECORD needs to exist as a record — dispatch contacts, coverage, rate card,
  compliance documents, accounting details. The VALUES are invented; no vendor
  list was ever captured. Nothing here is presented as real.

  ELIGIBILITY IS THE POINT OF THIS FILE. Everything else on a vendor is
  reference; the coverage, capability, compliance and availability fields exist
  so that `vendorBlockedReason` can answer, in one sentence somebody can act on,
  why this carrier is not on the picker for this order.
*/
import {
  PLACES,
  STAFF,
  STATE_NAMES,
  VENDOR_TAGS,
  dateOffset,
  domainFor,
  emailFor,
  intBetween,
  maybe,
  personName,
  phoneNumber,
  pickFrom,
  rng,
  seedAttachments,
  seedAudit,
  shiftDays,
  someOf,
  streetAddress,
  TODAY,
  type Attachment,
  type AuditEvent,
  type DirectoryContact,
  type RecordStatus,
} from "./directoryCore";

/** The service lines a vendor runs. Filter facet on the picker. */
export const BUSINESS_LINES = [
  "Bulk Fuel",
  "Packaged Lubes",
  "DEF",
  "Asset Movement",
  "Emergency Response",
] as const;

export type BusinessLine = (typeof BUSINESS_LINES)[number];

export const VENDOR_TYPES = [
  "Carrier", "Jobber", "Owner-Operator", "Terminal", "Service Contractor",
] as const;

export const SERVICE_AREA_TYPES = ["zip", "radius", "state", "custom"] as const;
export type ServiceAreaType = (typeof SERVICE_AREA_TYPES)[number];

export const COMPLIANCE_STATUSES = ["Valid", "Expiring", "Expired", "Missing"] as const;
export type ComplianceStatus = (typeof COMPLIANCE_STATUSES)[number];

export const AVAILABILITY_STATUSES = ["Available", "Limited", "Unavailable"] as const;
export type AvailabilityStatus = (typeof AVAILABILITY_STATUSES)[number];

/** One tier of a vendor's rate card. What a quote is checked against. */
export interface RateCardLine {
  id: string;
  label: string;
  /** Dollars per gallon, or a flat fee where `unit` says so. */
  rate: number;
  unit: "per gal" | "flat" | "per mile" | "per hour";
  /** Only over this many gallons. Null for the base tier. */
  minGallons: number | null;
  fuelSurcharge: number | null;
}

export interface Vendor {
  id: string;
  name: string;
  erpVendorId: string | null;
  legalBusinessName: string | null;
  dbaName: string | null;
  taxId: string | null;
  status: RecordStatus;
  vendorType: string;

  /* ── people ── */
  mainContactName: string | null;
  dispatchContactName: string | null;
  accountingContactName: string | null;
  escalationContactName: string | null;
  phone: string | null;
  dispatchPhone: string | null;
  email: string | null;
  dispatchEmail: string | null;
  accountingEmail: string | null;
  contacts: DirectoryContact[];

  /* ── where they are ── */
  addressLine1: string | null;
  addressLine2: string | null;
  city: string | null;
  state: string | null;
  zip: string | null;
  country: string;
  /** `City, ST` — kept because the order sheet prints it inline. */
  base: string;

  /* ── where they go ── */
  serviceAreaType: ServiceAreaType;
  /** Full state names. An order ships to exactly one. */
  serviceStates: string[];
  coveredCities: string[];
  coveredZips: string[];
  maxRadiusMiles: number | null;

  /* ── what they can do ── */
  businessLines: BusinessLine[];
  supportedProductIds: string[];
  supportedOrderTypes: string[];
  topOffCapable: boolean;
  assetHandlingCapable: boolean;
  afterHoursCapable: boolean;

  /* ── whether they may ── */
  complianceStatus: ComplianceStatus;
  /** Insurance and authority, as `YYYY-MM-DD`. Past this, no new assignments. */
  complianceValidTo: string;
  insuranceExpiry: string | null;
  licenseNumbers: string[];
  documents: Attachment[];
  /** A human decision, separate from whether the paperwork is current. */
  approvedForAssignment: boolean;
  /** Deactivated vendors keep their history and take no new work. */
  active: boolean;

  /* ── money ── */
  defaultRateCardId: string | null;
  rateCard: RateCardLine[];
  minimumCharge: number | null;
  paymentTerms: string;
  accountingVendorId: string | null;

  /* ── when ── */
  availabilityStatus: AvailabilityStatus;
  blackoutDates: string[];
  assignmentPriority: number;
  preferredCustomerIds: string[];

  /* ── operational reference ── */
  /** 0–100. The spec filters on a range, so it is a number, not a grade. */
  safetyScore: number;
  /** Miles from the ship-to. Derived per order in the real app; fixed here. */
  distanceMi: number;
  /** §6: emails can be disabled per vendor, individually or in bulk. */
  emailsEnabled: boolean;
  /** Has an account on the vendor app. Optional per the vendor flow — a vendor
   *  can acknowledge from the emailed public link with no login at all. */
  hasAccount: boolean;
  vendorInstruction: string | null;

  /* ── record ── */
  tags: string[];
  notes: string | null;
  attachments: Attachment[];
  audit: AuditEvent[];
  createdAt: string;
  updatedAt: string;
}

/* The eight the order flow points at, with the facts that are load-bearing
   there — Sierra is deactivated, Delta's compliance lapses in June. */
interface VendorSeed {
  name: string;
  base: string;
  businessLines: BusinessLine[];
  safetyScore: number;
  distanceMi: number;
  emailsEnabled: boolean;
  hasAccount: boolean;
  active: boolean;
  serviceStates: string[];
  complianceValidTo: string;
}

const CORE_VENDORS: VendorSeed[] = [
  { name: "Redline Carriers", base: "Fresno, CA", businessLines: ["Bulk Fuel", "DEF"], safetyScore: 94, distanceMi: 12, emailsEnabled: true, hasAccount: true, active: true, serviceStates: ["California", "Arizona"], complianceValidTo: "2027-01-15" },
  { name: "Sierra Bulk Transport", base: "Bakersfield, CA", businessLines: ["Bulk Fuel", "Emergency Response"], safetyScore: 88, distanceMi: 24, emailsEnabled: true, hasAccount: true, active: false, serviceStates: ["California"], complianceValidTo: "2026-11-30" },
  { name: "Delta Fuel Logistics", base: "Stockton, CA", businessLines: ["Bulk Fuel", "Packaged Lubes"], safetyScore: 91, distanceMi: 31, emailsEnabled: true, hasAccount: false, active: true, serviceStates: ["California"], complianceValidTo: "2026-06-30" },
  { name: "Kern Valley Hauling", base: "Delano, CA", businessLines: ["Bulk Fuel", "Asset Movement"], safetyScore: 76, distanceMi: 41, emailsEnabled: false, hasAccount: true, active: true, serviceStates: ["California", "Oregon", "Nevada"], complianceValidTo: "2027-09-01" },
  { name: "Pacific Tank Movers", base: "Modesto, CA", businessLines: ["Asset Movement"], safetyScore: 82, distanceMi: 55, emailsEnabled: true, hasAccount: true, active: true, serviceStates: ["California", "Texas"], complianceValidTo: "2027-03-20" },
  { name: "Golden State Petro", base: "Sacramento, CA", businessLines: ["Bulk Fuel", "DEF", "Packaged Lubes"], safetyScore: 97, distanceMi: 68, emailsEnabled: true, hasAccount: true, active: true, serviceStates: ["California"], complianceValidTo: "2027-07-11" },
  { name: "Foothill Fuel Service", base: "Visalia, CA", businessLines: ["Bulk Fuel"], safetyScore: 69, distanceMi: 19, emailsEnabled: true, hasAccount: false, active: true, serviceStates: ["California", "Oregon"], complianceValidTo: "2027-02-28" },
  { name: "Central Coast Energy", base: "Salinas, CA", businessLines: ["Bulk Fuel", "Emergency Response"], safetyScore: 85, distanceMi: 77, emailsEnabled: true, hasAccount: true, active: true, serviceStates: ["California"], complianceValidTo: "2027-05-22" },
];

const VENDOR_HEADS = [
  "Redline", "Sierra", "Delta", "Kern Valley", "Pacific", "Golden State",
  "Foothill", "Central Coast", "Ironwood", "Blue Mesa", "Cascade", "Rimrock",
  "Saguaro", "High Desert", "Copper Ridge", "Frontier", "Trailhead", "Stonegate",
  "Windward", "Silverline", "Cornerstone", "Basin", "Overland", "Ridgeline",
  "Northstar", "Sunfield", "Talon", "Junction", "Cypress", "Beacon",
] as const;

const VENDOR_TAILS = [
  "Carriers", "Bulk Transport", "Fuel Logistics", "Hauling", "Tank Movers",
  "Petro", "Fuel Service", "Energy", "Transport", "Distribution", "Tanklines",
  "Freight", "Petroleum", "Fuels", "Dispatch",
] as const;

const VENDOR_INSTRUCTIONS = [
  "Send the BOL within 2 hours of delivery or the invoice is held.",
  "Dispatch answers the shared line, not the mobile, before 6am.",
  "Confirm every load by email — they do not use the portal.",
  "Ask for the same driver on the university sites; he is badged.",
  "Quote includes the fuel surcharge. Do not add it twice.",
] as const;

function makeVendor(spec: VendorSeed & { seed: number; id: string; index: number }): Vendor {
  const r = rng(spec.seed);
  const [city, st] = spec.base.split(", ");
  const place = PLACES.find((p) => p.city === city) ?? pickFrom(r, PLACES);
  const domain = domainFor(spec.name);
  const dispatchName = personName(r);
  const mainName = personName(r);
  const accountingName = personName(r);

  const daysToCompliance = Math.round(
    (new Date(`${spec.complianceValidTo}T00:00:00Z`).getTime() - TODAY.getTime()) / 86_400_000
  );
  /* COMPLIANCE STATUS IS DERIVED, never stored independently. A vendor whose
     certificate expired last month and whose status still says Valid is the
     exact failure this directory exists to prevent. */
  const complianceStatus: ComplianceStatus =
    daysToCompliance < 0 ? "Expired" : daysToCompliance < 60 ? "Expiring" : "Valid";

  const tiers: RateCardLine[] = [
    { id: `${spec.id}-rc-1`, label: "Base haul", rate: Number((0.18 + r() * 0.22).toFixed(3)), unit: "per gal", minGallons: null, fuelSurcharge: Number((0.02 + r() * 0.05).toFixed(3)) },
    { id: `${spec.id}-rc-2`, label: "Volume 2,500 gal+", rate: Number((0.12 + r() * 0.14).toFixed(3)), unit: "per gal", minGallons: 2500, fuelSurcharge: Number((0.02 + r() * 0.04).toFixed(3)) },
  ];
  if (spec.businessLines.includes("Asset Movement")) {
    tiers.push({ id: `${spec.id}-rc-3`, label: "Asset move", rate: intBetween(r, 180, 480), unit: "flat", minGallons: null, fuelSurcharge: null });
  }
  if (spec.businessLines.includes("Emergency Response")) {
    tiers.push({ id: `${spec.id}-rc-4`, label: "After-hours callout", rate: intBetween(r, 110, 260), unit: "per hour", minGallons: null, fuelSurcharge: null });
  }

  const contactRows: DirectoryContact[] = [
    { id: `${spec.id}-ct-1`, name: dispatchName, role: "Dispatch", phone: phoneNumber(r), email: emailFor(dispatchName, domain), isPrimary: true, notes: maybe(r, 0.25, "Best reached on the dispatch line before 5am.") },
    { id: `${spec.id}-ct-2`, name: mainName, role: "Account Manager", phone: maybe(r, 0.8, phoneNumber(r)), email: maybe(r, 0.85, emailFor(mainName, domain)), isPrimary: false, notes: null },
    { id: `${spec.id}-ct-3`, name: accountingName, role: "Accounts Receivable", phone: maybe(r, 0.5, phoneNumber(r)), email: maybe(r, 0.9, `ar@${domain}`), isPrimary: false, notes: null },
  ].slice(0, intBetween(r, 1, 3));

  const createdAt = new Date(shiftDays(TODAY, -intBetween(r, 120, 1700)).setUTCHours(11)).toISOString();
  const updatedAt = new Date(shiftDays(TODAY, -intBetween(r, 0, 70)).setUTCHours(16)).toISOString();

  const v: Vendor = {
    id: spec.id,
    name: spec.name,
    erpVendorId: maybe(r, 0.8, `VEND-${3000 + spec.index}`),
    legalBusinessName: maybe(r, 0.7, `${spec.name} LLC`),
    dbaName: maybe(r, 0.25, spec.name.split(" ")[0]),
    taxId: maybe(r, 0.6, `${intBetween(r, 10, 99)}-${intBetween(r, 1000000, 9999999)}`),
    status: spec.active ? "active" : "inactive",
    vendorType: pickFrom(r, VENDOR_TYPES),

    mainContactName: mainName,
    dispatchContactName: dispatchName,
    accountingContactName: maybe(r, 0.7, accountingName),
    escalationContactName: maybe(r, 0.4, personName(r)),
    phone: phoneNumber(r),
    dispatchPhone: phoneNumber(r),
    email: maybe(r, 0.85, `info@${domain}`),
    dispatchEmail: `dispatch@${domain}`,
    accountingEmail: maybe(r, 0.75, `ap@${domain}`),
    contacts: contactRows,

    addressLine1: streetAddress(r),
    addressLine2: maybe(r, 0.15, `Dock ${intBetween(r, 1, 24)}`),
    city,
    state: st,
    zip: place.zip,
    country: "USA",
    base: spec.base,

    serviceAreaType: pickFrom(r, SERVICE_AREA_TYPES),
    serviceStates: spec.serviceStates,
    coveredCities: someOf(r, PLACES.filter((p) => spec.serviceStates.includes(STATE_NAMES[p.state] ?? "")).map((p) => p.city), 5),
    coveredZips: r() < 0.3 ? someOf(r, PLACES.map((p) => p.zip), 4) : [],
    maxRadiusMiles: maybe(r, 0.5, intBetween(r, 3, 30) * 25),

    businessLines: spec.businessLines,
    supportedProductIds: [],
    supportedOrderTypes: someOf(r, ["Delivery", "Core", "Emergency", "Transport", "Asset Movement", "Pump Out"] as const, 4),
    topOffCapable: r() < 0.62,
    assetHandlingCapable: spec.businessLines.includes("Asset Movement") || r() < 0.2,
    afterHoursCapable: spec.businessLines.includes("Emergency Response") || r() < 0.35,

    complianceStatus,
    complianceValidTo: spec.complianceValidTo,
    insuranceExpiry: maybe(r, 0.9, spec.complianceValidTo),
    licenseNumbers: someOf(r, [`MC-${intBetween(r, 100000, 999999)}`, `DOT-${intBetween(r, 1000000, 3999999)}`, `HM-${intBetween(r, 10000, 99999)}`], 2),
    documents: seedAttachments(r, [
      "Certificate of Insurance.pdf", "W-9.pdf", "Operating Authority.pdf",
      "Hazmat Endorsement.pdf", "Signed Carrier Agreement.pdf", "Safety Rating Letter.pdf",
    ], 4),
    approvedForAssignment: spec.active && r() < 0.88,
    active: spec.active,

    defaultRateCardId: tiers[0]?.id ?? null,
    rateCard: tiers,
    minimumCharge: maybe(r, 0.65, intBetween(r, 3, 20) * 25),
    paymentTerms: pickFrom(r, ["Net 15", "Net 30", "Net 45", "Quick pay 2/10"] as const),
    accountingVendorId: maybe(r, 0.7, `NS-V-${intBetween(r, 1000, 9999)}`),

    availabilityStatus: spec.active
      ? pickFrom(r, ["Available", "Available", "Available", "Limited", "Unavailable"] as const)
      : "Unavailable",
    /* Blackouts are the reason an eligible vendor is still not offered on a
       given date, so a slice of the list has to actually have some. */
    blackoutDates: r() < 0.28
      ? Array.from({ length: intBetween(r, 1, 4) }, () => dateOffset(intBetween(r, -10, 120)))
      : [],
    assignmentPriority: intBetween(r, 1, 5),
    preferredCustomerIds: [],

    safetyScore: spec.safetyScore,
    distanceMi: spec.distanceMi,
    emailsEnabled: spec.emailsEnabled,
    hasAccount: spec.hasAccount,
    vendorInstruction: maybe(r, 0.45, pickFrom(r, VENDOR_INSTRUCTIONS)),

    tags: r() < 0.65 ? someOf(r, VENDOR_TAGS, 3) : [],
    notes: maybe(r, 0.3, "Reliable on short notice. Rates reviewed each January."),
    attachments: seedAttachments(r, ["Rate Card 2026.xlsx", "Coverage Map.png", "Meeting Notes.pdf"], 2),
    audit: [],
    createdAt,
    updatedAt,
  };

  v.audit = seedAudit(r, {
    createdAt,
    updatedAt,
    noun: "Vendor",
    fields: [
      "Compliance status", "Insurance expiry", "Rate card", "Service states",
      "Dispatch email", "Assignment approval", "Availability", "Business lines",
    ],
  });
  return v;
}

function buildVendors(): Vendor[] {
  const out: Vendor[] = CORE_VENDORS.map((v, i) =>
    makeVendor({ ...v, seed: 11_000 + i, id: `vd-${i + 1}`, index: i })
  );

  let i = 0;
  while (out.length < 80) {
    const r = rng(12_000 + i);
    const name = `${pickFrom(r, VENDOR_HEADS)} ${pickFrom(r, VENDOR_TAILS)}`;
    if (!out.some((v) => v.name === name)) {
      const place = pickFrom(r, PLACES);
      const states = someOf(
        r,
        Object.values(STATE_NAMES),
        3
      );
      /* The vendor's own state is always covered — a carrier that does not
         serve the state it is based in is a data bug, not a business case. */
      const home = STATE_NAMES[place.state];
      if (home && !states.includes(home)) states.unshift(home);

      out.push(
        makeVendor({
          seed: 12_000 + i,
          id: `vd-${out.length + 1}`,
          index: out.length,
          name,
          base: `${place.city}, ${place.state}`,
          businessLines: someOf(r, BUSINESS_LINES, 3),
          safetyScore: intBetween(r, 58, 99),
          distanceMi: intBetween(r, 4, 180),
          emailsEnabled: r() < 0.85,
          hasAccount: r() < 0.6,
          active: r() < 0.88,
          serviceStates: states,
          /* A quarter of the list is out of date on purpose: "has overdue
             docs" is a filter, and a filter with no matches is untestable. */
          complianceValidTo: dateOffset(r() < 0.25 ? -intBetween(r, 5, 400) : intBetween(r, 20, 900)),
        })
      );
    }
    i += 1;
    if (i > 600) break;
  }
  return out;
}

export const VENDORS: Vendor[] = buildVendors();

export const vendorById = (id: string | null) =>
  id ? (VENDORS.find((v) => v.id === id) ?? null) : null;

export const vendorName = (id: string | null) => vendorById(id)?.name ?? "—";

/** The other direction, for a control whose value is the name on screen. */
export const vendorByName = (name: string) =>
  VENDORS.find((v) => v.name === name);

/**
 * WHY A VENDOR CANNOT TAKE THIS ORDER — the reason, or null when it can.
 *
 * A REASON, NOT A BOOLEAN. "Not offered" is the answer people escalate;
 * "compliance expired 30 Jun 2026" is the answer they act on, and it is the
 * same sentence whether it is read by the person picking or by the person they
 * ring afterwards. The rules are checked in the order they can be fixed in:
 * a deactivated vendor is somebody's decision, an expired document is a task,
 * geography and capability are facts about the vendor, and a blackout is a
 * fact about the DAY rather than about the vendor at all.
 */
export function vendorBlockedReason(
  v: Vendor,
  order: { businessLine: BusinessLine; state: string; on: Date }
): string | null {
  if (!v.active) return "Deactivated";
  if (!v.approvedForAssignment) return "Not approved for assignment";
  const [y, m, d] = v.complianceValidTo.split("-").map(Number);
  if (new Date(y, m - 1, d) < order.on) {
    return `Compliance expired ${v.complianceValidTo}`;
  }
  if (!v.businessLines.some((b) => b === order.businessLine)) {
    return `Does not run ${order.businessLine}`;
  }
  if (!v.serviceStates.includes(order.state)) {
    return `Does not serve ${order.state}`;
  }
  if (v.availabilityStatus === "Unavailable") return "Marked unavailable";
  const iso = order.on.toISOString().slice(0, 10);
  if (v.blackoutDates.includes(iso)) return `Blacked out on ${iso}`;
  return null;
}

/** Docs that have lapsed, or lapse inside 60 days — the "overdue docs" filter. */
export const hasOverdueDocs = (v: Vendor): boolean =>
  v.complianceStatus === "Expired" || v.complianceStatus === "Expiring";

/* ────────────────────────────────────────────────────────────── list view ──
   NOTHING HERE SUMS. A vendor has a safety score and a distance, and both are
   properties of one vendor rather than quantities that add up — an average
   safety score across a group would be a different statistic wearing the same
   place as a total, and a summed distance is meaningless. So the list passes no
   `measureOf`, and its group headers carry a count alone. */

export type VendorColumnKey =
  | "name"
  | "dispatch"
  | "lines"
  | "erpId"
  | "address"
  | "serviceArea"
  | "products"
  | "status"
  | "rateCard"
  | "assigned"
  | "instruction"
  | "actions";

export interface VendorColumnDef {
  key: VendorColumnKey;
  label: string;
  width: number;
  sortable?: boolean;
  align?: "right" | "center";
}

/*
  TWELVE COLUMNS, DOWN FROM TWENTY — and the cut is by a rule, not by taste.

  A VENDOR LIST EXISTS TO ANSWER ONE QUESTION: who can take this work. So a
  column earns its place if it feeds that answer. The eligibility inputs are
  active status, compliance, business lines, service area, supported products —
  those stay. Everything else was reference, and reference belongs in the
  record, which is one click away and has room for it.

  WHAT LEFT THE TABLE, and why:
    · Safety Score, Distance  — ranking inputs at ASSIGNMENT time, not
      directory-browsing facts. Distance especially: it is miles from a
      SHIP-TO, and a directory has no ship-to, so the number here is a
      placeholder pretending to be a measurement. Both remain FILTERS — a
      facet does not need a column to work.
    · Emails on/off, Vendor App  — per-vendor comms config. Real, rarely
      looked at, and never the reason somebody opens this list.
    · City, State  — folded into Address, as on Customers.
    · Compliance  — folded under the vendor's name, where the name is.
    · Dispatch Phone + Email  — one column, two lines.
*/
/*
  THE ORDER IS THE ONE THE READER ARRANGED, adopted as the default rather than
  argued with. Identity first, then the number that says how busy they are,
  then how to reach them, then what they can do, then where, then the
  commercial terms.

  Load is third on purpose. Once a shortlist is eligible, "how much work are
  they already carrying" is the next question, and it was ninth.
*/
export const VENDOR_COLUMNS: VendorColumnDef[] = [
  { key: "name", label: "Vendor Name", width: 220, sortable: true },
  { key: "erpId", label: "Vendor ID", width: 110, sortable: true },
  /* CENTRED, not right-aligned. These are 1-2 digit counts that get READ, not
     compared down the column — at 150px a right edge sits so far from a
     15px header that it reads as a mistake. `tabular-nums` stays, so the
     digits still line up with each other. Money and long figures keep
     `right`, where lining up the units is the whole point. */
  { key: "assigned", label: "Assigned Orders", width: 140, sortable: true },
  { key: "dispatch", label: "Dispatch", width: 250, sortable: true },
  { key: "lines", label: "Business Lines", width: 210, sortable: true },
  { key: "address", label: "Address", width: 160, sortable: true },
  { key: "serviceArea", label: "Service Area", width: 150, sortable: true },
  { key: "products", label: "Supported Products", width: 270, sortable: true },
  { key: "status", label: "Status", width: 100, sortable: true },
  { key: "rateCard", label: "Default Rate Card", width: 150, sortable: true },
  { key: "instruction", label: "Notes", width: 80, sortable: true },
  { key: "actions", label: "", width: 44 },
];

export const VENDOR_SEARCH_FIELDS = [
  { key: "name", label: "Vendor", text: (v: Vendor) => `${v.name} ${v.legalBusinessName ?? ""}` },
  { key: "contact", label: "Contact", text: (v: Vendor) => `${v.dispatchContactName ?? ""} ${v.mainContactName ?? ""} ${v.dispatchEmail ?? ""} ${v.dispatchPhone ?? ""}` },
  { key: "city", label: "City", text: (v: Vendor) => v.city ?? "" },
  { key: "state", label: "State", text: (v: Vendor) => `${v.state ?? ""} ${v.serviceStates.join(" ")}` },
  { key: "lines", label: "Business Lines", text: (v: Vendor) => v.businessLines.join(" ") },
];

/** Free-text across everything a vendor is findable by. */
export function matchesVendor(v: Vendor, q: string): boolean {
  return `${v.name} ${v.base} ${v.businessLines.join(" ")} ${v.dispatchContactName ?? ""} ${v.dispatchEmail ?? ""} ${v.serviceStates.join(" ")} ${v.erpVendorId ?? ""}`
    .toLowerCase()
    .includes(q);
}

export function matchesVendorIn(v: Vendor, q: string, scope: string): boolean {
  const f = VENDOR_SEARCH_FIELDS.find((x) => x.key === scope);
  return f ? f.text(v).toLowerCase().includes(q) : true;
}

export interface VendorSortState {
  key: VendorColumnKey;
  dir: "asc" | "desc";
}

export function sortVendors(rows: Vendor[], sort: VendorSortState | null): Vendor[] {
  if (!sort) return rows;
  const dir = sort.dir === "asc" ? 1 : -1;
  const of = (v: Vendor): string | number => {
    switch (sort.key) {
      case "name": return v.name;
      case "erpId": return v.erpVendorId ?? "";
      /* Sorting by address means sorting by PLACE, not by house number — the
         same call the Customers list makes on its merged column. */
      case "address": return `${v.city ?? ""} ${v.state ?? ""}`.trim();
      case "status": return v.active ? 1 : 0;
      case "assigned": return assignedOrderCount(v.id);
      /* EVERY COLUMN SORTS (Pavan, 2026-10-07) — by what the cell prints
         first; an icon column sorts the rows with a note first. */
      case "dispatch": return v.dispatchPhone ?? "";
      case "lines": return v.businessLines[0] ?? "";
      case "serviceArea": return v.serviceStates[0] ?? "";
      case "products": return v.supportedProductIds.length;
      case "rateCard":
        return (v.rateCard.find((l) => l.id === v.defaultRateCardId) ?? v.rateCard[0])?.label ?? "";
      case "instruction": return v.vendorInstruction ? 0 : 1;
      default: return v.name;
    }
  };
  return [...rows].sort((a, b) => {
    const x = of(a);
    const y = of(b);
    if (typeof x === "number" && typeof y === "number") return (x - y) * dir;
    return String(x).localeCompare(String(y)) * dir;
  });
}

/**
 * How many live orders this vendor is carrying.
